import { resolveDeliveryGateMode } from '@/components/board/deliveryGateSettings';
import { DeliveryReadinessPanel } from './DeliveryReadinessPanel';
import { DeliveryExceptionDetails } from './DeliveryExceptionDetails';
import type { ReadinessSpecLocation } from './readinessNavigation';
import { useEffect, useRef, useState } from 'react';
import { RefreshCw } from 'lucide-react';
import { PulseLoader } from '@/components/shared/PulseLoader';
import { useDashboardApi } from '@/services/api';
import { ObligationRefText } from './obligationPresentation';
import type { DeliveryEvidenceProjection } from '@/types/delivery-evidence';
import { isPersistedReadinessProjection, type PersistedReadinessProjection, type ReadinessMetric } from '@/types/delivery-readiness';
import { decisionStatusLabel } from '@/components/specs/DecisionReviewSection';
import { readinessReadMode } from '@/lib/readinessMode';
import { AuthenticatedFetchError } from '@/lib/authFetch';
import { isRetriableReadinessError, ReadinessContractError } from './readinessTransport';
import { TaskRequirementControl } from './TaskRequirementControl';
import { DeliverySummaryPanel } from './DeliverySummaryPanel';

class ReadinessGenerationChangedError extends Error {}

export interface DeliveryEvidencePanelProps {
  boardId: string;
  specId: string;
  revision?: string;
  skipDeliveryEvidence?: boolean;
  onSkipDeliveryEvidenceChange?: (value: boolean) => void;
  onOpenDecisions?: () => void;
  onOpenReadinessSpec?: (location: ReadinessSpecLocation) => void;
  focusExceptionId?: string | null;
  canManageTaskRequirements?: boolean;
}

export function DeliveryEvidencePanel(props: DeliveryEvidencePanelProps) {
  if (readinessReadMode() === 'legacy') return <DeliveryEvidenceDetails {...props} />;
  return <DeliverySummaryPanel key={`${props.boardId}:${props.specId}`} {...props}
    renderDetails={active => <DeliveryEvidenceDetails {...props} active={active} showRequirementControl={false} />} />;
}

function metricLabel(metric?: ReadinessMetric) {
  if (!metric || metric.status === 'unknown') return 'Unknown';
  if (metric.status === 'not_applicable') return 'N/A';
  return `${metric.percent}%`;
}

function unitLabel(state: string, phase: 'implementation' | 'verification') {
  const labels: Record<string, string> = {
    satisfied: phase === 'implementation' ? '✓ Current proof' : '✓ Verified',
    missing: '◌ Pending', partial: '◐ Partial', failed: '✕ Failed',
    stale: '↻ Stale', conflict: '⚠ Conflict', waived: 'Waived · no proof credit',
    not_applicable: 'N/A', unknown: 'Unknown',
  };
  return labels[state] ?? 'Unknown';
}

function ObligationEvidenceDetails({ data, row, currentRow }: {
  data: DeliveryEvidenceProjection; row: DeliveryEvidenceProjection['rows'][number];
  currentRow?: NonNullable<DeliveryEvidenceProjection['current_proof_rows']>[number];
}) {
  const implementationIds = currentRow?.implementation_ids ?? row.implementation_ids;
  const ids = new Set([...implementationIds, ...row.test_ids,
    ...row.implementation_waiver_ids, ...row.test_waiver_ids]);
  return <div className="space-y-4 break-words">
    <section aria-label="Implementation evidence" className="space-y-2">
      <h4 className="font-semibold">Implementation evidence</h4>
      {implementationIds.length === 0 && <p>{currentRow ? 'No current implementation proof.' : 'Current implementation proof unavailable.'}</p>}
      {implementationIds.map(id => {
        const proof = data.implementations.find(item => item.id === id);
        return <div key={id} className="space-y-1 rounded border border-gray-200 p-2 dark:border-gray-700">
          <p className="break-all">Record: {id}</p>
          {proof ? <>
            <p>Card: {proof.card_id}</p><p>Implementation author: {proof.actor_id || 'Not available'}</p><p>{proof.explanation}</p>
            {proof.executions.map(execution => <p key={execution.execution_id} className="break-all">
              {execution.relative_path} · {execution.source_ref} @ {execution.result_revision} · {execution.symbol || execution.execution_id}
              {' · '}{execution.current_accepted_execution ? 'Current accepted execution' : 'Not a current accepted execution'}
            </p>)}
          </> : <p>Record details unavailable in this projection.</p>}
        </div>;
      })}
      {row.implementation_waiver_ids.length > 0 && <p className="break-all">Implementation waivers (not proof): {row.implementation_waiver_ids.join(', ')}</p>}
    </section>
    <section aria-label="Verification evidence" className="space-y-2">
      <h4 className="font-semibold">Verification evidence</h4>
      {row.test_ids.length === 0 && <p>No admitted verification evidence.</p>}
      {row.test_ids.map(id => {
        const proof = data.tests?.find(item => item.id === id);
        return <div key={id} className="space-y-1 rounded border border-gray-200 p-2 dark:border-gray-700">
          <p className="break-all">Record: {id}</p>
          {proof ? <><p>Card: {proof.card_id} · Scenario: {proof.scenario_id}</p>
            <p>Verification author: {proof.actor_id || 'Not available'}</p>
            <p>Result: {proof.result} · {proof.current_verified_run ? 'Current verified run' : 'Current verification not established'}</p></>
            : <p>Record details unavailable in this projection.</p>}
        </div>;
      })}
      {row.test_waiver_ids.length > 0 && <p className="break-all">Verification waivers (not proof): {row.test_waiver_ids.join(', ')}</p>}
    </section>
    {data.records.filter(record => ids.has(record.id)).map(record => <p key={record.id} className="break-all">
      {record.id} · {record.created_at} · Actor: {record.actor_id}{record.revoked ? ' · Revoked' : ''}
      {' · '}{record.payload.justification}
    </p>)}
  </div>;
}

// Spec "Delivery" tab — informational rollup over the linked cards' ledgers
// (mockup sm_5ebd7063). Read-only by design: recording is card-scoped
// (task DoD) and waivers are rollup-level, human-only — this surface only
// presents the aggregated verdict, never mutates it.
export function DeliveryEvidenceDetails({ boardId, specId, revision, skipDeliveryEvidence = false, onSkipDeliveryEvidenceChange, onOpenDecisions, onOpenReadinessSpec, focusExceptionId, canManageTaskRequirements = false, active = true, showRequirementControl = true }: DeliveryEvidencePanelProps & { active?: boolean; showRequirementControl?: boolean }) {
  const api = useDashboardApi();
  const legacyMode = readinessReadMode() === 'legacy';
  const [storedData, setData] = useState<DeliveryEvidenceProjection | null>(null);
  const [dataOwner, setDataOwner] = useState<{ api: typeof api; key: string }>();
  const [gateMode, setGateMode] = useState<'advisory' | 'blocking' | null>(null);
  const [error, setError] = useState('');
  const [reload, setReload] = useState(0);
  const [storedProjection, setProjection] = useState<PersistedReadinessProjection | null>(null);
  const [projectionOwner, setProjectionOwner] = useState<{ api: typeof api; key: string }>();
  const [projectionError, setProjectionError] = useState('');
  const acceptedProjection = useRef<{ api: typeof api; key: string; value: PersistedReadinessProjection }>();
  const [showDetails, setShowDetails] = useState(legacyMode);
  const [showTaskRequirements, setShowTaskRequirements] = useState(false);
  const [taskCards, setTaskCards] = useState<{ api: typeof api; owner: string; cards: Array<{ id: string; title: string }> }>();
  const taskOwner = JSON.stringify([boardId, specId]);
  const scopeKey = JSON.stringify([boardId, specId, revision, reload]);
  const projectionScopeKey = JSON.stringify([boardId, specId, legacyMode]);
  const data = dataOwner?.api === api && dataOwner.key === scopeKey ? storedData : null;
  const projection = projectionOwner?.api === api && projectionOwner.key === projectionScopeKey ? storedProjection : null;

  useEffect(() => {
    if (legacyMode || !active) return;
    const refresh = () => setReload(value => value + 1);
    const visible = () => { if (document.visibilityState === 'visible') refresh(); };
    window.addEventListener('pulse:delivery-evidence-changed', refresh);
    window.addEventListener('focus', refresh);
    document.addEventListener('visibilitychange', visible);
    return () => {
      window.removeEventListener('pulse:delivery-evidence-changed', refresh);
      window.removeEventListener('focus', refresh);
      document.removeEventListener('visibilitychange', visible);
    };
  }, [legacyMode, active]);

  useEffect(() => {
    if (!active) return;
    const controller = new AbortController();
    if (acceptedProjection.current?.api !== api || acceptedProjection.current.key !== projectionScopeKey)
      acceptedProjection.current = undefined;
    setProjection(current => projectionOwner?.api === api && projectionOwner.key === projectionScopeKey
      && current?.projection.generation_id
      ? { ...current, projection: { ...current.projection, freshness: 'updating' } } : null);
    setProjectionError('');
    if (legacyMode) return () => controller.abort();
    let retry = 1000;
    void (async () => {
      while (!controller.signal.aborted) {
        if (document.visibilityState !== 'visible') {
          await new Promise(resolve => setTimeout(resolve, 500));
          continue;
        }
        try {
          let page = await api.getPersistedReadinessProjection(boardId, specId, { unitLimit: 250 }, controller.signal);
          if (!isPersistedReadinessProjection(page) || page.scope.board_id !== boardId || page.scope.spec_id !== specId
            || page.scope.card_id !== null)
            throw new ReadinessContractError('Readiness projection scope mismatch.');
          const rows = [...page.units];
          const seen = new Set<string>();
          while (page.page.has_more) {
            const cursor = page.page.next_cursor;
            if (!cursor || seen.has(cursor)) throw new ReadinessContractError('Readiness page cursor invalid.');
            seen.add(cursor);
            let next: PersistedReadinessProjection;
            try {
              next = await api.getPersistedReadinessProjection(boardId, specId,
                { unitLimit: 250, cursor }, controller.signal);
            } catch (failure) {
              if (failure instanceof AuthenticatedFetchError && failure.status === 409)
                throw new ReadinessGenerationChangedError('Readiness cursor expired. Restarting this view.');
              throw failure;
            }
            if (!isPersistedReadinessProjection(next) || next.scope.board_id !== boardId || next.scope.spec_id !== specId
              || next.scope.card_id !== null) throw new ReadinessContractError('Readiness page scope mismatch.');
            if (next.projection.generation_id !== page.projection.generation_id
              || next.scope.spec_edition !== page.scope.spec_edition
              || next.projection.source_revision !== page.projection.source_revision)
              throw new ReadinessGenerationChangedError('Readiness generation changed. Restarting this view.');
            rows.push(...next.units);
            page = next;
          }
          const previous = acceptedProjection.current?.value;
          if (previous && page.scope.spec_edition !== null && previous.scope.spec_edition !== null
            && (page.scope.spec_edition < previous.scope.spec_edition
              || page.scope.spec_edition === previous.scope.spec_edition
                && page.projection.source_revision !== null && previous.projection.source_revision !== null
                && page.projection.source_revision < previous.projection.source_revision))
            throw new ReadinessGenerationChangedError('Older readiness generation ignored. Retrying current view.');
          if (previous && page.projection.generation_id && previous.projection.generation_id
            && page.scope.spec_edition === previous.scope.spec_edition
            && page.projection.source_revision === previous.projection.source_revision
            && page.projection.evaluated_at && previous.projection.evaluated_at
            && Date.parse(page.projection.evaluated_at) < Date.parse(previous.projection.evaluated_at))
            throw new ReadinessGenerationChangedError('Older readiness generation ignored. Retrying current view.');
          if (!controller.signal.aborted) {
            acceptedProjection.current = { api, key: projectionScopeKey, value: { ...page, units: rows } };
            setProjectionOwner({ api, key: projectionScopeKey });
            setProjection({ ...page, units: rows });
          }
          setProjectionError(''); retry = 1000;
          if (!['updating', 'pending_initial'].includes(page.projection.freshness)) return;
          await new Promise(resolve => setTimeout(resolve, 500));
        } catch (failure) {
          if (controller.signal.aborted) return;
          setProjectionError(failure instanceof Error ? failure.message : 'Readiness projection unavailable.');
          if (failure instanceof ReadinessGenerationChangedError) {
            await new Promise(resolve => setTimeout(resolve, 500));
            continue;
          }
          if (!isRetriableReadinessError(failure)) {
            acceptedProjection.current = undefined;
            setProjection(null);
            return;
          }
          setProjection(current => current?.projection.generation_id
            ? { ...current, projection: { ...current.projection, freshness: 'unavailable', error_code: 'transport_error' } }
            : null);
          await new Promise(resolve => setTimeout(resolve, retry));
          retry = retry === 1000 ? 2000 : 5000;
        }
      }
    })();
    return () => controller.abort();
  }, [api, boardId, specId, revision, reload, projectionScopeKey, legacyMode, active]);

  useEffect(() => {
    if (!active) return;
    const controller = new AbortController();
    setData(null); setGateMode(null); setError('');
    if (showDetails || focusExceptionId || showTaskRequirements) api.getDeliveryEvidence(boardId, specId, controller.signal).then(value => {
      if (value.board_id !== boardId || value.spec_id !== specId) throw new Error('Delivery evidence scope changed. Refresh the Spec.');
      if (!controller.signal.aborted) {
        setDataOwner({ api, key: scopeKey });
        setTaskCards({ api, owner: taskOwner, cards: (value.per_card ?? []).map(card => ({ id: card.card_id, title: card.title })) });
        setData(value);
      }
    }).catch(err => {
      if (!controller.signal.aborted) {
        setError(err instanceof Error ? err.message : 'Delivery proof could not be loaded.');
        if (err instanceof AuthenticatedFetchError && [401, 403, 404].includes(err.status)) setTaskCards(undefined);
      }
    });
    api.getBoard(boardId).then(board => {
      if (!controller.signal.aborted) setGateMode(resolveDeliveryGateMode(board.settings?.delivery_evidence_gate));
    }).catch(() => { if (!controller.signal.aborted) setGateMode(null); });
    return () => controller.abort();
  }, [api, boardId, specId, revision, reload, focusExceptionId, showDetails, showTaskRequirements, scopeKey, taskOwner, active]);

  const missingImplementation = data?.rows.filter(row => !row.not_required && !row.implementation_satisfied).length ?? 0;
  const currentProofRows = new Map((data?.current_proof_rows ?? []).map(row =>
    [`${row.obligation_ref}:${row.semantic_sha256}`, row]));
  const missingTest = data?.rows.filter(row => !row.not_required && !row.test_satisfied && !row.decision_verification_status).length ?? 0;
  const pendingDecisions = data?.rows.filter(row => !row.not_required && row.decision_verification_status && !row.test_satisfied).length ?? 0;
  const notRequired = data?.rows.filter(row => row.not_required).length ?? 0;
  const summary = !data ? '' : data.allowed
    ? notRequired ? `Required delivery checks satisfied · ${notRequired} not required (no proof credit)` : `All ${data.rows.length} obligations satisfied (proof or authorized waiver)`
    : [missingImplementation ? `implementation missing on ${missingImplementation}` : '',
       missingTest ? `test coverage missing on ${missingTest}` : '',
       pendingDecisions ? `${pendingDecisions} decision verification(s) pending` : '']
      .filter(Boolean).join(' · ') + ' obligation' + ((missingImplementation + missingTest) === 1 ? '' : 's');

  return <section className="space-y-5" aria-label="Implementation and verification">
    {showRequirementControl && !showTaskRequirements && <button type="button" className="btn btn-secondary" onClick={() => setShowTaskRequirements(true)}>
      {canManageTaskRequirements ? 'Change task requirements' : 'View task requirements'}
    </button>}
    {showTaskRequirements && (taskCards?.api !== api || taskCards.owner !== taskOwner) && !error && <PulseLoader label="Loading tasks…" size="sm" />}
    {showTaskRequirements && taskCards?.api === api && taskCards.owner === taskOwner && (taskCards.cards.length ? <TaskRequirementControl
      key={`${boardId}:${specId}`} boardId={boardId} specId={specId}
      cards={taskCards.cards}
      initiallyOpen active={active} canEdit={canManageTaskRequirements} revision={revision}
      onChanged={() => setReload(value => value + 1)} /> : <p>No tasks in this Spec.</p>)}
    {focusExceptionId && data?.board_id === boardId && data.spec_id === specId
      && <DeliveryExceptionDetails data={data} recordId={focusExceptionId} />}
    {projection && <DeliveryReadinessPanel active={active} boardId={boardId} specId={specId} revision={`${revision ?? ''}:${reload}`}
      persistedValue={projection} onGenerationMismatch={() => setReload(value => value + 1)}
      onOpenReadinessSpec={onOpenReadinessSpec} />}
    {legacyMode && <DeliveryReadinessPanel active={active} boardId={boardId} specId={specId}
      revision={`${revision ?? ''}:${reload}`} onOpenReadinessSpec={onOpenReadinessSpec} />}
    {!legacyMode && !projection && !projectionError && <PulseLoader label="Loading readiness projection…" size="sm" className="py-4" />}
    {projectionError && <p role="alert" className="text-xs text-amber-700">{projectionError}</p>}
    <p className="text-sm text-gray-500 dark:text-gray-400">Track implementation and verification for each obligation. Expand an item to inspect its evidence.</p>
    <div className="flex flex-wrap items-center justify-between gap-4">
      <div className="flex min-w-0 items-center gap-2">
        {data && (data.allowed
          ? <span className="shrink-0 rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] uppercase tracking-wide text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300">Complete</span>
          : <span className="shrink-0 rounded-full bg-red-100 px-2 py-0.5 text-[10px] uppercase tracking-wide text-red-700 dark:bg-red-900/40 dark:text-red-300">Blocked</span>)}
        {(error || data) && <span className="text-xs text-gray-500 dark:text-gray-400" role="status">
          {error || `${summary} · Edition ${data!.edition}`}
        </span>}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <span className="rounded-full bg-gray-100 px-2 py-0.5 text-[10px] uppercase tracking-wide text-gray-600 dark:bg-gray-800 dark:text-gray-300" data-testid="delivery-gate-mode">
          Gate: {gateMode === null ? 'Unknown' : gateMode === 'advisory' ? 'Advisory' : 'Blocking'} (Board)
        </span>
        <button type="button" onClick={() => setReload(v => v + 1)} aria-label="Refresh delivery rollup"
          className="inline-flex h-9 shrink-0 items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white px-3 text-xs font-medium text-gray-700 shadow-sm transition-colors hover:bg-gray-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700">
          <RefreshCw size={14} /> Refresh
        </button>
      </div>
    </div>

      {showDetails && !data && !error && <PulseLoader label="Loading delivery details…" size="sm" className="py-6" />}
      <div className="flex items-center justify-between gap-3 rounded-lg border border-gray-200 bg-gray-50/50 px-3 py-2 dark:border-gray-700 dark:bg-gray-700/20">
        <div className="min-w-0">
          <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip delivery evidence requirement</span>
          <p className="text-[10px] text-gray-700 dark:text-gray-300">Allow moving spec to Done without complete delivery proof — the coverage verdict stays visible. Waivers (per obligation) remain human-only.</p>
        </div>
        {onSkipDeliveryEvidenceChange ? (
          <button
            type="button"
            role="switch"
            aria-checked={skipDeliveryEvidence}
            aria-label="Skip delivery evidence requirement"
            data-testid="delivery-skip-toggle"
            onClick={() => onSkipDeliveryEvidenceChange(!skipDeliveryEvidence)}
            className={`relative h-5 w-10 shrink-0 rounded-full transition-colors ${skipDeliveryEvidence ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}
          >
            <span className={`absolute left-0.5 top-0.5 h-4 w-4 rounded-full bg-white transition-transform ${skipDeliveryEvidence ? 'translate-x-5' : ''}`} />
          </button>
        ) : (
          <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] uppercase tracking-wide ${skipDeliveryEvidence ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300'}`}>
            {skipDeliveryEvidence ? 'Skipped' : 'Active'}
          </span>
        )}
      </div>

    {data && data.status === 'done' && !data.allowed && (
      <p className="rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-xs text-gray-500 dark:border-gray-800 dark:bg-gray-900/40 dark:text-gray-400">
        This completed Spec has not been reopened. Missing proof may have been recorded retrospectively or waived by an authorized human.
      </p>
    )}

    {!legacyMode && <div>
      <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-gray-700 dark:text-gray-300">Coverage by obligation</h3>
      {projection && <p className="mb-2 text-xs text-gray-500" role="status">
        {projection.projection.freshness === 'current' ? 'Current' : projection.projection.freshness === 'updating'
          ? 'Updating · previous coherent generation' : projection.projection.freshness === 'pending_initial'
            ? 'Waiting for calculation' : 'Calculation unavailable'}
        {projection.projection.generation_id ? ` · Generation ${projection.projection.generation_id}` : ''}
        {' · '}Implementation {metricLabel(projection.summaries.find(row => row.card_id === null)?.implementation)}
        {' · '}Verification {metricLabel(projection.summaries.find(row => row.card_id === null)?.verification)}
      </p>}
      {projection?.projection.generation_id && <div className="overflow-x-auto"><table className="w-full text-sm" data-testid="delivery-coverage-table">
        <thead><tr className="border-b text-left text-xs text-gray-500"><th scope="col">Obligation</th>
          <th scope="col">Implementation</th><th scope="col">Verification</th></tr></thead>
        <tbody>{projection.units.filter(unit => unit.card_id === null && unit.kind === 'obligation').map(unit =>
          <tr key={`${unit.ref}:${unit.semantic_sha256}`} className="border-b border-gray-100 dark:border-gray-800">
            <td className="py-2 pr-4"><ObligationRefText value={unit.ref} /></td>
            <td className="py-2" title={unit.implementation_reason_codes.join(', ')}>{unitLabel(unit.implementation_state, 'implementation')}</td>
            <td className="py-2" title={unit.verification_reason_codes.join(', ')}>{unitLabel(unit.verification_state, 'verification')}</td>
          </tr>)}</tbody>
      </table></div>}
    </div>}
    <button type="button" className="btn btn-secondary text-xs" onClick={() => setShowDetails(value => !value)}>
      {showDetails ? 'Hide detailed evidence' : 'Show detailed evidence'}
    </button>

    {showDetails && data && <>
      <div>
        <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-gray-700 dark:text-gray-300">Detailed evidence by obligation</h3>
        <p className="mb-2 text-xs text-gray-500 dark:text-gray-400">Implementation marks use the same current proof assessment as the percentage above. Delivery qualification also requires its contributing Cards to reach Done.</p>
        <div className="overflow-x-auto">
          <table className="w-full text-sm" data-testid="delivery-detailed-coverage-table">
            <thead>
              <tr className="border-b border-gray-100 text-left text-xs text-gray-400 dark:border-gray-800">
                <th scope="col" className="py-1 pr-4">Obligation</th>
                <th scope="col" className="px-2">Implementation</th>
                <th scope="col" className="px-2">Verification</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
              {data.rows.map(row => {
                const ref = row.obligation.binding.obligation_ref;
                const waivedImpl = row.implementation_waiver_ids.length > 0;
                const waivedTest = row.test_waiver_ids.length > 0;
                const decision = !!row.decision_verification_status;
                const currentProof = currentProofRows.get(`${ref}:${row.obligation.binding.semantic_sha256}`);
                return <tr key={ref}>
                  <td className="min-w-0 py-1.5 pr-4 text-gray-700 dark:text-gray-200">
                    <details className="group py-2">
                    <summary className="cursor-pointer rounded font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500">{row.obligation.title}</summary>
                    <div className="mt-3 space-y-3 rounded-lg bg-gray-50 p-3 text-xs dark:bg-gray-800/50">
                    <ObligationRefText value={ref} />
                    {!decision && row.required_card_ids && <p className="text-xs">{row.required_card_ids.length} planned implementation Card(s)</p>}
                    {Boolean(row.missing_card_ids?.length) && <p className="text-xs text-amber-600 dark:text-amber-400">Pending implementation Cards: {row.missing_card_ids!.slice(0, 20).join(', ')}{row.missing_card_ids!.length > 20 ? ' (additional Cards omitted)' : ''}</p>}
                    {row.missing_criteria?.slice(0, 20).map(([implementation, criterion]) => <p key={JSON.stringify([implementation, criterion])} className="text-xs text-amber-600 dark:text-amber-400">Implementation {implementation}: missing verification of {criterion}</p>)}
                    {(row.missing_criteria?.length ?? 0) > 20 && <p className="text-xs">Additional criterion gaps are omitted from this summary.</p>}
                    <p className="break-all text-gray-500">Semantic revision: {row.obligation.binding.semantic_sha256}</p>
                    {decision ? <div className="space-y-2"><p>{decisionStatusLabel(row.decision_verification_status!)}</p>
                      <p>Adherence reuses selected obligation evidence and any required inspection. No separate implementation Card is required.</p>
                      {onOpenDecisions && <button type="button" className="btn btn-secondary text-xs" onClick={onOpenDecisions}>Review in Decisions</button>}
                    </div> : <ObligationEvidenceDetails data={data} row={row} currentRow={currentProof} />}
                    </div>
                    </details>
                  </td>
                  <td className="px-2 text-xs" title={decision ? 'Decisions do not require their own implementation' : 'Current proof and delivery qualification are separate stages'}>
                    {decision ? <span className="text-gray-500">Not applicable</span> : <div className="space-y-1">
                      <div className={currentProof?.implementation_satisfied ? 'text-green-600 dark:text-green-400' : 'text-amber-600 dark:text-amber-400'}>
                        {currentProof ? currentProof.implementation_satisfied ? '✓ Current proof' : '◌ Current proof missing' : 'Current proof unavailable'}
                      </div>
                      <div className={row.implementation_satisfied && !waivedImpl ? 'text-green-600 dark:text-green-400' : 'text-amber-600 dark:text-amber-400'}>
                        {waivedImpl ? 'Waived' : row.implementation_satisfied ? <><span>✓</span> Delivery qualified</> : <><span>◌</span> Delivery pending</>}
                      </div>
                    </div>}
                  </td>
                  <td className="px-2 text-green-600 dark:text-green-400" title={waivedTest ? 'Explicitly waived — human authorization' : row.test_satisfied ? 'Current passing evidence for this obligation' : 'Missing / stale'}>
                    {decision ? <span className="text-xs">{decisionStatusLabel(row.decision_verification_status!)}</span> : waivedTest ? <span className="text-xs text-amber-600 dark:text-amber-400">Waived</span> : row.test_satisfied ? '✓' : <span className="text-amber-500">◌</span>}
                  </td>
                </tr>;
              })}
            </tbody>
          </table>
        </div>
      </div>

      {data.per_card && data.per_card.length > 0 && (
        <div>
          <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-gray-700 dark:text-gray-300">Per card</h3>
          <div className="space-y-2">
            {data.per_card.map(card => {
              const proven = card.obligations.filter(o => o.implementation_satisfied).length;
              const isTest = card.card_type === 'test';
              return <div key={card.card_id} className="flex items-center justify-between rounded-md border border-gray-200 p-3 dark:border-gray-800" data-testid={`delivery-card-${card.card_id}`}>
                <div className="min-w-0">
                  <div className="truncate text-sm font-medium text-gray-700 dark:text-gray-200">{card.title}</div>
                  <div className="text-xs text-gray-400 dark:text-gray-500">
                    {isTest
                      ? 'Test card · records authenticated outcomes; delivery requires current passing evidence for every required criterion'
                      : card.obligations.length === 0
                        ? 'No derived obligations'
                        : proven === card.obligations.length
                          ? `${proven} obligation${proven === 1 ? '' : 's'} with delivery-qualified proof`
                          : `${proven}/${card.obligations.length} obligations with delivery-qualified proof · ${card.obligations.length - proven} pending qualification`}
                  </div>
                </div>
                <span className={`shrink-0 text-xs font-medium ${isTest ? 'text-gray-400 dark:text-gray-500' : card.satisfied ? 'text-green-600 dark:text-green-400' : 'text-amber-600 dark:text-amber-400'}`}>
                  {isTest ? 'Verification gate' : card.satisfied ? 'Implementation proven' : 'Implementation pending'}
                </span>
              </div>;
            })}
          </div>
        </div>
      )}

      <p className="text-xs text-gray-400 dark:text-gray-500">
        Waivers are recorded at rollup level and require human authorization. Proof is recorded on each task or test card.
      </p>
    </>}
  </section>;
}

import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { useDashboardApi } from '@/services/api';
import { useCurrentBoard } from '@/store/dashboard';
import { AuthenticatedFetchError } from '@/lib/authFetch';
import { PulseLoader } from '@/components/shared/PulseLoader';
import { isDeliverySummary, type DeliveryGroup, type DeliveryReason, type DeliverySummary, type DeliveryTaskGroup } from '@/types/delivery-summary';
import { TaskRequirementControl } from './TaskRequirementControl';
import { ContextualHelpLink } from '@/components/help/ContextualHelpLink';
import type { DeliveryEvidencePanelProps } from './DeliveryEvidencePanel';

const labels: Record<DeliveryGroup, string> = { delivered: 'Delivered', in_progress: 'In progress', pending: 'Pending', optional_or_waived: 'Optional / Waived' };
const reasons: Record<DeliveryReason, string> = { delivered: 'Delivered', in_progress: 'Work in progress', not_started: 'Not started',
  awaiting_validation: 'Awaiting validation', paused: 'On hold', needs_rework: 'Rework required', cancelled: 'Cancelled',
  awaiting_dependency: 'Waiting for a dependency', awaiting_confirmation: 'Completion awaiting confirmation',
  updating: 'Completion awaiting an updated check', unavailable: 'Status not yet confirmed', optional: 'Optional', waived: 'Waived' };
const button = 'btn btn-secondary text-xs';
type Selection = Array<{ id: string; title: string }>;

export function DeliverySummaryPanel({ boardId, specId, revision, focusExceptionId, canManageTaskRequirements = false, renderDetails }:
  DeliveryEvidencePanelProps & { renderDetails: (active: boolean) => ReactNode }) {
  const api = useDashboardApi();
  const board = useCurrentBoard();
  const sectionId = useId();
  const [refresh, setRefresh] = useState(0);
  const owner = JSON.stringify([boardId, specId, revision, refresh]);
  const [stored, setStored] = useState<{ api: typeof api; owner: string; value: DeliverySummary }>();
  const summary = stored?.api === api && stored.owner === owner ? stored.value : undefined;
  const latest = useRef(summary);
  latest.current = summary;
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [detailsBlocked, setDetailsBlocked] = useState(false);
  const [pageError, setPageError] = useState('');
  const [busyGroup, setBusyGroup] = useState<DeliveryGroup>();
  const [optionalOpen, setOptionalOpen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(Boolean(focusExceptionId));
  const [detailsMounted, setDetailsMounted] = useState(Boolean(focusExceptionId));
  const [selecting, setSelecting] = useState(false);
  const [selection, setSelection] = useState<Selection>([]);
  const [editing, setEditing] = useState<Selection>();
  const [editorVersion, setEditorVersion] = useState(0);
  const editorRoot = useRef<HTMLDivElement>(null);
  const focusAcceptedDecision = useRef(false);
  const pageRequest = useRef<AbortController>();

  useEffect(() => {
    if (focusExceptionId) { setDetailsMounted(true); setDetailsOpen(true); }
  }, [focusExceptionId]);

  useEffect(() => { if (editing) editorRoot.current?.focus(); }, [editorVersion]);
  useEffect(() => {
    if (summary && focusAcceptedDecision.current) {
      editorRoot.current?.focus(); focusAcceptedDecision.current = false;
    }
  }, [summary]);

  useEffect(() => {
    const reload = () => setRefresh(value => value + 1);
    const visible = () => { if (document.visibilityState === 'visible') reload(); };
    window.addEventListener('pulse:delivery-evidence-changed', reload);
    window.addEventListener('focus', reload);
    document.addEventListener('visibilitychange', visible);
    return () => {
      window.removeEventListener('pulse:delivery-evidence-changed', reload);
      window.removeEventListener('focus', reload);
      document.removeEventListener('visibilitychange', visible);
    };
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    pageRequest.current?.abort(); setBusyGroup(undefined); setPageError('');
    setStored(undefined); setLoading(true); setError(''); setDetailsBlocked(false);
    // Initial read plus bounded backoff while the native worker is updating.
    // Focus, domain events and Refresh start a fresh read after this budget.
    void (async () => {
      for (const delay of [0, 1000, 2000, 5000]) {
        if (delay) await new Promise<void>(resolve => {
          const timer = setTimeout(resolve, delay);
          controller.signal.addEventListener('abort', () => { clearTimeout(timer); resolve(); }, { once: true });
        });
        if (controller.signal.aborted || delay && document.visibilityState !== 'visible') return;
        try {
          const value = await api.getDeliverySummary(boardId, specId, {}, controller.signal);
          if (!isDeliverySummary(value) || value.scope.board_id !== boardId || value.scope.spec_id !== specId)
            throw new Error('Delivery status could not be confirmed. Refresh to try again.');
          if (controller.signal.aborted) return;
          setStored({ api, owner, value }); setLoading(false); setError('');
          if (!['pending_initial', 'updating'].includes(value.projection.freshness)) return;
        } catch (failure) {
          if (controller.signal.aborted) return;
          setStored(undefined); setLoading(false);
          setDetailsBlocked(failure instanceof AuthenticatedFetchError && [401,403,404].includes(failure.status));
          setError(failure instanceof AuthenticatedFetchError && [401,403,404].includes(failure.status)
            ? 'Delivery status is unavailable with your current access.' : 'Delivery status could not be loaded. Refresh to try again.');
          return;
        }
      }
    })();
    return () => { controller.abort(); pageRequest.current?.abort(); };
  }, [api, boardId, specId, revision, refresh, owner]);

  async function loadGroup(group: DeliveryTaskGroup) {
    const base = latest.current;
    if (!base || pageRequest.current && !pageRequest.current.signal.aborted || group.loaded && !group.has_more) return;
    const controller = new AbortController(); pageRequest.current = controller;
    setBusyGroup(group.id); setPageError('');
    try {
      const value = await api.getDeliverySummary(boardId, specId,
        { group: group.id, limit: 10, ...(group.loaded ? { cursor: group.next_cursor! } : {}) }, controller.signal);
      if (controller.signal.aborted) return;
      if (!isDeliverySummary(value) || value.scope.board_id !== boardId || value.scope.spec_id !== specId)
        throw new Error('Invalid delivery page');
      if (latest.current?.population_id !== base.population_id || value.population_id !== base.population_id)
        throw new Error('Delivery population changed');
      if (JSON.stringify(value.scope) !== JSON.stringify(base.scope)
        || JSON.stringify(value.projection) !== JSON.stringify(base.projection)
        || value.complete !== base.complete || value.task_count !== base.task_count
        || value.required_task_count !== base.required_task_count || value.unique_obligation_count !== base.unique_obligation_count
        || value.groups.some((row,index) => row.count !== base.groups[index].count || row.id !== group.id && row.loaded))
        throw new Error('Delivery page changed its population');
      const next = value.groups.find(row => row.id === group.id)!;
      if (!next.loaded) throw new Error('Requested group was not loaded');
      const existingIds = new Set(base.groups.flatMap(row => row.items.map(task => task.card_id)));
      if (next.items.some(task => existingIds.has(task.card_id)) || next.has_more && next.next_cursor === group.next_cursor)
        throw new Error('Delivery page repeated');
      const merged = { ...base, groups: base.groups.map(row => row.id === group.id
        ? { ...next, items: [...row.items, ...next.items] } : row) };
      setStored({ api, owner, value: merged });
    } catch (failure) {
      if (controller.signal.aborted) return;
      if (failure instanceof AuthenticatedFetchError && [401,403,404].includes(failure.status)) {
        setStored(undefined); setDetailsBlocked(true); setError('Delivery status is unavailable with your current access.');
      } else setPageError('Tasks changed or this page is unavailable. Refresh the delivery status before continuing.');
    } finally {
      if (!controller.signal.aborted) setBusyGroup(undefined);
      if (pageRequest.current === controller) pageRequest.current = undefined;
    }
  }

  // Opening exceptions loads only that section. A complete zero count needs no GET.
  useEffect(() => {
    if (!optionalOpen || !summary) return;
    const group = summary.groups[3];
    if (!group.loaded && group.count !== 0 && !busyGroup && !pageError) void loadGroup(group);
  }, [optionalOpen, summary, busyGroup, pageError]);

  function edit(cards: Selection) {
    setEditing(cards); setEditorVersion(value => value + 1); setSelecting(false);
  }
  function responsible(id: string | null) {
    if (!id) return 'Unassigned';
    if (board?.id !== boardId) return 'Assigned';
    if (id === board.owner_id) return 'Board owner';
    return board.agents.find(agent => agent.id === id)?.name ?? 'Assigned';
  }
  function list(group: DeliveryTaskGroup) {
    return <div className="space-y-3">
      {!group.items.length && (group.count === 0 ? <p className="text-sm text-gray-500">No tasks.</p>
        : group.loaded ? <p className="text-sm text-gray-500">Status not yet confirmed.</p>
          : <p className="text-sm text-gray-500">{busyGroup === group.id ? 'Loading tasks…' : 'Task list is not loaded.'}</p>)}
      <ul className="space-y-2">
        {group.items.map(task => <li key={task.card_id} className="space-y-2 rounded-lg border border-gray-200 p-3 dark:border-gray-700">
          <div className="flex items-start gap-3">
            {selecting && <input type="checkbox" aria-label={`Select ${task.title}`}
              checked={selection.some(item => item.id === task.card_id)}
              disabled={selection.length >= 50 && !selection.some(item => item.id === task.card_id)}
              onChange={event => setSelection(items => event.target.checked
                ? [...items, { id: task.card_id, title: task.title }] : items.filter(item => item.id !== task.card_id))} />}
            <div className="min-w-0 flex-1 break-words"><p className="font-medium text-gray-900 dark:text-white">{task.title}</p>
              <p className="text-sm text-gray-600 dark:text-gray-300">{reasons[task.reason]}</p>
              {task.exception_applied && <p className="text-xs text-amber-700 dark:text-amber-300">Exception applied</p>}
              <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">{responsible(task.assignee_id)}
                {task.updated_at && <> · Updated <time dateTime={task.updated_at}>{new Date(task.updated_at).toLocaleString()}</time></>}</p>
            </div>
          </div>
          <button type="button" className={button} onClick={() => edit([{ id: task.card_id, title: task.title }])}>
            {canManageTaskRequirements ? 'Change requirement' : 'View requirement'}<span className="sr-only"> for {task.title}</span>
          </button>
        </li>)}
      </ul>
      {group.has_more && <button type="button" className={button} disabled={Boolean(busyGroup)} onClick={() => void loadGroup(group)}>
        {busyGroup === group.id ? 'Loading…' : `Load more ${labels[group.id].toLowerCase()} tasks`}
      </button>}
    </div>;
  }

  return <section aria-label="Delivery status" className="space-y-5">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div><h3 className="text-lg font-semibold text-gray-900 dark:text-white">Delivery</h3>
        <p className="text-sm text-gray-500 dark:text-gray-400">What has been delivered, what is in progress and what is pending.</p>
        <ContextualHelpLink sectionId="delivery-status" className="mt-2 text-xs">How delivery status works</ContextualHelpLink></div>
      <button type="button" className={button} disabled={loading} onClick={() => setRefresh(value => value + 1)}>Refresh delivery status</button>
    </div>
    {loading && <PulseLoader label="Loading delivery status…" size="sm" />}
    {error && <p role="alert" className="text-sm text-amber-700 dark:text-amber-300">{error}</p>}
    {editing && <div ref={editorRoot} tabIndex={-1} role="group" aria-label="Selected task requirements" hidden={!summary || Boolean(error)}>
      <TaskRequirementControl key={editorVersion} boardId={boardId} specId={specId}
        cards={editing} initiallyOpen initiallySelected active={Boolean(summary) && !error}
        canEdit={canManageTaskRequirements} revision={revision}
        onChanged={() => { focusAcceptedDecision.current = true; setRefresh(value => value + 1); }} />
    </div>}
    {summary && <>
      {!summary.complete && <p role="status" className="text-sm text-gray-500 dark:text-gray-400">
        {summary.projection.freshness === 'pending_initial' ? 'Delivery status is being prepared.'
          : summary.projection.freshness === 'unavailable' ? 'Delivery status could not be confirmed.'
            : 'Delivery status is updating. Completion and task counts are not yet confirmed.'} Refresh in a moment.
      </p>}
      {summary.complete && summary.task_count === 0 && <p>No tasks in this Spec.</p>}
      <button type="button" className={button} aria-pressed={selecting} onClick={() => setSelecting(value => !value)}>
        {canManageTaskRequirements ? 'Change task requirements' : 'View task requirements'}
      </button>
      {selecting && <div className="space-y-2">
        <p className="text-sm">Select up to 50 tasks. Load more to find another task.</p>
        <button type="button" className={button} disabled={!selection.length} onClick={() => edit(selection)}>
          Continue with {selection.length} selected
        </button>
      </div>}
      <div className="grid gap-4 lg:grid-cols-3">
        {summary.groups.slice(0,3).map(group => <section key={group.id} aria-label={labels[group.id]}
          className="min-w-0 space-y-3 rounded-xl bg-gray-50 p-3 dark:bg-gray-800/40">
          <h4 className="font-semibold text-gray-800 dark:text-gray-100">{labels[group.id]}{group.count !== null && ` (${group.count})`}</h4>
          {list(group)}
        </section>)}
      </div>
      <details open={optionalOpen} onToggle={event => setOptionalOpen(event.currentTarget.open)}
        className="rounded-lg border border-gray-200 p-3 dark:border-gray-700">
        <summary className="cursor-pointer rounded font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500">
          Optional / Waived{summary.groups[3].count !== null && ` (${summary.groups[3].count})`}
        </summary>
        {optionalOpen && <div className="mt-3 space-y-3"><p className="text-sm text-gray-500">Not required for delivery. This does not count as delivered work.</p>{list(summary.groups[3])}</div>}
      </details>
      {pageError && <p role="alert" className="text-sm text-amber-700 dark:text-amber-300">{pageError}</p>}
    </>}
    <button type="button" className={`${button} disabled:opacity-50`} disabled={detailsBlocked} aria-expanded={detailsOpen} aria-controls={`${sectionId}-details`}
      onClick={() => { setDetailsMounted(true); setDetailsOpen(value => !value); }}>{detailsOpen ? 'Hide Details' : 'Details'}</button>
    {detailsMounted && <div id={`${sectionId}-details`} hidden={!detailsOpen || detailsBlocked}>
      {renderDetails(detailsOpen && !detailsBlocked)}
    </div>}
  </section>;
}

import { useEffect, useId, useRef, useState } from 'react';
import { useDashboardApi } from '@/services/api';
import { AuthenticatedFetchError } from '@/lib/authFetch';
import { ContextualHelpLink } from '@/components/help/ContextualHelpLink';
import type { TaskRequirementChoice, TaskRequirementInput, TaskRequirementOptions } from '@/types/task-requirement';
import { TaskRequirementHistory } from './TaskRequirementHistory';
import { requirementLabels } from './taskRequirementLabels';

interface Props {
  boardId: string; specId: string; cards: Array<{ id: string; title: string }>;
  active?: boolean; canEdit?: boolean; initiallyOpen?: boolean; initiallySelected?: boolean; revision?: string | number; onChanged?: () => void;
}

// Mount with a board/spec key. Options are fetched only while editing an exact
// selection; a changed server basis never replaces a human draft silently.
export function TaskRequirementControl({ boardId, specId, cards, active = true, canEdit = true, initiallyOpen = false, initiallySelected = false, revision, onChanged }: Props) {
  const api = useDashboardApi();
  const headingId = useId();
  const [open, setOpen] = useState(initiallyOpen);
  const [selected, setSelected] = useState<string[]>(initiallySelected ? cards.map(card => card.id) : cards.length === 1 ? [cards[0].id] : []);
  const [choice, setChoice] = useState<TaskRequirementChoice | ''>('');
  const [note, setNote] = useState('');
  const [options, setOptions] = useState<TaskRequirementOptions | null>(null);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [refresh, setRefresh] = useState(0);
  const [stale, setStale] = useState(false);
  const [uncertain, setUncertain] = useState<TaskRequirementInput | null>(null);
  const [requestedRevision, setRequestedRevision] = useState(revision);
  const [historyOpen, setHistoryOpen] = useState<Record<string, boolean>>({});
  const alive = useRef(true);
  const selectionKey = JSON.stringify(selected);
  const basisChanged = requestedRevision !== revision;

  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  useEffect(() => {
    if (!open || !active || !selected.length || basisChanged) return;
    const controller = new AbortController();
    setLoading(true); setOptions(null); setError(''); setStale(false);
    api.getTaskRequirementOptions(boardId, specId, selected, controller.signal).then(value => {
      if (controller.signal.aborted) return;
      if (value.contract_version !== 'task-requirement-options/v1'
        || value.board_id !== boardId || value.spec_id !== specId
        || JSON.stringify(value.cards.map(card => card.card_id).sort()) !== JSON.stringify([...selected].sort())) {
        throw new Error('Current task requirements could not be confirmed.');
      }
      setOptions(value);
    }).catch(err => {
      if (!controller.signal.aborted) setError(err instanceof Error ? err.message : 'Task requirements could not be loaded.');
    }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  // Selection identity is a value, rather than the caller's array identity.
  }, [api, boardId, specId, open, active, selectionKey, requestedRevision, basisChanged, refresh]);

  async function save() {
    if (busy || !active) return;
    if (!uncertain && (!canEdit || !options?.can_apply || loading || stale || basisChanged || !choice || !options.allowed_decisions.includes(choice))) return;
    const request: TaskRequirementInput = uncertain ?? {
      contract_version: 'task-requirement-decision/v1', card_ids: [...selected],
      decision: choice as TaskRequirementChoice, basis: options!.basis,
      note: note.trim() || null, idempotency_key: crypto.randomUUID(),
    };
    setBusy(true); setError('');
    try {
      const result = await api.applyTaskRequirementDecision(boardId, specId, request);
      if (result.contract_version !== 'task-requirement-operation/v1' || result.status !== 'applied'
        || result.decision !== request.decision
        || JSON.stringify([...result.affected_cards].sort()) !== JSON.stringify([...request.card_ids].sort())) {
        throw new Error('The decision response could not be confirmed.');
      }
      if (!alive.current) return;
      setUncertain(null); setOptions(null); setOpen(false); setChoice(''); setNote('');
      setNotice(result.replayed ? 'The original decision was saved. Review current requirements before making another change.' : 'Task requirement saved. Work status and proof are unchanged.');
      onChanged?.();
    } catch (err) {
      if (!alive.current) return;
      if (err instanceof AuthenticatedFetchError && [400, 401, 403, 404, 409, 422].includes(err.status)) {
        setUncertain(null); setStale(true);
        if ([401, 403, 404].includes(err.status)) setOptions(null);
        setError(err.status === 409 ? 'The task requirements changed or this draft conflicts with an earlier operation. Review the latest requirements; your note and choice are preserved.' : err.message);
      } else {
        setUncertain(request);
        setError('The response is uncertain. Retry the same decision before making another change.');
      }
    } finally { if (alive.current) setBusy(false); }
  }

  const locked = busy || Boolean(uncertain);
  return <section aria-label="Task requirement" className="space-y-3 rounded-lg border border-gray-200 p-4 dark:border-gray-700">
    <div className="flex flex-wrap items-center justify-between gap-3">
      <button type="button" className="btn btn-secondary" aria-expanded={open} aria-controls={headingId}
        disabled={!active || locked} onClick={() => { setOpen(value => !value); setRequestedRevision(revision); setNotice(''); }}>
        {open ? 'Close task requirement' : canEdit ? 'Change task requirement' : 'View task requirement'}
      </button>
      <ContextualHelpLink sectionId="task-requirements">Task requirement rules</ContextualHelpLink>
    </div>
    {notice && <p role="status" className="text-sm">{notice}</p>}
    {open && <form id={headingId} className="space-y-3" onSubmit={event => { event.preventDefault(); void save(); }}>
      <p className="text-sm text-gray-600 dark:text-gray-300">{canEdit ? 'Choose Required, Optional or Waived. A note is optional. ' : ''}This is the delivery requirement for this Spec edition; work status and evidence stay unchanged.</p>
      <fieldset disabled={locked || !active} className="space-y-2">
        <legend className="text-sm font-medium">Tasks (up to 50)</legend>
        {cards.map(card => {
          const current = options?.cards.find(row => row.card_id === card.id);
          return <div key={card.id} className="space-y-1">
          <label className="flex items-start gap-2 text-sm">
          <input type="checkbox" aria-label={card.title} checked={selected.includes(card.id)} disabled={!selected.includes(card.id) && selected.length >= 50}
            onChange={event => { setSelected(ids => event.target.checked ? [...ids, card.id] : ids.filter(id => id !== card.id)); setRequestedRevision(revision); setOptions(null); setNotice(''); }} />
          <span className="min-w-0 flex-1">{card.title}</span>
          {current && <span className="rounded bg-gray-100 px-2 py-0.5 text-xs dark:bg-gray-800">{requirementLabels[current.decision]}</span>}
          </label>
          {current && <div className="ml-5 text-sm">
            {!current.mutable && <p>Reopen this task before changing its requirement.</p>}
            <details onToggle={event => { const isOpen = event.currentTarget.open; setHistoryOpen(value => ({ ...value, [card.id]: isOpen })); }}>
              <summary aria-label={`Decision history for ${card.title}`} className="cursor-pointer">Details · Decision history</summary>
              {historyOpen[card.id] && <TaskRequirementHistory key={`${boardId}:${specId}:${card.id}`} boardId={boardId} specId={specId} cardId={card.id} />}
            </details>
          </div>}
          </div>;
        })}
      </fieldset>
      {loading && !basisChanged && <p role="status" className="text-sm">Loading task requirements…</p>}
      {basisChanged && <p role="alert" className="text-sm">The task or Spec changed. Review the latest requirements before saving. Your note and choice are preserved.</p>}
      {options && <>
        {!options.allowed_decisions.length && <p className="text-sm">Only an authorized human can change these requirements.</p>}
        {options.effects.dependent_tasks.length > 0 && <p className="text-sm">Dependencies stay unchanged. Dependent tasks: {options.effects.dependent_tasks.map(card => card.title).join(', ')}.</p>}
        {options.effects.test_scenarios_remain_governed && <p className="text-sm">Test task decisions change execution responsibility only. Required scenarios for other tasks and the Spec still need verification.</p>}
      </>}
      {(canEdit && Boolean(options?.allowed_decisions.length) || uncertain) && <><label className="block text-sm">Requirement
        <select className="mt-1 w-full rounded border bg-white p-2 dark:bg-gray-900" value={choice} disabled={locked || !active || !options?.can_apply || loading || stale || basisChanged}
          onChange={event => setChoice(event.target.value as TaskRequirementChoice | '')}>
          <option value="">Select a requirement…</option>
          {(['required', 'optional', 'waived'] as const).filter(value => options?.allowed_decisions.includes(value) || value === choice)
            .map(value => <option key={value} value={value}>{requirementLabels[value]}</option>)}
        </select>
      </label>
      <label className="block text-sm">Note (optional)
        <textarea className="mt-1 w-full rounded border bg-white p-2 dark:bg-gray-900" value={note} maxLength={20000} disabled={locked || !active}
          onChange={event => setNote(event.target.value)} />
      </label></>}
      {error && <p role="alert" className="text-sm text-amber-700 dark:text-amber-300">{error}</p>}
      {!uncertain && (error || stale || basisChanged) && <button type="button" className="btn btn-secondary" disabled={busy || (loading && !basisChanged) || !selected.length || !active}
        onClick={() => { setRequestedRevision(revision); setRefresh(value => value + 1); }}>Review latest task requirements</button>}
      {canEdit && <button type="submit" className="btn btn-primary disabled:cursor-not-allowed disabled:opacity-50" disabled={!active || busy || (!uncertain && (loading || stale || basisChanged || !options?.can_apply || !choice || !options.allowed_decisions.includes(choice)))}>
        {busy ? 'Saving…' : uncertain ? 'Retry same decision' : 'Save task requirement'}
      </button>}
    </form>}
  </section>;
}

