/** Resolve an actor ID to a display name using the members list. */
function resolveActorName(id: string | null | undefined, members: { id: string; name: string }[]): string {
  if (!id) return 'Unknown';
  const member = members.find(m => m.id === id);
  if (member) return member.name;
  // Fallback: if it looks like a user ID, show a short label
  if (id.startsWith('user_')) return 'User';
  if (id.includes('@')) return id.split('@')[0];
  return id.length > 16 ? id.slice(0, 12) + '…' : id;
}

function shortId(id: string): string {
  return id.length > 16 ? id.slice(0, 12) + '…' : id;
}

function humanizeEvidenceToken(value: string): string {
  return value.replace(/[_-]+/g, ' ').replace(/^./, (character) => character.toUpperCase());
}

function cardTypeLabel(card: Pick<Card, 'card_type'> | null | undefined): string {
  if (card?.card_type === 'bug') return 'Bug';
  if (card?.card_type === 'test') return 'Test';
  return 'Task';
}

function preserveProjectedOpenQACount(
  updated: Card,
  existing: Pick<Card, 'open_qa_count'> | undefined,
): Card {
  if (
    updated.open_qa_count !== undefined
    || existing?.open_qa_count === undefined
  ) {
    return updated;
  }
  return { ...updated, open_qa_count: existing.open_qa_count };
}

type CardTestsTab = Extract<
  CardModalSubtab,
  'regression' | 'coverage' | 'amendment' | 'scenarios' | 'evidence'
>;
type CardReferencesTab = Extract<
  CardModalSubtab,
  'lineage' | 'requirements' | 'dependencies' | 'project-structure'
>;
type CardValidationTab = Extract<
  CardModalSubtab,
  'execution-report' | 'task-validation' | 'policy-compliance'
>;

const TEST_EVIDENCE_FIELDS: Array<keyof TestScenarioEvidence> = [
  'test_file_path',
  'test_function',
  'last_run_at',
  'test_run_id',
  'output_snippet',
  // Re-executable evidence contract (spec 9e0bf979): evidence may carry only
  // these fields (e.g. a replay_command + expected_output_snapshot), so they
  // must count as "has evidence" for rendering.
  'evidence_class',
  'replay_command',
  'manifest_ref',
  'execution_attestation',
  'manual_checklist_ref',
  'expected_output_snapshot',
  'non_replayable_justification',
];

function getScenarioEvidence(scenario: TestScenario): TestScenarioEvidence | null {
  return scenario.evidence ?? null;
}

function hasScenarioEvidence(scenario: TestScenario): boolean {
  const evidence = getScenarioEvidence(scenario);
  return Boolean(evidence && TEST_EVIDENCE_FIELDS.some((field) => Boolean(evidence[field])));
}

function formatEvidenceTimestamp(value: string | null | undefined): string | null {
  if (!value) return null;
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleString();
}

function testScenarioStatusColor(status: string): string {
  switch (status) {
    case 'passed': return 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300';
    case 'failed': return 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300';
    case 'automated': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300';
    case 'ready': return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/40 dark:text-yellow-300';
    default: return 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400';
  }
}

function remediationPathLabel(path: string): string {
  switch (path) {
    case 'path_a_reuse_existing_scenario':
      return 'Path A · Reuse eligible scenario';
    case 'path_b_semantic_gap':
      return 'Path B · Semantic gap';
    case 'path_b_amendment_lineage':
      return 'Path B · Amendment lineage';
    default:
      return 'Workflow guidance';
  }
}

function BugWorkflowRemediationPanel({
  preview,
  linkedTestCount,
}: {
  preview: BugRegressionScenarioPreview | null;
  linkedTestCount: number;
}) {
  const remediation: BugWorkflowRemediationMessage | null = preview?.remediation ?? null;
  if (!remediation) {
    return (
      <div className="flex items-start gap-3 p-4 rounded-lg bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-700/40">
        <AlertCircle className="shrink-0 mt-0.5 text-amber-500" size={20} />
        <div>
          <p className="text-sm font-semibold text-amber-800 dark:text-amber-300">Regression gate guidance unavailable</p>
          <p className="text-xs text-amber-700 dark:text-amber-400 mt-0.5">
            Refresh the card to reload canonical remediation details before moving this bug forward.
          </p>
        </div>
      </div>
    );
  }

  const isReady = linkedTestCount > 0 && !remediation.semantic_gap_required;
  const tone = isReady
    ? 'bg-green-50 dark:bg-green-900/10 border-green-200 dark:border-green-700/40 text-green-800 dark:text-green-300'
    : remediation.semantic_gap_required
      ? 'bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-700/40 text-red-800 dark:text-red-300'
      : 'bg-amber-50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-700/40 text-amber-800 dark:text-amber-300';
  const Icon = isReady ? Check : remediation.semantic_gap_required ? XCircle : AlertCircle;
  const iconClass = isReady ? 'text-green-500' : remediation.semantic_gap_required ? 'text-red-500' : 'text-amber-500';
  const primaryAction = remediation.actions.find((action) => action.primary) ?? remediation.actions[0] ?? null;
  const secondaryActions = primaryAction
    ? remediation.actions.filter((action) => action.action_id !== primaryAction.action_id)
    : [];

  return (
    <div data-testid="bug-workflow-remediation-panel" className={`p-4 rounded-lg border ${tone}`}>
      <div className="flex items-start gap-3">
        <Icon className={`shrink-0 mt-0.5 ${iconClass}`} size={20} />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-sm font-semibold">
              {isReady ? 'Ready for In Progress' : remediation.message}
            </p>
            <span className="text-[10px] px-2 py-0.5 rounded-full bg-white/70 dark:bg-black/20 font-semibold">
              {remediationPathLabel(remediation.remediation_path)}
            </span>
          </div>
          <p className="text-xs mt-1 opacity-90">{remediation.detail}</p>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mt-3 text-[10px]">
            <div className="rounded bg-white/70 dark:bg-black/20 px-2 py-1">
              <span className="block opacity-70">Next action</span>
              <strong>{remediation.next_action}</strong>
            </div>
            <div className="rounded bg-white/70 dark:bg-black/20 px-2 py-1">
              <span className="block opacity-70">Eligible</span>
              <strong>{remediation.eligible_scenarios_count}</strong>
            </div>
            <div className="rounded bg-white/70 dark:bg-black/20 px-2 py-1">
              <span className="block opacity-70">Semantic gap</span>
              <strong>{remediation.semantic_gap_required ? 'yes' : 'no'}</strong>
            </div>
          </div>
          {primaryAction && (
            <div className="mt-3 space-y-2">
              <div className="rounded border border-current/30 bg-white/80 dark:bg-black/25 px-3 py-2">
                <p className="text-[10px] uppercase tracking-wide opacity-70">Primary action</p>
                <p className="text-xs font-semibold">{primaryAction.label}</p>
                <p className="text-[10px] opacity-80">{primaryAction.description}</p>
              </div>
              {secondaryActions.length > 0 && (
                <div className="space-y-1">
                  <p className="text-[10px] uppercase tracking-wide opacity-70">Supporting actions</p>
                  {secondaryActions.map((action) => (
                    <div key={action.action_id} className="rounded bg-white/70 dark:bg-black/20 px-2 py-1.5">
                      <p className="text-xs font-semibold">{action.label}</p>
                      <p className="text-[10px] opacity-80">{action.description}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {preview && (preview.eligible_scenarios.length > 0 || preview.rejected_scenarios.length > 0) && (
            <div className="grid sm:grid-cols-2 gap-2 mt-3 text-xs">
              <div>
                <p className="font-semibold mb-1">Eligible scenarios</p>
                {preview.eligible_scenarios.length > 0 ? (
                  <ul className="space-y-1">
                    {preview.eligible_scenarios.map((scenario) => (
                      <li key={scenario.scenario_id} className="rounded bg-white/70 dark:bg-black/20 px-2 py-1">
                        {scenario.title || scenario.scenario_id}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-[10px] opacity-75">None</p>
                )}
              </div>
              <div>
                <p className="font-semibold mb-1">Rejected candidates</p>
                {preview.rejected_scenarios.length > 0 ? (
                  <ul className="space-y-1">
                    {preview.rejected_scenarios.map((scenario) => (
                      <li key={scenario.scenario_id} className="rounded bg-white/70 dark:bg-black/20 px-2 py-1">
                        {scenario.scenario_id} · {scenario.reason}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-[10px] opacity-75">None</p>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

interface CardModalProps {
  boardId: string;
  onClose?: () => void;
  onEscape?: () => void;
  onAuthoritativeStatusChange?: (
    card: Card,
    previousStatus: CardStatus,
  ) => void;
}

interface TaskValidationHierarchySnapshot {
  cardId: string;
  specId: string | null;
  config: ResolvedTaskValidationThresholds;
}

export function CardModal({
  boardId,
  onClose,
  onEscape,
  onAuthoritativeStatusChange,
}: CardModalProps) {
  const api = useDashboardApi();
  const perms = usePermissions(boardId);
  const tabIdBase = useId();
  const selectedCardId = useSelectedCard();
  const selectedCardIdRef = useRef(selectedCardId);
  selectedCardIdRef.current = selectedCardId;
  const cardLoadGenerationRef = useRef(0);
  const cardDataGenerationRef = useRef(0);
  const cardStatusRef = useRef<CardStatus | null>(null);
  const isOpen = useIsCardModalOpen();
  const modalOrigin = useRef<HTMLElement | null>(null);
  useEffect(() => {
    if (!isOpen) return;
    modalOrigin.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    return () => { if (modalOrigin.current?.isConnected) modalOrigin.current.focus(); };
  }, [isOpen]);
  const { closeCardModal, openCardModal, removeCardFromColumn, updateCardInColumn, cardModalTarget } = useDashboardStore();
  const columns = useColumns();
  const currentBoard = useCurrentBoard();

  // Flat list of all cards on the board for dependency picker
  const allBoardCards = Object.values(columns).flat();

  const [card, setCard] = useState<Card | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [liveRevision, setLiveRevision] = useState(0);
  const [syncAuthorizing, setSyncAuthorizing] = useState(false);
  const syncGeneration = useRef(0);
  const authorizationRequired = useRef(false);
  const refreshedRevision = useRef(0);
  const boardIdRef = useRef(boardId);
  boardIdRef.current = boardId;
  const [activeTab, setActiveTab] = useState<CardModalTab>('details');
  const nativeReferenceRoot = useRef<HTMLDivElement>(null);
  useNativeReferenceFocus(nativeReferenceRoot, card?.id === selectedCardId ? cardModalTarget?.focusReference : undefined,
    `${selectedCardId}:${isOpen}:${isLoading}:${activeTab}`);
  const [testsTab, setTestsTab] = useState<CardTestsTab>('regression');
  const [referencesTab, setReferencesTab] =
    useState<CardReferencesTab>('lineage');
  const [validationTab, setValidationTab] =
    useState<CardValidationTab>('execution-report');
  const [policyAuthorityRefreshKey, setPolicyAuthorityRefreshKey] = useState(0);
  const [movingStatus, setMovingStatus] = useState<CardStatus | null>(null);
  const [expanded, setExpanded] = useState(false);
  const [boardMembers, setBoardMembers] = useState<{ id: string; name: string }[]>([]);
  const [seenStatus, setSeenStatus] = useState<Record<string, { agent_name: string; seen_at: string }[]>>({});
  const [dependencies, setDependencies] = useState<{ id: string; title: string; status: string }[]>([]);
  const [dependents, setDependents] = useState<{ id: string; title: string; status: string }[]>([]);
  const [parentSpec, setParentSpec] = useState<{ id: string; title: string } | null>(null);
  const [fullSpec, setFullSpec] = useState<Spec | null>(null);
  const [projectStructureProjection, setProjectStructureProjection] =
    useState<ProjectStructureProjectionResponse | null>(null);
  const [projectStructureLoading, setProjectStructureLoading] = useState(false);
  const [projectStructureError, setProjectStructureError] = useState<string | null>(null);
  const projectStructureGeneration = useRef(0);
  const [taskValidationHierarchy, setTaskValidationHierarchy] =
    useState<TaskValidationHierarchySnapshot | null>(null);
  const [taskValidationHierarchyLoading, setTaskValidationHierarchyLoading] =
    useState(false);
  const [taskValidationHierarchyError, setTaskValidationHierarchyError] =
    useState<string | null>(null);
  const [specScenarios, setSpecScenarios] = useState<TestScenario[]>([]);
  const [specRules, setSpecRules] = useState<any[]>([]);
  const [specContracts, setSpecContracts] = useState<any[]>([]);
  const [specIRs, setSpecIRs] = useState<any[]>([]);
  const [specORs, setSpecORs] = useState<any[]>([]);
  const [specTRs, setSpecTRs] = useState<any[]>([]);
  const [bugRegressionPreview, setBugRegressionPreview] = useState<BugRegressionScenarioPreview | null>(null);
  const [amendmentRevisions, setAmendmentRevisions] = useState<AmendmentRevisionListResponse | null>(null);
  const [amendmentBusy, setAmendmentBusy] = useState(false);
  const [knowledgeMutationBusy, setKnowledgeMutationBusy] = useState(false);
  const [viewingSpecId, setViewingSpecId] = useState<string | null>(null);
  const [viewingSpecNodeId, setViewingSpecNodeId] = useState<string | null>(null);
  const [specKBsFull, setSpecKBsFull] = useState<{ id: string; title: string; description?: string; content: string; mime_type?: string }[]>([]);
  const [knowledgeReaderActive, setKnowledgeReaderActive] = useState(false);
  const [showConclusionPrompt, setShowConclusionPrompt] = useState(false);
  const [humanReportRequest, setHumanReportRequest] = useState<{ cardId: string; status: 'validation' | 'done'; requestId: string }>();
  const consumedHumanReportRequest = useRef<string>();
  const [showCancelDialog, setShowCancelDialog] = useState(false);
  const [conclusionTargetStatus, setConclusionTargetStatus] = useState<CardStatus>('done');
  const [conclusionDraft, setConclusionDraft] = useState('');
  const [conclusionCompleteness, setConclusionCompleteness] = useState(100);
  const [conclusionCompletenessJustification, setConclusionCompletenessJustification] = useState('');
  const [conclusionDrift, setConclusionDrift] = useState(0);
  const [conclusionDriftJustification, setConclusionDriftJustification] = useState('');
  const [conclusionImpactDraft, setConclusionImpactDraft] = useState<ImpactEvidenceDraft>(emptyImpactEvidenceDraft());
  // AC-16: the 409 impact_evidence_required remediation renders inline and
  // the prompt stays open with its state preserved.
  const [conclusionGateError, setConclusionGateError] = useState<string | null>(null);
  const [conclusionDeliverySelection, setConclusionDeliverySelection] = useState<DeliverySelectionInput>();
  const [conclusionSelectionPending, setConclusionSelectionPending] = useState(false);
  const [conclusionBatchMode, setConclusionBatchMode] = useState(false);
  const [conclusionBatch, setConclusionBatch] = useState<CardDeliveryBatchDraft>();
  const conclusionOrigin = useRef<{ cardId: string; status: CardStatus }>();
  const conclusionReplay = useRef<{ body: string; key: string }>();
  const learningSubmissionReplay = useRef<{ body: string; key: string }>();
  const learningReportScope = `${boardId}:${card?.id}:${conclusionTargetStatus}`;
  const [reportLearning, setReportLearning] = useState<{ scope: string; draft: Omit<LearningSubmission, 'capture_id'> | null; pending: boolean } | null>(null);
  const onReportLearning = useCallback((draft: Omit<LearningSubmission, 'capture_id'> | null, pending: boolean) => {
    setReportLearning({ scope: learningReportScope, draft, pending });
  }, [learningReportScope]);
  const canAuthorLearning = !perms.isLoading && !perms.error
    && ['board.read', 'card.entity.read', 'card.entity.context_read', 'card.validation.read',
      'card.comments.read', 'card.conclusion.read', 'card.tests.read', 'spec.entity.read', 'spec.tests.read',
      'kg.session.begin', 'kg.session.add_node', 'kg.session.add_edge', 'kg.session.commit', 'card.conclusion.write'].every(perms.has);
  const reportLearningPending = reportLearning?.scope === learningReportScope && reportLearning.pending;
  const conclusionSubmitting = useRef(false);
  const taskValidationThresholdsReady = Boolean(
    card
    && currentBoard?.id === card.board_id
    && taskValidationHierarchy?.cardId === card.id
    && taskValidationHierarchy.specId === (card.spec_id ?? null),
  );
  const taskValidationThresholds = taskValidationThresholdsReady
    ? taskValidationHierarchy!.config
    : null;
  const originTask = card?.origin_task_id
    ? allBoardCards.find((candidate) => candidate.id === card.origin_task_id) || null
    : null;
  const linkedTestTasks = (card?.linked_test_task_ids || []).map((taskId) => ({
    id: taskId,
    card: allBoardCards.find((candidate) => candidate.id === taskId) || null,
  }));
  const linkedScenarioIds = new Set(card?.test_scenario_ids || []);
  const linkedEvidenceScenarios = specScenarios.filter((scenario) => linkedScenarioIds.has(scenario.id));
  const evidenceProvidedCount = linkedEvidenceScenarios.filter(hasScenarioEvidence).length;
  const canMutateCard = (action: string) => {
    if (
      card?.status === 'rejected'
      && ![
        'card.move.rejected_to_in_progress',
        'card.qa.ask',
        'card.qa.answer',
        'card.comments.create',
        'card.comments.create_choice',
        'card.comments.respond_choice',
      ].includes(action)
    ) {
      return false;
    }
    return hasPermissionWithState(
      perms.has,
      action,
      'card',
      card?.status,
    );
  };
  const canReadIR = perms.has('spec.integration_requirements.read');
  const canReadOR = perms.has('spec.observability_requirements.read');
  const canReadProjectStructure = perms.has('spec.entity.read');
  const showCardProjectStructure = Boolean(
    canReadProjectStructure
    && card?.spec_id
    && ['normal', 'test'].includes(card.card_type ?? 'normal')
    && fullSpec?.id === card.spec_id
    && fullSpec.project_structure !== null
    && fullSpec.project_structure !== undefined,
  );
  const projectStructureActive = showCardProjectStructure && isOpen && card?.id === selectedCardId
    && activeTab === 'references' && referencesTab === 'project-structure' && !syncAuthorizing;
  const projectStructureVisible = useRef(projectStructureActive);
  projectStructureVisible.current = projectStructureActive;
  const canLinkIRTasks = perms.has('spec.integration_requirements.link_task') && canMutateCard('card.link_to.ir');
  const canLinkORTasks = perms.has('spec.observability_requirements.link_task') && canMutateCard('card.link_to.or');
  const canReadTests = perms.has('card.tests.read');
  const canReadMockups = perms.has('card.mockups.read');
  const canReadArchitecture = perms.has('card.architecture.read');
  const canReadAttachments = perms.has('card.attachments.read');
  const canReadKnowledge = perms.has('card.entity.read');
  const canReadQA = perms.has('card.qa.read');
  const canReadComments = perms.has('card.comments.read');
  const canReadConclusion = perms.has('card.conclusion.read');
  const canReadValidation = perms.has('card.validation.read');
  const canReadPolicyCompliance = perms.has('guidelines.assessments.read');
  const canReadActivity = perms.has('card.activity_read');
  const { canReadProjection: canReadCodeTraceability } =
    useCodeTraceabilityAuthority(boardId);
  const normalContentFrozen = (card?.card_type ?? 'normal') === 'normal'
    && fullSpec?.id === card?.spec_id && fullSpec?.status === 'done';
  const canEditCardFields = !normalContentFrozen && canMutateCard('card.entity.edit_fields');
  const canEditBugFields = canMutateCard('card.entity.edit_bug_fields');
  const canAssignCard = !normalContentFrozen && canMutateCard('card.entity.assign');
  const canLinkTests = canMutateCard('card.entity.link_tests');
  const canAskQA = canMutateCard('card.qa.ask');
  const canAnswerQA = canMutateCard('card.qa.answer');
  const canCreateComments = canMutateCard('card.comments.create');
  const canCreateChoiceComments = canMutateCard('card.comments.create_choice');
  const canRespondToChoiceComments = canMutateCard('card.comments.respond_choice');
  const canUploadAttachments = !normalContentFrozen && canMutateCard('card.attachments.upload');
  const canDeleteAttachments = !normalContentFrozen && canMutateCard('card.attachments.delete');
  const canDeleteCard = !normalContentFrozen && canMutateCard('card.entity.delete');
  const canManageDependencies = !normalContentFrozen && canMutateCard('card.entity.manage_dependencies');
  const canLinkScenarios = canMutateCard('card.link_to.scenario');
  const canLinkRules = canMutateCard('card.link_to.rule');
  const canLinkContracts = canMutateCard('card.link_to.contract');
  const canLinkTRs = canMutateCard('card.link_to.tr');
  const canSubmitValidation = canMutateCard('card.validation.submit');
  const canReadAmendmentRevisions = perms.has('amendment.revision.read');
  const canCreateAmendment = card?.status !== 'rejected'
    && perms.has('amendment.revision.create');
  const canAssociateAmendment = card?.status !== 'rejected'
    && perms.has('amendment.revision.associate');
  const canReadBoardAgents = perms.has('agent.board_access.read');
  const hasAmendmentWorkspace = Boolean(
    bugRegressionPreview?.semantic_gap_required
    || (amendmentRevisions?.revisions.length || 0) > 0,
  );

  const loadProjectStructureProjection = useCallback(async (
    subject: Pick<Card, 'id' | 'board_id' | 'spec_id' | 'card_type'>,
  ) => {
    if (!projectStructureVisible.current) return;
    const generation = ++projectStructureGeneration.current;
    const supportsProjection = Boolean(
      canReadProjectStructure
      && subject.spec_id
      && ['normal', 'test'].includes(subject.card_type ?? 'normal'),
    );
    if (!supportsProjection) {
      setProjectStructureProjection(null);
      setProjectStructureError(null);
      setProjectStructureLoading(false);
      return;
    }
    const requestCardId = subject.id;
    const isCurrent = () => generation === projectStructureGeneration.current
      && selectedCardIdRef.current === requestCardId && boardIdRef.current === boardId
      && projectStructureVisible.current;
    setProjectStructureLoading(true);
    setProjectStructureError(null);
    try {
      const projection = await api.getCardProjectStructure(
        subject.board_id || boardId,
        requestCardId,
      );
      if (!isCurrent()) return;
      setProjectStructureProjection(projection);
    } catch {
      if (!isCurrent()) return;
      setProjectStructureProjection(null);
      setProjectStructureError('The project structure projection could not be loaded.');
    } finally {
      if (isCurrent()) {
        setProjectStructureLoading(false);
      }
    }
  }, [api, boardId, canReadProjectStructure]);

  const policyTransitionAuthority = usePolicyTransitionAuthority({
    boardId: card?.board_id ?? boardId,
    entityType: 'card',
    subjectId: card?.id,
    currentStatus: card?.status,
    enabled: isOpen,
    refreshKey: policyAuthorityRefreshKey,
  });

  const notePolicySubjectChanged = useCallback(() => {
    setPolicyAuthorityRefreshKey((current) => current + 1);
  }, []);

  const withPreservedOpenQACount = useCallback((updated: Card) => {
    if (!canReadQA || updated.open_qa_count !== undefined) return updated;
    const localCard = card?.id === updated.id && card.open_qa_count !== undefined
      ? card
      : undefined;
    const projectedCard = localCard
      ?? CARD_STATUSES
        .map((status) => (columns[status] ?? []).find((candidate) => candidate.id === updated.id))
        .find((candidate) => candidate?.open_qa_count !== undefined);
    return preserveProjectedOpenQACount(updated, projectedCard);
  }, [canReadQA, card, columns]);

  const applyCardUpdate = useCallback((updated: Card) => {
    const reconciled = withPreservedOpenQACount(updated);
    const previousStatus = cardStatusRef.current;
    cardStatusRef.current = reconciled.status;
    setCard(reconciled);
    updateCardInColumn(reconciled);
    if (previousStatus && previousStatus !== reconciled.status) {
      onAuthoritativeStatusChange?.(reconciled, previousStatus);
    }
    notePolicySubjectChanged();
  }, [notePolicySubjectChanged, onAuthoritativeStatusChange, updateCardInColumn, withPreservedOpenQACount]);

  const resetConclusionPrompt = () => {
    setConclusionDraft('');
    setConclusionCompleteness(100);
    setConclusionCompletenessJustification('');
    setConclusionDrift(0);
    setConclusionDriftJustification('');
    setConclusionImpactDraft(emptyImpactEvidenceDraft());
    setConclusionDeliverySelection(undefined);
    setConclusionSelectionPending(false);
    setConclusionBatchMode(false);
    setConclusionBatch(undefined);
    conclusionOrigin.current = card ? { cardId: card.id, status: card.status } : undefined;
    conclusionReplay.current = undefined;
    learningSubmissionReplay.current = undefined;
    setReportLearning(null);
    setConclusionGateError(null);
  };

  const requiresExecutionReport = (status: CardStatus) => {
    if (!card || status === card.status) return false;
    if (status === 'done') return true;
    if (status !== 'validation') return false;
    if (card.card_type === 'test') return false;
    return ['not_started', 'in_progress', 'on_hold'].includes(card.status);
  };

  const loseCardAccess = () => {
    syncGeneration.current += 1;
    cardLoadGenerationRef.current += 1;
    cardDataGenerationRef.current += 1;
    setSyncAuthorizing(false);
    setCard(null);
    setFullSpec(null);
    setParentSpec(null);
    setSpecKBsFull([]);
    setDependencies([]);
    setDependents([]);
    setSeenStatus({});
    setBoardMembers([]);
    setSpecScenarios([]);
    setSpecRules([]);
    setSpecContracts([]);
    setSpecIRs([]);
    setSpecORs([]);
    setSpecTRs([]);
    setShowConclusionPrompt(false);
    setShowCancelDialog(false);
    resetConclusionPrompt();
    closeCardModal();
    onClose?.();
  };
  const loseCardAccessRef = useRef(loseCardAccess);
  loseCardAccessRef.current = loseCardAccess;

  const loadCard = (cardId: string) => {
    const loadGeneration = ++cardLoadGenerationRef.current;
    const dataGeneration = ++cardDataGenerationRef.current;
    const isCurrentFullLoad = () =>
      loadGeneration === cardLoadGenerationRef.current
      && selectedCardIdRef.current === cardId;
    const isCurrentLoad = () =>
      isCurrentFullLoad()
      && dataGeneration === cardDataGenerationRef.current;
    // Refreshing the same card must keep the human submission draft mounted.
    setIsLoading(card?.id !== cardId);
    setBugRegressionPreview(null);
    setAmendmentRevisions(null);
    if (card?.id !== cardId) setFullSpec(null);
    setSpecKBsFull([]);
    setTaskValidationHierarchy(null);
    setTaskValidationHierarchyLoading(true);
    setTaskValidationHierarchyError(null);
    api.getCard(cardId)
      .then((data) => {
        if (!isCurrentLoad()) return;
        const reconciled = withPreservedOpenQACount(data);
        const projectedStatus = CARD_STATUSES.find((status) =>
          (columns[status] ?? []).some((candidate) => candidate.id === data.id),
        );
        cardStatusRef.current = reconciled.status;
        setCard(reconciled);
        updateCardInColumn(reconciled);
        if (projectedStatus && projectedStatus !== reconciled.status) {
          onAuthoritativeStatusChange?.(reconciled, projectedStatus);
        }
        notePolicySubjectChanged();
        if (data.card_type === 'bug') {
          api.getBugRegressionScenarioCandidates(data.id, data.board_id)
            .then((preview) => {
              if (isCurrentLoad()) setBugRegressionPreview(preview);
            })
            .catch(() => {
              if (isCurrentLoad()) setBugRegressionPreview(null);
            });
          if (canReadAmendmentRevisions) {
            api.listAmendmentRevisions(data.board_id, data.id)
              .then((revisions) => {
                if (isCurrentLoad()) setAmendmentRevisions(revisions);
              })
              .catch(() => {
                if (isCurrentLoad()) setAmendmentRevisions(null);
              });
          } else {
            setAmendmentRevisions(null);
          }
        }
        const specRequest: Promise<Spec | null | undefined> = data.spec_id
          ? api.getSpec(data.spec_id).catch(() => undefined)
          : Promise.resolve(null);
        void specRequest.then((spec) => {
          if (!isCurrentLoad()) return;

          if (spec) {
            setParentSpec({ id: spec.id, title: spec.title });
            setFullSpec(spec);
            setSpecScenarios(spec.test_scenarios || []);
            setSpecRules(spec.business_rules || []);
            setSpecContracts(spec.api_contracts || []);
            setSpecIRs(spec.integration_requirements || []);
            setSpecORs(spec.observability_requirements || []);
            setSpecTRs((spec.technical_requirements || []).map((tr: any, i: number) => typeof tr === 'string' ? { id: `tr_legacy_${i}`, text: tr, linked_task_ids: null } : tr));
          } else {
            setParentSpec(null);
            setFullSpec(null);
            setSpecScenarios([]);
            setSpecRules([]);
            setSpecContracts([]);
            setSpecIRs([]);
            setSpecORs([]);
            setSpecTRs([]);
            setSpecKBsFull([]);
          }
          if (spec === undefined || !data.validation_config) {
            setTaskValidationHierarchy(null);
            setTaskValidationHierarchyError(
              'Could not load the authoritative Card validation thresholds.',
            );
          } else {
            setTaskValidationHierarchy({
              cardId: data.id,
              specId: data.spec_id ?? null,
              config: data.validation_config,
            });
            setTaskValidationHierarchyError(null);
          }
          setTaskValidationHierarchyLoading(false);
        });
      })
      .catch((error: unknown) => {
        if (isCurrentLoad()) {
          if (error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status)) {
            loseCardAccessRef.current(); return;
          }
          setTaskValidationHierarchy(null);
          setTaskValidationHierarchyLoading(false);
          setTaskValidationHierarchyError(
            'Could not load the card validation thresholds.',
          );
          toast.error('Failed to load card');
        }
      })
      .finally(() => {
        if (isCurrentFullLoad()) setIsLoading(false);
      });
    if (canReadBoardAgents) {
      api.listAgentsForBoard(boardId)
        .then((agents) => {
          if (isCurrentLoad()) {
            setBoardMembers(agents.map((a) => ({ id: a.id, name: a.name })));
          }
        })
        .catch(() => {});
    } else {
      setBoardMembers([]);
    }
    api.getCardSeenStatus(cardId)
      .then((data) => {
        if (isCurrentLoad()) setSeenStatus(data.items);
      })
      .catch(() => {});
    api.getCardDependencies(cardId)
      .then((items) => {
        if (isCurrentLoad()) setDependencies(items);
      })
      .catch(() => {});
    api.getCardDependents(cardId)
      .then((items) => {
        if (isCurrentLoad()) setDependents(items);
      })
      .catch(() => {});
  };

  // Bodies are needed only by the visible Knowledge picker, not threshold
  // resolution. A new Spec inventory replaces the previous roots; late results
  // from a closed pane or another Card never repopulate the current picker.
  const knowledgeSourceId = fullSpec?.id;
  const knowledgeSourceInventory = fullSpec?.knowledge_bases;
  const knowledgeCardSpecId = card?.spec_id;
  useEffect(() => {
    if (!canReadKnowledge || !knowledgeSourceId || knowledgeCardSpecId !== knowledgeSourceId) {
      setSpecKBsFull([]);
      return;
    }
    if (!knowledgeReaderActive || activeTab !== 'resources' || syncAuthorizing) return;
    let cancelled = false;
    setSpecKBsFull([]);
    void Promise.all((knowledgeSourceInventory || []).map(kb =>
      api.getSpecKnowledge(knowledgeSourceId, kb.id).catch(() => null),
    )).then(items => {
      if (!cancelled) setSpecKBsFull(items.filter(item => item !== null).map(item => ({
        ...item, description: item.description ?? undefined, content: item.content || '',
      })));
    });
    return () => { cancelled = true; };
  }, [api, canReadKnowledge, selectedCardId, knowledgeCardSpecId, knowledgeSourceId,
    knowledgeSourceInventory, knowledgeReaderActive, activeTab, syncAuthorizing, liveRevision]);

  // Silent refresh — updates card data without showing loading spinner
  const silentRefresh = useCallback((cardId: string) => {
    if (isLoading || taskValidationHierarchyLoading) return;
    const dataGeneration = ++cardDataGenerationRef.current;
    const isCurrentRefresh = () =>
      dataGeneration === cardDataGenerationRef.current
      && selectedCardIdRef.current === cardId;
    api.getCard(cardId)
      .then((data) => {
        if (!isCurrentRefresh()) return;
        const reconciled = withPreservedOpenQACount(data);
        // Reuse the existing modal refresh cycle for external-agent writes.
        // Verification may change on another Card while this Card stays Done.
        notifyReadinessChanged();
        const previousStatus = cardStatusRef.current;
        cardStatusRef.current = reconciled.status;
        setCard(reconciled);
        updateCardInColumn(reconciled);
        if (previousStatus && previousStatus !== reconciled.status) {
          onAuthoritativeStatusChange?.(reconciled, previousStatus);
        }
        setTaskValidationHierarchyLoading(true);
        setTaskValidationHierarchyError(null);
        // A Spec/policy revision can change allowed actions without changing
        // the Card's updated_at. Refresh only after an actual invalidation.
        notePolicySubjectChanged();
        if (data.card_type === 'bug') {
          api.getBugRegressionScenarioCandidates(data.id, data.board_id)
            .then((preview) => {
              if (isCurrentRefresh()) {
                setBugRegressionPreview(preview);
              }
            })
            .catch(() => {
              if (isCurrentRefresh()) {
                setBugRegressionPreview(null);
              }
            });
          if (canReadAmendmentRevisions) {
            api.listAmendmentRevisions(data.board_id, data.id)
              .then((revisions) => {
                if (isCurrentRefresh()) {
                  setAmendmentRevisions(revisions);
                }
              })
              .catch(() => {
                if (isCurrentRefresh()) {
                  setAmendmentRevisions(null);
                }
              });
          } else {
            setAmendmentRevisions(null);
          }
        } else {
          setBugRegressionPreview(null);
          setAmendmentRevisions(null);
        }
        const specRequest: Promise<Spec | null | undefined> = data.spec_id
          ? api.getSpec(data.spec_id).catch(() => undefined)
          : Promise.resolve(null);
        void specRequest.then((spec) => {
          if (!isCurrentRefresh()) return;
          if (spec) {
            setParentSpec({ id: spec.id, title: spec.title });
            setFullSpec(spec);
            setSpecScenarios(spec.test_scenarios || []);
            setSpecRules(spec.business_rules || []);
            setSpecContracts(spec.api_contracts || []);
            setSpecIRs(spec.integration_requirements || []);
            setSpecORs(spec.observability_requirements || []);
            setSpecTRs((spec.technical_requirements || []).map((tr: any, i: number) => typeof tr === 'string' ? { id: `tr_legacy_${i}`, text: tr, linked_task_ids: null } : tr));
          } else {
            setParentSpec(null);
            setFullSpec(null);
            setSpecScenarios([]);
            setSpecRules([]);
            setSpecContracts([]);
            setSpecIRs([]);
            setSpecORs([]);
            setSpecTRs([]);
          }
          if (spec === undefined || !data.validation_config) {
            setTaskValidationHierarchy(null);
            setTaskValidationHierarchyError(
              'Could not refresh the authoritative Card validation thresholds.',
            );
          } else {
            setTaskValidationHierarchy({
              cardId: data.id,
              specId: data.spec_id ?? null,
              config: data.validation_config,
            });
            setTaskValidationHierarchyError(null);
          }
          setTaskValidationHierarchyLoading(false);
        });
      })
      .catch((error: unknown) => {
        if (!isCurrentRefresh()) return;
        if (error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status)) {
          loseCardAccessRef.current(); return;
        }
        setTaskValidationHierarchy(null);
        setTaskValidationHierarchyLoading(false);
        setTaskValidationHierarchyError(
          'Could not refresh the card validation thresholds.',
        );
      });
    api.getCardSeenStatus(cardId)
      .then((data) => {
        if (isCurrentRefresh()) setSeenStatus(data.items);
      })
      .catch(() => {});
    api.getCardDependencies(cardId)
      .then((items) => {
        if (isCurrentRefresh()) setDependencies(items);
      })
      .catch(() => {});
    api.getCardDependents(cardId)
      .then((items) => {
        if (isCurrentRefresh()) setDependents(items);
      })
      .catch(() => {});
  }, [
    api,
    canReadAmendmentRevisions,
    isLoading,
    notePolicySubjectChanged,
    onAuthoritativeStatusChange,
    taskValidationHierarchyLoading,
    updateCardInColumn,
    withPreservedOpenQACount,
  ]);

  // Path B safe actions (spec be089cd3). User-click only — NO auto-mutation on
  // render, and NEVER a gate skip/bypass; these only REMEDIATE via the new
  // amendment-revision surfaces.
  const handleCreateAmendment = useCallback(async () => {
    if (!card || !canCreateAmendment) return;
    setAmendmentBusy(true);
    try {
      await api.createAmendmentRevision(card.board_id, card.id, {
        origin_task_ids: card.origin_task_id ? [card.origin_task_id] : undefined,
      });
      toast.success('Amendment revision created (draft)');
      silentRefresh(card.id);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Failed to create amendment revision');
    } finally {
      setAmendmentBusy(false);
    }
  }, [api, canCreateAmendment, card, silentRefresh]);

  const handleAssociateAmendment = useCallback(async (amendmentId: string) => {
    if (!card || !canAssociateAmendment) return;
    setAmendmentBusy(true);
    try {
      await api.associateAmendmentRevisionArtifacts(card.board_id, card.id, amendmentId, {
        regression_test_task_ids: card.linked_test_task_ids ?? [],
      });
      toast.success('Regression artifacts associated');
      silentRefresh(card.id);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Failed to associate artifacts');
    } finally {
      setAmendmentBusy(false);
    }
  }, [api, canAssociateAmendment, card, silentRefresh]);

  useEffect(() => {
    if (selectedCardId && isOpen) {
      if (syncAuthorizing) return;
      loadCard(selectedCardId);
    } else {
      cardLoadGenerationRef.current += 1;
      cardDataGenerationRef.current += 1;
      cardStatusRef.current = null;
      setCard(null);
      setSpecKBsFull([]);
      setTaskValidationHierarchy(null);
      setTaskValidationHierarchyLoading(false);
      setTaskValidationHierarchyError(null);
    }
  }, [selectedCardId, isOpen, canReadAmendmentRevisions, canReadBoardAgents]);

  useEffect(() => {
    if (isOpen && card?.id === selectedCardId && canReadCodeTraceability && cardModalTarget) {
      setActiveTab(cardModalTarget.tab);
      const request = cardModalTarget.humanReport;
      if (request && consumedHumanReportRequest.current !== request.requestId && card.status === 'in_progress') {
        consumedHumanReportRequest.current = request.requestId;
        setHumanReportRequest({ cardId: card.id, ...request });
      }
    }
  }, [isOpen, card?.id, selectedCardId, canReadCodeTraceability, cardModalTarget]);

  useEffect(() => {
    if (!card || !isOpen || !showCardProjectStructure) {
      setProjectStructureProjection(null);
      setProjectStructureError(null);
      setProjectStructureLoading(false);
      return;
    }
    if (projectStructureActive) void loadProjectStructureProjection(card);
    return () => { projectStructureGeneration.current += 1; };
  }, [
    card,
    fullSpec?.project_structure_revision,
    isOpen,
    showCardProjectStructure,
    projectStructureActive,
    liveRevision,
    loadProjectStructureProjection,
  ]);

  useEffect(() => {
    if (!card) return;

    const hasResources =
      canReadMockups
      || canReadKnowledge
      || canReadArchitecture
      || canReadAttachments;
    const hasValidation =
      canReadConclusion
      || (card.card_type !== 'test' && canReadValidation)
      || canReadPolicyCompliance;
    const unavailable =
      (activeTab === 'tests'
        && (!canReadTests || !['bug', 'test'].includes(card.card_type || 'normal')))
      || (activeTab === 'resources' && !hasResources)
      || (activeTab === 'qa' && !canReadQA)
      || (activeTab === 'comments' && !canReadComments)
      || (activeTab === 'implementation-targets'
        && (!canReadCodeTraceability || card.card_type !== 'normal'))
      || (activeTab === 'validation' && !hasValidation)
      || (activeTab === 'activity' && !canReadActivity);

    if (unavailable) {
      setActiveTab('details');
    }

    if (
      card.card_type === 'test'
      && !['scenarios', 'evidence'].includes(testsTab)
    ) {
      setTestsTab('scenarios');
    }
    if (
      card.card_type === 'bug'
      && !['regression', 'coverage', 'amendment'].includes(testsTab)
    ) {
      setTestsTab('regression');
    }
    if (
      card.card_type === 'bug'
      && testsTab === 'amendment'
      && !hasAmendmentWorkspace
    ) {
      setTestsTab('regression');
    }
    if (
      referencesTab === 'project-structure'
      && !showCardProjectStructure
    ) {
      setReferencesTab('lineage');
    }
    const visibleValidationTabs: CardValidationTab[] = [
      ...(canReadConclusion ? ['execution-report' as const] : []),
      ...(card.card_type !== 'test' && canReadValidation
        ? ['task-validation' as const]
        : []),
      ...(canReadPolicyCompliance ? ['policy-compliance' as const] : []),
    ];
    if (
      visibleValidationTabs.length > 0
      && !visibleValidationTabs.includes(validationTab)
    ) {
      setValidationTab(visibleValidationTabs[0]);
    }
  }, [
    activeTab,
    canReadActivity,
    canReadArchitecture,
    canReadAttachments,
    canReadComments,
    canReadCodeTraceability,
    canReadConclusion,
    canReadKnowledge,
    canReadMockups,
    canReadPolicyCompliance,
    canReadProjectStructure,
    canReadQA,
    canReadTests,
    canReadValidation,
    card,
    hasAmendmentWorkspace,
    testsTab,
    referencesTab,
    showCardProjectStructure,
    validationTab,
  ]);

  const handleWorkspaceRevision = async ({ initial, authorityChanged }: {
    initial: boolean; authorityChanged: boolean;
  }) => {
      if (initial) return;
      const requestedCard = selectedCardId;
      const generation = ++syncGeneration.current;
      const current = () => generation === syncGeneration.current
        && selectedCardIdRef.current === requestedCard && boardIdRef.current === boardId;
      authorizationRequired.current ||= authorityChanged;
      if (authorizationRequired.current) {
        cardLoadGenerationRef.current += 1;
        cardDataGenerationRef.current += 1;
        // Invalidated loads cannot clear their loading flags in finally.
        // The authorized revision below queues their replacement explicitly.
        setIsLoading(false);
        setTaskValidationHierarchyLoading(false);
        setSyncAuthorizing(true);
        try {
          const effective = await refreshBoardPermissions(boardId);
          if (!current()) return;
          if (effective.board_id !== boardId || !hasEffectivePermission(effective, 'card.entity.read')) {
            loseCardAccessRef.current(); return;
          }
        } catch { if (current()) loseCardAccessRef.current(); return; }
      }
      if (!current()) return;
      authorizationRequired.current = false;
      setSyncAuthorizing(false);
      setLiveRevision(value => value + 1);
  };

  const syncState = useWorkspaceRevisions({
    boardId: isOpen && selectedCardId ? boardId : undefined,
    subjects: selectedCardId ? [
      { subject_type: 'card', subject_id: selectedCardId },
      ...(card?.id === selectedCardId && card.spec_id && perms.has('spec.entity.read')
        ? [{ subject_type: 'spec' as const, subject_id: card.spec_id }] : []),
    ] : [],
    // The linked Spec can lose access while the Card remains readable. Recheck
    // the Card's own authority; its native refresh still refuses lost Card access.
    onAccessLost: () => { void handleWorkspaceRevision({ initial: false, authorityChanged: true }); },
    onChange: handleWorkspaceRevision,
  });

  useEffect(() => {
    if (!selectedCardId || !isOpen || isLoading || taskValidationHierarchyLoading || syncAuthorizing
      || liveRevision === refreshedRevision.current) return;
    refreshedRevision.current = liveRevision;
    silentRefresh(selectedCardId);
  }, [selectedCardId, isOpen, isLoading, taskValidationHierarchyLoading, syncAuthorizing, liveRevision, silentRefresh]);

  useEffect(() => {
    authorizationRequired.current = false;
    setSyncAuthorizing(false);
    return () => {
      syncGeneration.current += 1;
      cardLoadGenerationRef.current += 1;
      cardDataGenerationRef.current += 1;
    };
  }, [boardId, selectedCardId, isOpen]);

  const handleRefresh = () => {
    if (selectedCardId) loadCard(selectedCardId);
  };

  const handleClose = () => {
    if (knowledgeMutationBusy) return;
    closeCardModal();
    onClose?.();
  };

  useEscapeToClose(
    () => {
      if (onEscape) onEscape();
      else handleClose();
    },
    {
      enabled: isOpen,
      canClose: !knowledgeMutationBusy,
    },
  );

  const handleStatusChange = async (status: CardStatus, conclusion?: string, metrics?: { completeness: number; completeness_justification: string; drift: number; drift_justification: string }, cancellationReason?: string, impactEvidence?: ImpactEvidence, deliverySelection?: DeliverySelectionInput, batch?: CardDeliveryBatchDraft): Promise<boolean> => {
    if (!card || conclusionSubmitting.current || (!batch && status === card.status)) return false;
    // Rejected is consequence-only. Even if a rolling-upgrade server were to
    // project a stale manual edge, the client must never invoke it.
    if (status === 'rejected') return false;
    const fromStatus = batch ? conclusionOrigin.current?.status : card.status;
    if (batch && conclusionOrigin.current?.cardId !== card.id) return false;
    if (!batch && card.status === 'rejected' && status !== 'in_progress') return false;
    if (batch ? !hasPermissionWithState(perms.has, `card.move.${fromStatus}_to_${status}`, 'card', fromStatus)
      : !canMutateCard(`card.move.${card.status}_to_${status}`)) return false;

    // ITEM 17: cancelling requires a justification — intercept with the dialog.
    if (status === 'cancelled' && !cancellationReason) {
      setShowCancelDialog(true);
      return false;
    }

    // Human Spec delivery uses one audited application command. Technical
    // receipt selection and assessment scores belong to the agent workflow.
    if (card.spec_id && ['normal', 'bug', 'test'].includes(card.card_type || 'normal')
      && ['validation', 'done'].includes(status) && !conclusion) {
      setActiveTab('delivery');
      if (card.status !== 'in_progress') {
        toast.error('Review the task in Delivery. A new delivery report requires In Progress; existing validation remains authoritative.');
        return false;
      }
      setHumanReportRequest({ cardId: card.id, status: status as 'validation' | 'done', requestId: crypto.randomUUID() });
      return false;
    }
    // Legacy reports for cards outside a Spec.
    if (requiresExecutionReport(status) && !conclusion) {
      setConclusionTargetStatus(status);
      setShowConclusionPrompt(true);
      resetConclusionPrompt();
      return false;
    }

    setMovingStatus(status);
    conclusionSubmitting.current = true;
    policyTransitionAuthority.clearRejection();
    try {
      if (reportLearningPending && conclusion) throw new Error('Complete or remove the Learning before submitting this report.');
      let learningSubmission: LearningSubmission | undefined;
      if (conclusion && card.card_type === 'bug' && reportLearning?.scope === learningReportScope && reportLearning.draft) {
        if (!canAuthorLearning) throw new Error('Learning authoring permission is unavailable.');
        const body = JSON.stringify({ boardId, cardId: card.id, status, conclusion, metrics,
          impactEvidence, deliverySelection, batch, learning: reportLearning.draft });
        if (learningSubmissionReplay.current?.body !== body) learningSubmissionReplay.current = { body, key: uuidv4() };
        learningSubmission = { ...reportLearning.draft, capture_id: learningSubmissionReplay.current.key };
      }
      if (batch) {
        if (!card.spec_id || !deliverySelection || !sameDeliveryBasis(batch, deliverySelection)
          || !batch.entries.length || !conclusion || !metrics
          || fromStatus !== 'in_progress' || !['validation', 'done'].includes(status)) {
          throw new Error('Refresh and review the delivery selection before submitting this draft.');
        }
        const body: CardDeliveryReportInput = {
          contract_version: 'card-delivery-report/v1', expected_card_status: 'in_progress',
          batch: { ...batch, idempotency_key: '' },
          report: { status: status as 'validation' | 'done', conclusion, ...metrics,
            ...(learningSubmission ? { learning_submission: learningSubmission } : {}),
            ...(impactEvidence ? { impact_evidence: impactEvidence } : {}) },
          existing_record_ids: deliverySelection.record_ids, reuse_impact: deliverySelection.reuse_impact ?? false,
        };
        if (batch.entries.length + body.existing_record_ids.length > 200 || new TextEncoder().encode(JSON.stringify(body)).length > 128 * 1024) {
          throw new Error('The report exceeds the selected record or size limit. Reduce the draft before submitting.');
        }
        const fingerprint = JSON.stringify({ boardId: card.board_id, cardId: card.id, specId: card.spec_id, body });
        if (conclusionReplay.current?.body !== fingerprint) conclusionReplay.current = { body: fingerprint, key: crypto.randomUUID() };
        body.batch.idempotency_key = conclusionReplay.current.key;
        await api.recordCardDeliveryEvidence(card.board_id, card.id, card.spec_id, body);
        // A failed refresh cannot turn a confirmed commit into a failed submission.
        try { applyCardUpdate(await api.getCard(card.id)); }
        catch { toast.error('Report saved. Refresh the card to see its current state.'); }
        toast.success('Evidence and report saved');
        return true;
      }
      const updated = await api.moveCard(card.id, {
        ...(learningSubmission ? { learning_submission: learningSubmission } : {}),
        status,
        conclusion,
        completeness: metrics?.completeness,
        completeness_justification: metrics?.completeness_justification,
        drift: metrics?.drift,
        drift_justification: metrics?.drift_justification,
        ...(cancellationReason ? { cancellation_reason: cancellationReason } : {}),
        ...(impactEvidence ? { impact_evidence: impactEvidence } : {}),
        ...(deliverySelection ? { delivery_selection: deliverySelection } : {}),
      });
      applyCardUpdate(updated);
      if (updated.status === 'cancelled') {
        setActiveTab('details');
        window.setTimeout(() => {
          document
            .getElementById('cancellation-panel')
            ?.scrollIntoView({ block: 'start', behavior: 'smooth' });
        }, 0);
      }
      toast.success('Status updated');
      return true;
    } catch (err) {
      const rejection = readPolicyTransitionRejection(err, {
        boardId: card.board_id,
        entityType: 'card',
        subjectId: card.id,
        currentStatus: card.status,
        toStatus: status,
      });
      const handled =
        await policyTransitionAuthority.handleTransitionError(err, status);
      if (!handled) {
        await policyTransitionAuthority.refresh();
      }
      toast.error(
        rejection
          ? policyTransitionRejectionMessage(rejection)
          : err instanceof Error
            ? err.message
            : 'Failed to update status',
      );
      // AC-16: surface the rejection inside the still-open prompt. ANY
      // rejection keeps the typed report and evidence rows — a 422 from the
      // shape contract is as correctable as the 409 gate, and discarding the
      // author's work would be the worse failure.
      setConclusionGateError(
        err instanceof Error ? err.message : 'Failed to update status',
      );
      return false;
    } finally {
      conclusionSubmitting.current = false;
      setMovingStatus(null);
    }
  };

  const handleAssigneeChange = async (assigneeId: string) => {
    if (!card || !canAssignCard) return;
    try {
      const updated = await api.updateCard(card.id, { assignee_id: assigneeId || undefined });
      applyCardUpdate(updated);
      toast.success('Assignee updated');
    } catch {
      toast.error('Failed to update assignee');
    }
  };

  const handlePriorityChange = async (priority: string) => {
    if (!card || !canEditCardFields) return;
    try {
      const updated = await api.updateCard(card.id, { priority: priority as CardPriority });
      applyCardUpdate(updated);
      toast.success('Priority updated');
    } catch {
      toast.error('Failed to update priority');
    }
  };

  const handleDelete = async () => {
    if (!card || !canDeleteCard) return;
    if (!confirm('Are you sure you want to delete this card?')) return;

    try {
      await api.deleteCard(card.id);
      removeCardFromColumn(card.id);
      handleClose();
      toast.success('Card deleted');
    } catch {
      toast.error('Failed to delete card');
    }
  };

  const conclusionTargetLabel = STATUS_LABELS[conclusionTargetStatus];
  const hasVisibleResources =
    canReadMockups
    || canReadKnowledge
    || canReadArchitecture
    || canReadAttachments;
  const hasVisibleValidation = Boolean(
    card
    && (
      canReadConclusion
      || (card.card_type !== 'test' && canReadValidation)
      || canReadPolicyCompliance
    )
  );
  const unansweredQA = card?.qa_items.filter(
    (item) => item.answered_at == null,
  ).length || 0;
  const resourceCount = card
    ? (card.screen_mockups?.length || 0)
      + (card.knowledge_bases?.length || 0)
      + (card.architecture_designs?.length || 0)
      + card.attachments.length
    : 0;
  const validationCount = card
    ? (card.conclusions?.length || 0) + (card.validations?.length || 0)
    : 0;
  const allowedStatuses: CardStatus[] = card
    ? [
        card.status,
        ...policyTransitionAuthority.actionableTransitions
          .map((transition) => transition.to_status)
          .filter(
            (status): status is CardStatus =>
              Object.prototype.hasOwnProperty.call(STATUS_LABELS, status)
              && status !== card.status,
          )
          .filter((status) => status !== 'rejected')
          .filter((status) => (
            card.status !== 'rejected' || status === 'in_progress'
          ))
          .filter((status) => canMutateCard(
            `card.move.${card.status}_to_${status}`,
          )),
      ].filter(
        (status, index, statuses) => statuses.indexOf(status) === index,
      )
    : [];
  const topTabs: {
    id: CardModalTab;
    label: string;
    icon: ReactNode;
    count?: number;
    attention?: boolean;
  }[] = card
    ? [
        {
          id: 'details',
          label: 'Details',
          icon: <FileText size={14} />,
        },
        ...(
          canReadCodeTraceability && card.card_type === 'normal'
            ? [{
                id: 'implementation-targets' as const,
                label: 'Implementation Targets',
                icon: <Target size={14} />,
              }]
            : []
        ),
        ...(
          canReadCodeTraceability && card.spec_id && ['normal', 'bug', 'test'].includes(card.card_type || 'normal')
            ? [{
                id: 'delivery' as const,
                label: 'Delivery',
                icon: <ShieldCheck size={14} />,
              }]
            : []
        ),
        ...(
          canReadTests && ['bug', 'test'].includes(card.card_type || 'normal')
            ? [{
                id: 'tests' as const,
                label: 'Tests',
                icon: <FlaskConical size={14} />,
                count: card.card_type === 'bug'
                  ? card.linked_test_task_ids?.length || 0
                  : linkedEvidenceScenarios.length,
                attention: card.card_type === 'bug'
                  ? (card.linked_test_task_ids?.length || 0) === 0
                  : evidenceProvidedCount < linkedEvidenceScenarios.length,
              }]
            : []
        ),
        ...(
          hasVisibleResources
            ? [{
                id: 'resources' as const,
                label: 'Resources',
                icon: <Layers size={14} />,
                count: resourceCount,
              }]
            : []
        ),
        ...(
          canReadQA
            ? [{
                id: 'qa' as const,
                label: 'Q&A',
                icon: <MessageCircleQuestion size={14} />,
                count: card.qa_items.length,
                attention: unansweredQA > 0,
              }]
            : []
        ),
        ...(
          canReadComments
            ? [{
                id: 'comments' as const,
                label: 'Comments',
                icon: <MessageSquare size={14} />,
                count: card.comments.length,
              }]
            : []
        ),
        {
          id: 'references',
          label: 'References',
          icon: <Link size={14} />,
        },
        ...(
          hasVisibleValidation
            ? [{
                id: 'validation' as const,
                label: 'Validation',
                icon: <Shield size={14} />,
                count: validationCount,
              }]
            : []
        ),
        ...(
          canReadActivity
            ? [{
                id: 'activity' as const,
                label: 'Activity',
                icon: <History size={14} />,
              }]
            : []
        ),
      ]
    : [];

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={event => {
      // Nested dialogs are siblings of the Card content. Their clicks must not
      // dismiss the Card (and thereby unmount an open Spec or its draft).
      if (event.target === event.currentTarget) handleClose();
    }}>
      {syncAuthorizing && <PulseLoader label="Checking Card access…" />}
      <div ref={nativeReferenceRoot} style={{ display: syncAuthorizing ? 'none' : undefined }} className={`modal-content ${expanded ? '!max-w-[95vw] !h-[95vh]' : ''}`} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="modal-header">
          <div className="flex items-center gap-3 flex-1">
            <select
              value={card?.status || ''}
              onChange={(e) => handleStatusChange(e.target.value as CardStatus)}
              disabled={
                !card
                || isLoading
                 || knowledgeMutationBusy
                 || movingStatus !== null
                 || policyTransitionAuthority.preview.status !== 'ready'
                 || allowedStatuses.length <= 1
               }
              aria-label="Card status"
              className="text-sm border border-gray-300 rounded px-2 py-1 bg-white dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100"
            >
              {allowedStatuses.map((status) => (
                <option key={status} value={status}>
                  {STATUS_LABELS[status]}
                </option>
              ))}
            </select>
            {card?.card_type === 'bug' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-xs font-bold bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 uppercase tracking-wide shrink-0">
                <Bug size={14} />
                BUG
              </span>
            )}
            {card?.card_type === 'test' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-xs font-bold bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300 uppercase tracking-wide shrink-0">
                <FlaskConical size={14} />
                TEST
              </span>
            )}
            <h2 className="font-semibold text-lg whitespace-pre-wrap break-words flex-1 min-w-0">
              <EditableField value={card?.title || ''} disabled={isLoading || !card || !canEditCardFields}
                placeholder="Card title" renderView={value => <span>{value}</span>}
                onSave={async title => {
                  if (!card || !title) throw new Error('Card title is required.');
                  applyCardUpdate(await api.updateCard(card.id, { title }));
                  toast.success('Title updated');
                }} />
            </h2>
          </div>
          {parentSpec && (
            <button
              onClick={() => setViewingSpecId(parentSpec.id)}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300 hover:ring-2 hover:ring-violet-300 dark:hover:ring-violet-600 transition-all shrink-0"
              title="View linked spec"
            >
              <FileText size={11} />
              {parentSpec.title.length > 30 ? parentSpec.title.slice(0, 27) + '...' : parentSpec.title}
            </button>
          )}
          <div className="flex items-center gap-1">
            <button
              onClick={() => {
                if (!card) return;
                openLineageGraph(
                  card.card_type === 'bug'
                    ? 'bug'
                    : card.card_type === 'test'
                      ? 'test'
                      : 'task',
                  card.id,
                );
              }}
              disabled={!card}
              className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors disabled:opacity-30"
              title="Open lineage graph"
            >
              <GitBranch size={16} />
            </button>
            {card && (
              <EntityExportButton
                boardId={card.board_id || boardId}
                entityType="card"
                entityId={card.id}
                entityTitle={card.title}
              />
            )}
            <button onClick={handleRefresh} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors" title="Refresh card">
              <RefreshCw size={16} className={isLoading ? 'animate-spin' : ''} />
            </button>
            <button onClick={() => setExpanded(!expanded)} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors" title={expanded ? 'Collapse' : 'Expand'}>
              {expanded ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
            </button>
            <button
              onClick={handleClose}
              disabled={knowledgeMutationBusy}
              aria-label="Close card dialog"
              className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:cursor-not-allowed disabled:opacity-50"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Body */}
        {(syncState === 'offline' || syncState === 'unavailable') && <p role="status" className="px-6 py-2 text-sm text-amber-700 dark:text-amber-300">
          Live updates are unavailable. This Card may be out of date.
        </p>}
        {isLoading ? (
          <div className="modal-body text-center py-8 text-gray-500 dark:text-gray-400">Loading...</div>
        ) : card ? (
          <>
            {/* Tabs */}
            <AccessibleTabList
              idBase={`${tabIdBase}-card-${card.id}`}
              ariaLabel="Card sections"
              items={topTabs.map((tab) => ({
                ...tab,
                disabled: knowledgeMutationBusy,
              }))}
              value={activeTab}
              onValueChange={setActiveTab}
              className="px-6 pt-3"
            />

            <div className="modal-body">
              {normalContentFrozen && (
                <p role="status" className="mb-4 text-sm text-amber-700 dark:text-amber-300">
                  This Spec is Done. Normal task content is locked; use the authorized Spec revision workflow to resume normal work. Reading and collaboration remain available.
                </p>
              )}
              {/* Details Tab */}
              <AccessibleTabPanel
                idBase={`${tabIdBase}-card-${card.id}`}
                tabId="details"
                value={activeTab}
              >
                <div className="space-y-4">
                  {card.status === 'cancelled' && (
                    <div className="space-y-2">
                      <CancellationDetails
                        id="cancellation-panel"
                        entityLabel="card"
                        reason={card.cancellation_reason}
                        cancelledBy={card.cancelled_by}
                        cancelledAt={card.cancelled_at}
                        resolveActorName={(id) =>
                          resolveActorName(id, boardMembers)
                        }
                      />
                      <p className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-200">
                        Cancelling a card can return a validated parent spec to
                        Approved. Its earlier evaluation results remain under
                        Previous, and a new Current result is required when the
                        spec enters Validation again. The lifecycle change
                        remains available in Activity.
                      </p>
                    </div>
                  )}
                  <div>
                    <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">Description</h3>
                    <EditableField
                      value={card.description || ''}
                      disabled={!canEditCardFields}
                      onSave={async (val) => {
                        const updated = await api.updateCard(card.id, { description: val });
                        applyCardUpdate(updated);
                      }}
                      multiline
                      renderView={(v) => <Md>{v}</Md>}
                      placeholder="No description"
                    />
                  </div>

                  {/* Bug-specific fields */}
                  {card.card_type === 'bug' && (
                    <>
                      {/* Severity */}
                      <div>
                        <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">Severity</h3>
                        <div className="flex gap-2">
                          {(['critical', 'major', 'minor'] as BugSeverity[]).map((sev) => (
                            <button
                              key={sev}
                              disabled={!canEditBugFields}
                              onClick={async () => {
                                if (!canEditBugFields) return;
                                const updated = await api.updateCard(card.id, { severity: sev });
                                applyCardUpdate(updated);
                              }}
                              className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                                card.severity === sev
                                  ? sev === 'critical' ? 'bg-red-500 text-white ring-2 ring-red-300'
                                  : sev === 'major' ? 'bg-orange-500 text-white ring-2 ring-orange-300'
                                  : 'bg-yellow-500 text-white ring-2 ring-yellow-300'
                                  : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'
                              } disabled:cursor-not-allowed disabled:opacity-50`}
                            >
                              {BUG_SEVERITY_LABELS[sev]}
                            </button>
                          ))}
                        </div>
                      </div>

                      {/* Expected Behavior */}
                      <div>
                        <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">Expected Behavior</h3>
                        <div className="border border-gray-200 dark:border-gray-600 rounded-lg bg-green-50 dark:bg-green-900/10">
                          <EditableField
                            value={card.expected_behavior || ''}
                            disabled={!canEditBugFields}
                            onSave={async (val) => {
                              const updated = await api.updateCard(card.id, { expected_behavior: val });
                              applyCardUpdate(updated);
                            }}
                            multiline
                            renderView={(v) => <div className="p-3 text-sm text-gray-800 dark:text-gray-200"><Md>{v}</Md></div>}
                            placeholder="Describe expected behavior..."
                          />
                        </div>
                      </div>

                      {/* Observed Behavior */}
                      <div>
                        <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">Observed Behavior</h3>
                        <div className="border border-red-200 dark:border-red-600/40 rounded-lg bg-red-50 dark:bg-red-900/10">
                          <EditableField
                            value={card.observed_behavior || ''}
                            disabled={!canEditBugFields}
                            onSave={async (val) => {
                              const updated = await api.updateCard(card.id, { observed_behavior: val });
                              applyCardUpdate(updated);
                            }}
                            multiline
                            renderView={(v) => <div className="p-3 text-sm text-gray-800 dark:text-gray-200"><Md>{v}</Md></div>}
                            placeholder="Describe observed behavior..."
                          />
                        </div>
                      </div>

                      {/* Steps to Reproduce */}
                      <div>
                        <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">Steps to Reproduce</h3>
                        <div className="border border-gray-200 dark:border-gray-600 rounded-lg bg-gray-50 dark:bg-gray-800">
                          <EditableField
                            value={card.steps_to_reproduce || ''}
                            disabled={!canEditBugFields}
                            onSave={async (val) => {
                              const updated = await api.updateCard(card.id, { steps_to_reproduce: val });
                              applyCardUpdate(updated);
                            }}
                            multiline
                            renderView={(v) => <div className="p-3 text-sm text-gray-800 dark:text-gray-200"><Md>{v}</Md></div>}
                            placeholder="Steps to reproduce..."
                          />
                        </div>
                      </div>

                      {/* Action Plan */}
                      <div>
                        <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">Action Plan</h3>
                        <div className="border border-blue-200 dark:border-blue-600/40 rounded-lg bg-blue-50 dark:bg-blue-900/10">
                          <EditableField
                            value={card.action_plan || ''}
                            disabled={!canEditBugFields}
                            onSave={async (val) => {
                              const updated = await api.updateCard(card.id, { action_plan: val });
                              applyCardUpdate(updated);
                            }}
                            multiline
                            renderView={(v) => <div className="p-3 text-sm text-gray-800 dark:text-gray-200"><Md>{v}</Md></div>}
                            placeholder="Action plan for fix..."
                          />
                        </div>
                      </div>
                    </>
                  )}

                  {/* Assignee */}
                  <div>
                    <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">Assignee</h3>
                    <select
                      value={card.assignee_id || ''}
                      onChange={(e) => handleAssigneeChange(e.target.value)}
                      disabled={!canAssignCard}
                      aria-label="Card assignee"
                      className="text-sm border border-gray-300 rounded px-3 py-1.5 bg-white dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100 w-full disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      <option value="">None</option>
                      {(() => {
                        // Build deduplicated assignee options: creator + board agents
                        const creatorName = boardMembers.find(m => m.id === card.created_by)?.name;
                        const creatorLabel = creatorName ? `${creatorName} (creator)` : `Owner (creator)`;
                        const options: { id: string; label: string }[] = [
                          { id: card.created_by, label: creatorLabel },
                        ];
                        for (const m of boardMembers) {
                          if (m.id !== card.created_by) {
                            options.push({ id: m.id, label: m.name });
                          }
                        }
                        return options.map(o => (
                          <option key={o.id} value={o.id}>{o.label}</option>
                        ));
                      })()}
                    </select>
                  </div>

                  {/* Priority */}
                  <div>
                    <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">Priority</h3>
                    <select
                      value={card.priority || 'none'}
                      onChange={(e) => handlePriorityChange(e.target.value)}
                      disabled={!canEditCardFields}
                      aria-label="Card priority"
                      className="text-sm border border-gray-300 rounded px-3 py-1.5 bg-white dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100 w-full disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      {CARD_PRIORITIES.map((p) => (
                        <option key={p} value={p}>{PRIORITY_LABELS[p]}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">Details</h3>
                    <EditableField
                      value={card.details || ''}
                      disabled={!canEditCardFields}
                      onSave={async (val) => {
                        const updated = await api.updateCard(card.id, { details: val });
                        applyCardUpdate(updated);
                      }}
                      multiline
                      renderView={(v) => <Md>{v}</Md>}
                      placeholder="No details"
                    />
                  </div>

                  {card.labels && card.labels.length > 0 && (
                    <div>
                      <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">Labels</h3>
                      <div className="flex flex-wrap gap-1">
                        {card.labels.map((label, idx) => (
                          <span
                            key={idx}
                            className="text-xs px-2 py-1 rounded bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300"
                          >
                            {label}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </AccessibleTabPanel>

              {canReadCodeTraceability && card.card_type === 'normal' && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="implementation-targets"
                  value={activeTab}
                  mount="lazy-keep"
                >
                  <ImplementationTargetsPanel
                    boardId={card.board_id}
                    revision={liveRevision}
                    active={activeTab === 'implementation-targets' && !syncAuthorizing}
                    subjectId={card.id}
                    subjectVersion={card.subject_version ?? 1}
                    specVersion={fullSpec?.version}
                    operationallyFrozen={card.status === 'rejected'}
                    onCreateDependency={canManageDependencies ? () => {
                      setActiveTab('references');
                      setReferencesTab('dependencies');
                    } : undefined}
                  />
                </AccessibleTabPanel>
              )}

              {canReadCodeTraceability && card.spec_id && ['normal', 'bug', 'test'].includes(card.card_type || 'normal') && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="delivery"
                  value={activeTab}
                  mount="lazy-keep"
                >
                  <CardDeliveryDoDPanel
                    key={card.id}
                    active={activeTab === 'delivery' && !syncAuthorizing}
                    revision={liveRevision}
                    reportRequest={humanReportRequest?.cardId === card.id ? humanReportRequest : undefined}
                    onReportClosed={() => setHumanReportRequest(undefined)}
                    boardId={card.board_id}
                    card={{ id: card.id, card_type: card.card_type || 'normal', spec_id: card.spec_id }}
                    canRecord={perms.has('code_traceability.target.execution_submit')}
                    canProgress={perms.has('card.conclusion.write')}
                    canTest={perms.has('spec.tests.execute')}
                    canWaiver={perms.has('code_traceability.waiver.create') || perms.has('code_traceability.waiver.clear')}
                    onOpenTests={canReadTests && card.card_type === 'test' ? () => setActiveTab('tests') : undefined}
                    focusDiagnosis={cardModalTarget?.focusDiagnosis}
                    focusRecordId={cardModalTarget?.recordId}
                    onOpenReadinessCard={openCardModal}
                    onChanged={() => { toast.success('Task updated'); void loadCard(card.id); notifyReadinessChanged(); }}
                  />
                </AccessibleTabPanel>
              )}

              <AccessibleTabPanel
                idBase={`${tabIdBase}-card-${card.id}`}
                tabId="references"
                value={activeTab}
              >
                <div className="space-y-4">
                  <AccessibleTabList
                    idBase={`${tabIdBase}-card-${card.id}-references`}
                    ariaLabel="Card reference sections"
                    items={[
                      {
                        id: 'lineage' as const,
                        label: 'Lineage',
                        icon: <GitBranch size={14} />,
                      },
                      {
                        id: 'requirements' as const,
                        label: 'Requirements',
                        icon: <ListChecks size={14} />,
                      },
                      ...(
                        showCardProjectStructure
                          ? [{
                              id: 'project-structure' as const,
                              label: 'Project structure',
                              icon: <FolderTree size={14} />,
                              count: projectStructureProjection?.nodes.filter((item) => item.direct).length,
                            }]
                          : []
                      ),
                      {
                        id: 'dependencies' as const,
                        label: 'Dependencies',
                        icon: <Link size={14} />,
                        count: dependencies.length + dependents.length,
                        attention: dependencies.some(
                          (dependency) =>
                            !['done', 'cancelled'].includes(dependency.status),
                        ),
                      },
                    ]}
                    value={referencesTab}
                    onValueChange={setReferencesTab}
                    variant="secondary"
                  />

                  <AccessibleTabPanel
                    idBase={`${tabIdBase}-card-${card.id}-references`}
                    tabId="lineage"
                    value={referencesTab}
                  >
                    <CardLineagePanel
                      card={card}
                      parentSpec={parentSpec}
                      originTask={originTask}
                      linkedTestTasks={linkedTestTasks}
                      onOpenSpec={setViewingSpecId}
                    />
                  </AccessibleTabPanel>

                  {showCardProjectStructure && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-references`}
                      tabId="project-structure"
                      value={referencesTab}
                    >
                      <ProjectStructureErrorBoundary>
                        <ProjectStructureProjectionPanel
                          projection={projectStructureProjection}
                          loading={projectStructureLoading}
                          error={projectStructureError}
                          onRetry={() => void loadProjectStructureProjection(card)}
                          onOpenFull={(nodeId) => {
                            setViewingSpecNodeId(nodeId ?? null);
                            setViewingSpecId(card.spec_id!);
                          }}
                        />
                      </ProjectStructureErrorBoundary>
                    </AccessibleTabPanel>
                  )}

                  <AccessibleTabPanel
                    idBase={`${tabIdBase}-card-${card.id}-references`}
                    tabId="dependencies"
                    value={referencesTab}
                  >
                    {/* Dependencies */}
                  <DependenciesSection
                    cardId={card.id}
                    dependencies={dependencies}
                    dependents={dependents}
                    setDependencies={setDependencies}
                    api={api}
                    allCards={allBoardCards}
                    canManage={canManageDependencies}
                    onSubjectChanged={notePolicySubjectChanged}
                  />
                  </AccessibleTabPanel>

                  <AccessibleTabPanel
                    idBase={`${tabIdBase}-card-${card.id}-references`}
                    tabId="requirements"
                    value={referencesTab}
                  >
                    <div className="space-y-4">
                    {(card.card_type ?? 'normal') === 'normal' && (
                      <div className="flex items-center justify-between gap-3 rounded-md border border-amber-200 bg-amber-50/70 p-3 dark:border-amber-800/60 dark:bg-amber-950/20">
                        <div className="min-w-0">
                          <h3 className="text-sm font-medium text-gray-900 dark:text-gray-100">Skip task requirement link gate</h3>
                          <p className="mt-0.5 text-xs text-gray-600 dark:text-gray-400">
                            Allow this task to start without a direct FR/TR/BR/IR/OR link.
                          </p>
                        </div>
                        {canEditCardFields ? (
                          <SettingsToggle
                            checked={card.skip_task_requirement_link_gate ?? false}
                            onChange={async () => {
                              const updated = await api.updateCard(card.id, {
                                skip_task_requirement_link_gate: !(card.skip_task_requirement_link_gate ?? false),
                              });
                              applyCardUpdate(updated);
                            }}
                            ariaLabel="Skip task requirement link gate for this card"
                            activeColor="amber"
                          />
                        ) : (
                          <span className="rounded-full border border-amber-200 bg-white px-2 py-1 text-[10px] font-semibold uppercase tracking-wide text-amber-700 dark:border-amber-800 dark:bg-gray-900/40 dark:text-amber-300">
                            {card.skip_task_requirement_link_gate
                              ? 'Enabled'
                              : 'Disabled'}
                          </span>
                        )}
                      </div>
                    )}

                  {/* Test Scenarios for normal cards; bug and test coverage live in Tests. */}
                  {(card.card_type ?? 'normal') === 'normal' && card.spec_id && specScenarios.length > 0 && (
                    <TestScenariosSection
                      card={card}
                      specId={card.spec_id}
                      scenarios={specScenarios}
                      api={api}
                      onUpdate={(updatedCard, updatedScenarios) => {
                        applyCardUpdate(updatedCard);
                        setSpecScenarios(updatedScenarios);
                      }}
                      canLink={canLinkScenarios}
                    />
                  )}

                  {/* Linked Business Rules */}
                  {card.spec_id && specRules.length > 0 && (
                    <LinkedSpecItemsSection
                      card={card}
                      specId={card.spec_id}
                      items={specRules}
                      field="business_rules"
                      label="Business Rules"
                      icon={<Scale size={14} className="inline mr-1" />}
                      api={api}
                      canLink={canLinkRules}
                      onSubjectChanged={notePolicySubjectChanged}
                      onSpecRefresh={() => {
                        api.getSpec(card.spec_id!).then((spec) => {
                          setSpecRules(spec.business_rules || []);
                        }).catch(() => {});
                      }}
                    />
                  )}

                  {/* Linked API Contracts */}
                  {card.spec_id && specContracts.length > 0 && (
                    <LinkedSpecItemsSection
                      card={card}
                      specId={card.spec_id}
                      items={specContracts}
                      field="api_contracts"
                      label="API Contracts"
                      icon={<FileText size={14} className="inline mr-1" />}
                      api={api}
                      canLink={canLinkContracts}
                      onSubjectChanged={notePolicySubjectChanged}
                      onSpecRefresh={() => {
                        api.getSpec(card.spec_id!).then((spec) => {
                          setSpecContracts(spec.api_contracts || []);
                        }).catch(() => {});
                      }}
                    />
                  )}

                  {/* Linked Integration Requirements */}
                  {card.spec_id && canReadIR && specIRs.length > 0 && (
                    <LinkedSpecItemsSection
                      card={card}
                      specId={card.spec_id}
                      items={specIRs}
                      field="integration_requirements"
                      label="Integration Requirements"
                      icon={<Network size={14} className="inline mr-1" />}
                      api={api}
                      canLink={canLinkIRTasks}
                      onSubjectChanged={notePolicySubjectChanged}
                      onSpecRefresh={() => {
                        api.getSpec(card.spec_id!).then((spec) => {
                          setSpecIRs(spec.integration_requirements || []);
                        }).catch(() => {});
                      }}
                    />
                  )}

                  {/* Linked Observability Requirements */}
                  {card.spec_id && canReadOR && specORs.length > 0 && (
                    <LinkedSpecItemsSection
                      card={card}
                      specId={card.spec_id}
                      items={specORs}
                      field="observability_requirements"
                      label="Observability Requirements"
                      icon={<Gauge size={14} className="inline mr-1" />}
                      api={api}
                      canLink={canLinkORTasks}
                      onSubjectChanged={notePolicySubjectChanged}
                      onSpecRefresh={() => {
                        api.getSpec(card.spec_id!).then((spec) => {
                          setSpecORs(spec.observability_requirements || []);
                        }).catch(() => {});
                      }}
                    />
                  )}

                  {/* Linked Technical Requirements */}
                  {card.spec_id && specTRs.length > 0 && (
                    <LinkedSpecItemsSection
                      card={card}
                      specId={card.spec_id}
                      items={specTRs}
                      field="technical_requirements"
                      label="Technical Requirements"
                      icon={<FileText size={14} className="inline mr-1" />}
                      api={api}
                      canLink={canLinkTRs}
                      onSubjectChanged={notePolicySubjectChanged}
                      onSpecRefresh={() => {
                        api.getSpec(card.spec_id!).then((spec) => {
                          setSpecTRs((spec.technical_requirements || []).map((tr: any, i: number) => typeof tr === 'string' ? { id: `tr_legacy_${i}`, text: tr, linked_task_ids: null } : tr));
                        }).catch(() => {});
                      }}
                    />
                  )}
                    </div>
                  </AccessibleTabPanel>
                </div>
              </AccessibleTabPanel>

              {canReadTests
                && ['bug', 'test'].includes(card.card_type || 'normal') && (
              <AccessibleTabPanel
                idBase={`${tabIdBase}-card-${card.id}`}
                tabId="tests"
                value={activeTab}
                mount="lazy-keep"
              >
                <div className="space-y-4">
                  <AccessibleTabList
                    idBase={`${tabIdBase}-card-${card.id}-tests`}
                    ariaLabel="Card test sections"
                    items={
                      card.card_type === 'bug'
                        ? [
                            {
                              id: 'regression' as const,
                              label: 'Regression',
                              icon: <FlaskConical size={14} />,
                              count: card.linked_test_task_ids?.length || 0,
                              attention:
                                (card.linked_test_task_ids?.length || 0) === 0,
                            },
                            {
                              id: 'coverage' as const,
                              label: 'Coverage',
                              icon: <CheckCircle size={14} />,
                              count: specScenarios.length,
                            },
                            ...(
                              hasAmendmentWorkspace
                                ? [{
                                    id: 'amendment' as const,
                                    label: 'Amendment',
                                    icon: <FileText size={14} />,
                                    count:
                                      amendmentRevisions?.revisions.length || 0,
                                  }]
                                : []
                            ),
                          ]
                        : [
                            {
                              id: 'scenarios' as const,
                              label: 'Scenarios',
                              icon: <FlaskConical size={14} />,
                              count: linkedEvidenceScenarios.length,
                            },
                            {
                              id: 'evidence' as const,
                              label: 'Evidence',
                              icon: <CheckCircle size={14} />,
                              count: evidenceProvidedCount,
                              attention:
                                evidenceProvidedCount
                                < linkedEvidenceScenarios.length,
                            },
                          ]
                    }
                    value={testsTab}
                    onValueChange={setTestsTab}
                    variant="secondary"
                  />

                  {card.card_type === 'bug' && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-tests`}
                      tabId="regression"
                      value={testsTab}
                    >
                      <div className="space-y-4">
                  <BugWorkflowRemediationPanel
                    preview={bugRegressionPreview}
                    linkedTestCount={card.linked_test_task_ids?.length ?? 0}
                  />

                  {/* Linked Test Tasks */}
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Linked Test Tasks</h3>
                    </div>
                    {(card.linked_test_task_ids?.length ?? 0) > 0 ? (
                      <div className="border border-gray-200 dark:border-gray-600 rounded-lg divide-y divide-gray-100 dark:divide-gray-700">
                        {card.linked_test_task_ids!.map((taskId) => {
                          const taskInBoard = allBoardCards.find(c => c.id === taskId);
                          return (
                            <div key={taskId} className="p-3 flex items-center justify-between">
                              <div className="flex items-center gap-3 min-w-0">
                                <span className="shrink-0 flex h-6 w-6 items-center justify-center rounded bg-violet-100 dark:bg-violet-900/40 text-violet-600 dark:text-violet-400">
                                  <FlaskConical size={12} />
                                </span>
                                <div className="min-w-0">
                                  <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                                    {taskInBoard?.title || taskId.slice(0, 12) + '…'}
                                  </p>
                                  {taskInBoard && (
                                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300 font-medium">
                                      {taskInBoard.status}
                                    </span>
                                  )}
                                </div>
                              </div>
                              <button
                                disabled={!canLinkTests}
                                onClick={async () => {
                                  if (!canLinkTests) return;
                                  try {
                                    await api.unlinkTestTaskFromBug(card.id, taskId);
                                    const updated = await api.getCard(card.id);
                                    applyCardUpdate(updated);
                                    toast.success('Test task unlinked');
                                  } catch {
                                    toast.error('Failed to unlink');
                                  }
                                }}
                                className="p-1 text-gray-400 hover:text-red-500 disabled:cursor-not-allowed disabled:opacity-30"
                                title={canLinkTests ? 'Unlink' : 'Missing permission: card.entity.link_tests'}
                              >
                                <X size={14} />
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <div className="border border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-6 flex flex-col items-center justify-center text-gray-400 dark:text-gray-500">
                        <Link size={32} strokeWidth={1.5} />
                        <p className="text-xs mt-2">No test tasks linked</p>
                        <p className="text-[10px] mt-0.5">Create test scenarios first, then link the resulting test tasks here</p>
                      </div>
                    )}
                  </div>
                      </div>
                    </AccessibleTabPanel>
                  )}

                  {card.card_type === 'bug' && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-tests`}
                      tabId="coverage"
                      value={testsTab}
                    >
                  {/* Test Scenarios from spec */}
                  {specScenarios.length > 0 ? (
                    <div>
                      <h3 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">
                        Test Scenarios (from Spec) — {specScenarios.length}
                      </h3>
                      <div className="border border-gray-200 dark:border-gray-600 rounded-lg divide-y divide-gray-100 dark:divide-gray-700">
                        {specScenarios.map((scenario) => {
                          const isNew = scenario.created_at && card.created_at && scenario.created_at >= card.created_at;
                          return (
                            <div key={scenario.id} className="p-3 flex items-start gap-3">
                              <div className="shrink-0 mt-0.5">
                                <span className={`flex h-6 w-6 items-center justify-center rounded-full ${isNew ? 'bg-green-100 dark:bg-green-900/40 text-green-600 dark:text-green-400' : 'bg-gray-100 dark:bg-gray-700 text-gray-400'}`}>
                                  <FlaskConical size={12} />
                                </span>
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-gray-900 dark:text-gray-100">{scenario.title}</p>
                                <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                                  Given {scenario.given} → When {scenario.when} → Then {scenario.then}
                                </p>
                                <div className="flex items-center gap-2 mt-1.5">
                                  {isNew && (
                                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 font-medium">NEW</span>
                                  )}
                                  <ScenarioTypeBadge scenarioType={scenario.scenario_type} />
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ) : (
                    <div className="rounded-lg border border-dashed border-gray-300 px-4 py-8 text-center text-sm text-gray-500 dark:border-gray-600 dark:text-gray-400">
                      The parent spec has no test scenarios available for
                      regression coverage.
                    </div>
                  )}
                    </AccessibleTabPanel>
                  )}

                  {card.card_type === 'bug'
                    && (
                      hasAmendmentWorkspace
                    ) && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-tests`}
                      tabId="amendment"
                      value={testsTab}
                    >
                      <PathBRemediationPanel
                        revisions={amendmentRevisions?.revisions ?? []}
                        pathBResolution={
                          amendmentRevisions?.path_b_resolution ?? null
                        }
                        bugRegressionPreview={bugRegressionPreview}
                        onCreateAmendment={handleCreateAmendment}
                        onAssociate={handleAssociateAmendment}
                        busy={amendmentBusy}
                        canCreate={canCreateAmendment}
                        canAssociate={canAssociateAmendment}
                      />
                    </AccessibleTabPanel>
                  )}

                  {card.card_type === 'test' && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-tests`}
                      tabId="scenarios"
                      value={testsTab}
                    >
                      {card.spec_id ? (
                        <TestScenariosSection
                          card={card}
                          specId={card.spec_id}
                          scenarios={specScenarios}
                          api={api}
                          canLink={canLinkScenarios}
                          onUpdate={(updatedCard, updatedScenarios) => {
                            applyCardUpdate(updatedCard);
                            setSpecScenarios(updatedScenarios);
                          }}
                        />
                      ) : (
                        <div className="rounded-lg border border-dashed border-gray-300 px-4 py-8 text-center text-sm text-gray-500 dark:border-gray-600 dark:text-gray-400">
                          Link this test card to a spec before associating test
                          scenarios.
                        </div>
                      )}
                    </AccessibleTabPanel>
                  )}

                  {card.card_type === 'test' && (
                    <AccessibleTabPanel
                      idBase={`${tabIdBase}-card-${card.id}-tests`}
                      tabId="evidence"
                      value={testsTab}
                    >
                      <TestEvidenceTab scenarios={linkedEvidenceScenarios} />
                    </AccessibleTabPanel>
                  )}
                </div>
              </AccessibleTabPanel>
              )}

              {hasVisibleResources && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="resources"
                  value={activeTab}
                  mount="lazy-keep"
                >
                  <CardResourcesPanel
                    card={card}
                    revision={liveRevision}
                    active={activeTab === 'resources' && !syncAuthorizing}
                    onKnowledgeVisibilityChange={setKnowledgeReaderActive}
                    expanded={expanded}
                    contentReadOnly={normalContentFrozen}
                    specKnowledgeBases={specKBsFull}
                    canReadMockups={canReadMockups}
                    canReadKnowledge={canReadKnowledge}
                    canReadArchitecture={canReadArchitecture}
                    canReadAttachments={canReadAttachments}
                    canUploadAttachments={canUploadAttachments}
                    canDeleteAttachments={canDeleteAttachments}
                    onCardChanged={(updated) => {
                      const reconciled = withPreservedOpenQACount(updated);
                      setCard(reconciled);
                      updateCardInColumn(reconciled);
                    }}
                    onSubjectChanged={notePolicySubjectChanged}
                    onBusyChange={setKnowledgeMutationBusy}
                  />
                </AccessibleTabPanel>
              )}

              {/* Q&A Tab */}
              {canReadQA && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="qa"
                  value={activeTab}
                >
                <QATab
                  card={card}
                  onCardChanged={applyCardUpdate}
                  api={api}
                  members={boardMembers}
                  seenStatus={seenStatus}
                  canAsk={canAskQA}
                  canAnswer={canAnswerQA}
                />
                </AccessibleTabPanel>
              )}

              {/* Comments Tab */}
              {canReadComments && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="comments"
                  value={activeTab}
                >
                <CommentsTab
                  card={card}
                  setCard={setCard}
                  api={api}
                  members={boardMembers}
                  seenStatus={seenStatus}
                  canCreate={canCreateComments}
                  canCreateChoice={canCreateChoiceComments}
                  canRespondToChoice={canRespondToChoiceComments}
                />
                </AccessibleTabPanel>
              )}

              {hasVisibleValidation && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="validation"
                  value={activeTab}
                  mount="lazy-keep"
                >
                  <div className="space-y-4">
                    <AccessibleTabList
                      idBase={`${tabIdBase}-card-${card.id}-validation`}
                      ariaLabel="Card validation sections"
                      items={[
                        ...(canReadConclusion
                          ? [{
                              id: 'execution-report' as const,
                              label: 'Execution report',
                              icon: <FileText size={14} />,
                              count: card.conclusions?.length || 0,
                            }]
                          : []),
                        ...(card.card_type !== 'test' && canReadValidation
                          ? [{
                              id: 'task-validation' as const,
                              label: 'Task validation',
                              icon: <Shield size={14} />,
                              count: card.validations?.length || 0,
                            }]
                          : []),
                        ...(canReadPolicyCompliance
                          ? [{
                              id: 'policy-compliance' as const,
                              label: 'Policy Compliance',
                              icon: <ShieldCheck size={14} />,
                            }]
                          : []),
                      ]}
                      value={validationTab}
                      onValueChange={setValidationTab}
                      variant="secondary"
                    />

                    {canReadConclusion && (
                      <AccessibleTabPanel
                        idBase={`${tabIdBase}-card-${card.id}-validation`}
                        tabId="execution-report"
                        value={validationTab}
                        mount="lazy-keep"
                      >
                        <ExecutionReportsPanel card={card} />
                        {card.card_type === 'bug' && card.id === selectedCardId && card.board_id === boardId && (
                          <LearningCapturePanel boardId={boardId} bugId={card.id} />
                        )}
                      </AccessibleTabPanel>
                    )}

                    {card.card_type !== 'test' && canReadValidation && (
                      <AccessibleTabPanel
                        idBase={`${tabIdBase}-card-${card.id}-validation`}
                        tabId="task-validation"
                        value={validationTab}
                      >
                        <ValidationsTab
                          boardId={boardId}
                          card={card}
                          onCardChanged={(updated) => {
                            applyCardUpdate(updated);
                          }}
                          api={api}
                          members={boardMembers}
                          canSubmit={canSubmitValidation}
                          thresholds={taskValidationThresholds}
                          thresholdsLoading={taskValidationHierarchyLoading}
                          thresholdsError={taskValidationHierarchyError}
                          onRetryThresholds={() => loadCard(card.id)}
                          canStartRework={allowedStatuses.includes('in_progress')}
                          reworkBusy={movingStatus === 'in_progress'}
                          onStartRework={() => handleStatusChange('in_progress')}
                        />
                      </AccessibleTabPanel>
                    )}

                    {canReadPolicyCompliance && (
                      <AccessibleTabPanel
                        idBase={`${tabIdBase}-card-${card.id}-validation`}
                        tabId="policy-compliance"
                        value={validationTab}
                        mount="lazy-keep"
                        className="space-y-4"
                      >
                        <PolicyCompliancePanel
                          boardId={card.board_id}
                          entityType="card"
                          presentationMode="subject-version"
                          subjectId={card.id}
                          transitionPreview={policyTransitionAuthority.preview}
                          refreshKey={policyAuthorityRefreshKey}
                          resolveSemanticAnchor={resolveCardSemanticAnchor}
                          onNavigateSemanticAnchor={() => {
                            setActiveTab('details');
                          }}
                          onEvaluated={() => {
                            policyTransitionAuthority.clearRejection();
                            void policyTransitionAuthority.refresh();
                          }}
                          onRefreshed={() => {
                            policyTransitionAuthority.clearRejection();
                            void policyTransitionAuthority.refresh();
                          }}
                        />
                      </AccessibleTabPanel>
                    )}
                  </div>
                </AccessibleTabPanel>
              )}

              {/* Activity Tab */}
              {canReadActivity && (
                <AccessibleTabPanel
                  idBase={`${tabIdBase}-card-${card.id}`}
                  tabId="activity"
                  value={activeTab}
                >
                  <ActivityTab cardId={card.id} api={api} revision={liveRevision} />
                </AccessibleTabPanel>
              )}
            </div>
          </>
        ) : null}

        {/* Execution report prompt — shown when changing status to Validation/Done */}
        {showConclusionPrompt && (
          <div className="px-6 py-3 border-t border-gray-100 dark:border-gray-700/50 bg-green-50/50 dark:bg-green-900/10 max-h-[60vh] overflow-y-auto">
            <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Execution Report Required</h4>
            <p className="text-xs text-gray-500 dark:text-gray-400 mb-2">
              Provide the executor report before moving this card to {conclusionTargetLabel}.
            </p>
            <textarea
              value={conclusionDraft}
              onChange={(e) => setConclusionDraft(e.target.value)}
              placeholder={"## Implementation Summary\n\n### Changes\n- ...\n\n### Testing\n- ...\n\n### Follow-ups\n- ..."}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none"
              rows={6}
              autoFocus
            />
            <div className="mt-4 grid gap-4 md:grid-cols-2">
              <div className="flex gap-4 rounded-lg border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-900/20">
                <MetricScoreRing
                label="Completeness"
                value={conclusionCompleteness}
                direction="higher-is-better"
                tone="info"
                testId="execution-report-completeness-score"
                />
                <div className="min-w-0 flex-1">
                  <label
                    htmlFor="execution-report-completeness"
                    className="text-xs font-medium text-gray-600 dark:text-gray-400"
                  >
                    Completeness score
                  </label>
                  <input
                    id="execution-report-completeness"
                    type="range"
                    min={0}
                    max={100}
                    value={conclusionCompleteness}
                    onChange={(e) =>
                      setConclusionCompleteness(Number(e.target.value))
                    }
                    className="mt-2 w-full"
                  />
                  <textarea
                    value={conclusionCompletenessJustification}
                    onChange={(e) =>
                      setConclusionCompletenessJustification(e.target.value)
                    }
                    placeholder="Justify the completeness score..."
                    className="mt-2 w-full resize-none rounded-lg border border-gray-300 px-3 py-2 text-xs dark:border-gray-600 dark:bg-gray-700"
                    rows={3}
                  />
                </div>
              </div>

              <div className="flex gap-4 rounded-lg border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-900/20">
                <MetricScoreRing
                label="Drift"
                value={conclusionDrift}
                direction="lower-is-better"
                tone="info"
                testId="execution-report-drift-score"
                />
                <div className="min-w-0 flex-1">
                  <label
                    htmlFor="execution-report-drift"
                    className="text-xs font-medium text-gray-600 dark:text-gray-400"
                  >
                    Drift score
                  </label>
                  <input
                    id="execution-report-drift"
                    type="range"
                    min={0}
                    max={100}
                    value={conclusionDrift}
                    onChange={(e) =>
                      setConclusionDrift(Number(e.target.value))
                    }
                    className="mt-2 w-full"
                  />
                  <textarea
                    value={conclusionDriftJustification}
                    onChange={(e) =>
                      setConclusionDriftJustification(e.target.value)
                    }
                    placeholder="Justify the drift score..."
                    className="mt-2 w-full resize-none rounded-lg border border-gray-300 px-3 py-2 text-xs dark:border-gray-600 dark:bg-gray-700"
                    rows={3}
                  />
                </div>
              </div>
            </div>
            <fieldset disabled={movingStatus !== null} className="min-w-0">
            {card?.card_type === 'bug' && <LearningSubmissionEditor key={learningReportScope}
              boardId={boardId} bugId={card.id} canCreate={canAuthorLearning}
              canReadTargets={!perms.isLoading && !perms.error && perms.has('kg.query.learning_from_bugs')} onChange={onReportLearning} />}
            {!conclusionDeliverySelection?.reuse_impact && <ImpactEvidenceEditor
              draft={conclusionImpactDraft}
              onChange={setConclusionImpactDraft}
            />}
            {card?.spec_id && <DeliverySelectionEditor key={card.id} boardId={card.board_id} cardId={card.id} specId={card.spec_id} onChange={setConclusionDeliverySelection} onPending={setConclusionSelectionPending} />}
            </fieldset>
            {conclusionGateError && (
              <p
                className="mt-2 rounded border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700 dark:border-red-800 dark:bg-red-950/30 dark:text-red-300"
                data-testid="impact-evidence-gate-error"
              >
                {conclusionGateError}
              </p>
            )}
            <div className="flex justify-end gap-2 mt-3">
              <button disabled={movingStatus !== null} onClick={() => setShowConclusionPrompt(false)} className="btn btn-secondary text-xs">Cancel</button>
              <button
                onClick={async () => {
                  setConclusionGateError(null);
                  const ok = await handleStatusChange(conclusionTargetStatus, conclusionDraft.trim(), {
                    completeness: conclusionCompleteness,
                    completeness_justification: conclusionCompletenessJustification.trim(),
                    drift: conclusionDrift,
                    drift_justification: conclusionDriftJustification.trim(),
                  }, undefined, conclusionDeliverySelection?.reuse_impact ? undefined : buildImpactEvidencePayload(conclusionImpactDraft), conclusionDeliverySelection, conclusionBatchMode ? conclusionBatch : undefined);
                  // AC-16: only a successful move closes the prompt — a gate
                  // rejection keeps every typed row intact.
                  if (ok) setShowConclusionPrompt(false);
                }}
                disabled={movingStatus !== null || reportLearningPending || conclusionSelectionPending || (conclusionBatchMode && (!conclusionBatch?.entries.length || !conclusionDeliverySelection || !sameDeliveryBasis(conclusionBatch, conclusionDeliverySelection))) || !conclusionDraft.trim() || !conclusionCompletenessJustification.trim() || !conclusionDriftJustification.trim()}
                className={`btn text-xs ${conclusionDraft.trim() && conclusionCompletenessJustification.trim() && conclusionDriftJustification.trim() ? 'btn-primary' : 'btn-secondary opacity-50'}`}
              >
                Complete & Move to {conclusionTargetLabel}
              </button>
            </div>
          </div>
        )}

        {canDeleteCard && (
          <div className="modal-footer">
            <button onClick={handleDelete} className="btn btn-danger flex items-center gap-1">
              <Trash2 size={16} />
              Delete
            </button>
          </div>
        )}
      </div>

      {/* Spec modal */}
      {viewingSpecId && (
        <SpecModal
          specId={viewingSpecId}
          boardId={boardId}
          initialTab={viewingSpecNodeId ? 'project-structure' : undefined}
          focusProjectNodeId={viewingSpecNodeId}
          onClose={() => {
            setViewingSpecId(null);
            setViewingSpecNodeId(null);
          }}
          onChanged={() => { if (selectedCardId) loadCard(selectedCardId); }}
        />
      )}

      {/* Cancellation justification (ITEM 17). stopPropagation keeps clicks
          inside the dialog from bubbling to the overlay's close handler. */}
      <div onClick={(e) => e.stopPropagation()}>
        <CancellationReasonDialog
          open={showCancelDialog}
          entityLabel="card"
          onConfirm={(reason) => {
            setShowCancelDialog(false);
            handleStatusChange('cancelled', undefined, undefined, reason);
          }}
          onCancel={() => setShowCancelDialog(false)}
        />
      </div>
    </div>
  );
}

function CardLineagePanel({
  card,
  parentSpec,
  originTask,
  linkedTestTasks,
  onOpenSpec,
}: {
  card: Card;
  parentSpec: { id: string; title: string } | null;
  originTask: {
    id: string;
    title: string;
    status: CardStatus;
    card_type?: Card['card_type'];
  } | null;
  linkedTestTasks: {
    id: string;
    card: {
      id: string;
      title: string;
      status: CardStatus;
      card_type?: Card['card_type'];
    } | null;
  }[];
  onOpenSpec: (specId: string) => void;
}) {
  const lineageType = card.card_type === 'bug'
    ? 'bug'
    : card.card_type === 'test'
      ? 'test'
      : 'task';

  return (
    <div className="space-y-4" data-testid="card-lineage-panel">
      <CardScenarioReferenceNotice context={card.scenario_reference_context} />
      <MissingLinkNotice context={card.missing_link_context} />
      <div className="grid gap-3 sm:grid-cols-3">
        <div className="rounded-lg border border-gray-200 p-3 dark:border-gray-700">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400">
            Parent spec
          </p>
          {parentSpec ? (
            <button
              type="button"
              onClick={() => onOpenSpec(parentSpec.id)}
              className="mt-1 text-left text-sm font-medium text-violet-700 hover:underline dark:text-violet-300"
            >
              {parentSpec.title}
            </button>
          ) : (
            <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
              No parent spec
            </p>
          )}
        </div>
        <div className="rounded-lg border border-gray-200 p-3 dark:border-gray-700">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400">
            Lineage graph
          </p>
          <button
            type="button"
            onClick={() => openLineageGraph(lineageType, card.id)}
            className="mt-1 inline-flex items-center gap-1 text-sm font-medium text-blue-700 hover:underline dark:text-blue-300"
          >
            <GitBranch size={14} />
            Open graph
          </button>
        </div>
      </div>

      {card.card_type === 'bug' && (
        <div
          data-testid="bug-traceability-panel"
          className="rounded-lg border border-blue-200 bg-blue-50/70 p-3 dark:border-blue-700/40 dark:bg-blue-900/10"
        >
          <div className="mb-3 flex items-center gap-2">
            <GitBranch
              size={14}
              className="text-blue-600 dark:text-blue-300"
            />
            <h3 className="text-xs font-semibold uppercase tracking-wide text-blue-900 dark:text-blue-200">
              Bug Traceability
            </h3>
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="rounded-md border border-blue-100 bg-white/70 p-3 dark:border-blue-800/60 dark:bg-gray-900/30">
              <p className="text-[10px] font-semibold uppercase tracking-wide text-blue-600 dark:text-blue-300">
                Origin Task
              </p>
              <p className="mt-1 break-words text-sm font-medium text-gray-900 dark:text-gray-100">
                {originTask?.title
                  || (card.origin_task_id
                    ? shortId(card.origin_task_id)
                    : 'Missing origin task')}
              </p>
              <div className="mt-2 flex flex-wrap items-center gap-1.5">
                <span className="inline-flex items-center gap-1 rounded bg-blue-100 px-1.5 py-0.5 text-[10px] font-medium text-blue-700 dark:bg-blue-900/40 dark:text-blue-300">
                  <FileText size={10} />
                  {originTask ? cardTypeLabel(originTask) : 'Task'}
                </span>
                {originTask && (
                  <span className="rounded bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300">
                    {STATUS_LABELS[originTask.status]}
                  </span>
                )}
              </div>
            </div>

            <div className="rounded-md border border-blue-100 bg-white/70 p-3 dark:border-blue-800/60 dark:bg-gray-900/30">
              <p className="text-[10px] font-semibold uppercase tracking-wide text-blue-600 dark:text-blue-300">
                Linked Regression Tests
              </p>
              {linkedTestTasks.length > 0 ? (
                <div className="mt-2 space-y-1.5">
                  {linkedTestTasks.map(({ id, card: testTask }) => (
                    <div
                      key={id}
                      className="flex items-start gap-2 text-sm text-gray-900 dark:text-gray-100"
                    >
                      <FlaskConical
                        size={13}
                        className="mt-0.5 shrink-0 text-violet-500"
                      />
                      <div className="min-w-0">
                        <p className="truncate font-medium">
                          {testTask?.title || shortId(id)}
                        </p>
                        {testTask && (
                          <p className="text-[10px] text-gray-500 dark:text-gray-400">
                            {STATUS_LABELS[testTask.status]}
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="mt-2 flex items-center gap-2 text-xs text-amber-700 dark:text-amber-300">
                  <AlertCircle size={13} />
                  No regression test linked
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Exported for focused component tests (SK-B2-S1 TS-11 read-only block).
export function ExecutionReportsPanel({ card }: { card: Card }) {
  const reports = card.conclusions || [];

  if (reports.length === 0) {
    return (
      <div className="py-8 text-center">
        <p className="text-sm text-gray-500 dark:text-gray-400">
          No execution report yet
        </p>
        <p className="mt-1 text-xs text-gray-400 dark:text-gray-500">
          An execution report is collected when work moves to Validation or
          Done.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3" data-testid="execution-reports-panel">
      {[...reports].reverse().map((report, index) => (
        <article
          key={`${report.created_at}-${index}`}
          className="rounded-lg border border-gray-200 p-4 dark:border-gray-700"
        >
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
            <div>
              <p className="text-xs font-semibold text-gray-700 dark:text-gray-200">
                Execution report #{reports.length - index}
              </p>
            </div>
            <span className="text-[10px] text-gray-400">
              {shortId(report.author_id)} ·{' '}
              {new Date(report.created_at).toLocaleString()}
            </span>
          </div>

          <div
            className="grid gap-4 rounded-lg border border-cyan-100 bg-cyan-50/40 p-3 sm:grid-cols-2 dark:border-cyan-900/60 dark:bg-cyan-950/15"
            data-testid={`execution-report-${index}-scores`}
          >
            <div className="flex gap-4">
              <MetricScoreRing
                label="Completeness"
                value={report.completeness}
                direction="higher-is-better"
                tone="info"
                testId={`execution-report-${index}-completeness-score`}
              />
              <div className="min-w-0 flex-1">
                <p className="text-xs font-semibold text-gray-600 dark:text-gray-300">
                  Executor justification
                </p>
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  {report.completeness_justification
                    || 'No justification recorded.'}
                </p>
              </div>
            </div>
            <div className="flex gap-4">
              <MetricScoreRing
                label="Drift"
                value={report.drift}
                direction="lower-is-better"
                tone="info"
                testId={`execution-report-${index}-drift-score`}
              />
              <div className="min-w-0 flex-1">
                <p className="text-xs font-semibold text-gray-600 dark:text-gray-300">
                  Executor justification
                </p>
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  {report.drift_justification || 'No justification recorded.'}
                </p>
              </div>
            </div>
          </div>

          <div className="mt-4" data-testid={`execution-report-${index}-summary`}>
            <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-gray-400">
              Execution summary
            </p>
            <Md>{report.text}</Md>
          </div>

          {report.delivery_manifest && <div className="mt-3 rounded border p-3 text-sm">
            <p>Sealed delivery revision {report.delivery_manifest.delivery_revision} · {report.delivery_manifest.records.length} selected records</p>
            {report.delivery_manifest.impact_basis && <p>Impact reused from recorded declarations · {report.delivery_manifest.impact_basis.length} source bases</p>}
            <code className="break-all text-xs">{report.delivery_manifest.sha256}</code>
            <p>This is the evidence presented with the report; current eligibility is evaluated separately.</p>
          </div>}
          {report.impact_evidence && (
            <div
              className="mt-4 rounded-lg border border-gray-200 bg-gray-50/60 p-3 dark:border-gray-700 dark:bg-gray-900/20"
              data-testid="impact-evidence-readonly"
            >
              <div className="flex flex-wrap items-center justify-between gap-2">
                <p className="text-xs font-semibold text-gray-700 dark:text-gray-200">
                  Impact evidence
                </p>
                <span className="rounded-full bg-gray-200/70 px-2 py-0.5 text-[10px] font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-300">
                  Agent-declared
                </span>
              </div>
              <div className="mt-3 grid gap-3 text-[11px] text-gray-600 dark:text-gray-300 lg:grid-cols-2">
                {report.impact_evidence.files.length > 0 && (
                  <section className="rounded-md border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-800/70">
                    <p className="mb-2 font-semibold text-gray-600 dark:text-gray-300">
                      Files <span className="font-normal text-gray-400">({report.impact_evidence.files.length})</span>
                    </p>
                    <ul className="space-y-2">
                      {report.impact_evidence.files.map((file, evidenceIndex) => (
                        <li key={evidenceIndex} className="min-w-0">
                          <div className="mb-1 flex flex-wrap gap-1.5">
                            <span className="rounded bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium dark:bg-gray-700">{file.repo}</span>
                            <span className="rounded bg-blue-50 px-1.5 py-0.5 text-[10px] font-medium text-blue-700 dark:bg-blue-950/40 dark:text-blue-300">
                              {humanizeEvidenceToken(file.change_kind)}
                            </span>
                          </div>
                          <code className="block break-all text-[11px] text-gray-700 dark:text-gray-200">{file.path}</code>
                          {file.previous_path && (
                            <p className="mt-1 break-all text-[10px] text-gray-400">Previously {file.previous_path}</p>
                          )}
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
                {report.impact_evidence.symbols.length > 0 && (
                  <section className="rounded-md border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-800/70">
                    <p className="mb-2 font-semibold text-gray-600 dark:text-gray-300">
                      Symbols <span className="font-normal text-gray-400">({report.impact_evidence.symbols.length})</span>
                    </p>
                    <ul className="space-y-2">
                      {report.impact_evidence.symbols.map((symbol, evidenceIndex) => (
                        <li key={evidenceIndex} className="min-w-0">
                          <div className="mb-1 flex flex-wrap gap-1.5">
                            <span className="rounded bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium dark:bg-gray-700">{humanizeEvidenceToken(symbol.kind)}</span>
                            <span className="rounded bg-violet-50 px-1.5 py-0.5 text-[10px] font-medium text-violet-700 dark:bg-violet-950/40 dark:text-violet-300">{humanizeEvidenceToken(symbol.action)}</span>
                          </div>
                          <code className="block break-all text-gray-700 dark:text-gray-200">{symbol.name}</code>
                          <p className="mt-1 break-all text-[10px] text-gray-400">{symbol.repo} · {symbol.file}</p>
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
                {report.impact_evidence.surfaces.length > 0 && (
                  <section className="rounded-md border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-800/70">
                    <p className="mb-2 font-semibold text-gray-600 dark:text-gray-300">
                      Surfaces <span className="font-normal text-gray-400">({report.impact_evidence.surfaces.length})</span>
                    </p>
                    <ul className="space-y-2">
                      {report.impact_evidence.surfaces.map((surface, evidenceIndex) => (
                        <li key={evidenceIndex}>
                          <span className="mb-1 inline-flex rounded bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium dark:bg-gray-700">{humanizeEvidenceToken(surface.kind)}</span>
                          <code className="block break-all text-gray-700 dark:text-gray-200">{surface.identifier}</code>
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
                {report.impact_evidence.tests.length > 0 && (
                  <section className="rounded-md border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-800/70">
                    <p className="mb-2 font-semibold text-gray-600 dark:text-gray-300">
                      Tests <span className="font-normal text-gray-400">({report.impact_evidence.tests.length})</span>
                    </p>
                    <ul className="space-y-2">
                      {report.impact_evidence.tests.map((test, evidenceIndex) => (
                        <li key={evidenceIndex} className="min-w-0">
                          <div className="mb-1 flex flex-wrap gap-1.5">
                            <span className="rounded bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium dark:bg-gray-700">{test.repo}</span>
                            <span className="rounded bg-emerald-50 px-1.5 py-0.5 text-[10px] font-medium text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">{humanizeEvidenceToken(test.action)}</span>
                          </div>
                          <code className="block break-all text-gray-700 dark:text-gray-200">
                            {test.test_file_path}{test.test_function ? `::${test.test_function}` : ''}
                          </code>
                          {test.scenario_id && <p className="mt-1 text-[10px] text-gray-400">Scenario {test.scenario_id}</p>}
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
                {report.impact_evidence.evidence_refs.length > 0 && (
                  <section className="rounded-md border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-800/70 lg:col-span-2">
                    <p className="mb-2 font-semibold text-gray-600 dark:text-gray-300">Evidence references</p>
                    <div className="flex flex-wrap gap-1.5">
                      {report.impact_evidence.evidence_refs.map((reference, evidenceIndex) => (
                        <code key={evidenceIndex} className="rounded bg-gray-100 px-2 py-1 text-[10px] text-gray-600 dark:bg-gray-700 dark:text-gray-200">{reference}</code>
                      ))}
                    </div>
                  </section>
                )}
              </div>
            </div>
          )}
        </article>
      ))}
    </div>
  );
}

// Exported for focused component tests (spec 9e0bf979 evidence visibility).
export function TestEvidenceTab({ scenarios }: { scenarios: TestScenario[] }) {
  const evidenceCount = scenarios.filter(hasScenarioEvidence).length;
  const missingCount = scenarios.length - evidenceCount;

  if (scenarios.length === 0) {
    return (
      <div
        data-testid="test-evidence-tab"
        className="border border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-8 text-center text-gray-500 dark:text-gray-400"
      >
        <CheckCircle size={28} strokeWidth={1.5} className="mx-auto mb-2 text-gray-400" />
        <p className="text-sm font-medium">No linked test scenarios</p>
      </div>
    );
  }

  return (
    <div data-testid="test-evidence-tab" className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-emerald-200 dark:border-emerald-800/60 bg-emerald-50/70 dark:bg-emerald-900/10 p-3">
        <div>
          <h3 className="text-xs font-semibold uppercase tracking-wide text-emerald-700 dark:text-emerald-300">Evidence Coverage</h3>
          <p className="mt-1 text-sm text-gray-700 dark:text-gray-300">
            {evidenceCount}/{scenarios.length} linked scenario{scenarios.length === 1 ? '' : 's'} with evidence
          </p>
        </div>
        <div className="flex items-center gap-2">
          {missingCount > 0 && (
            <span className="inline-flex items-center gap-1 rounded bg-amber-100 px-2 py-1 text-xs font-medium text-amber-700 dark:bg-amber-900/40 dark:text-amber-300">
              <AlertCircle size={12} />
              {missingCount} missing
            </span>
          )}
          <span className="inline-flex items-center gap-1 rounded bg-emerald-100 px-2 py-1 text-xs font-medium text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300">
            <CheckCircle size={12} />
            {evidenceCount} recorded
          </span>
        </div>
      </div>

      <div className="space-y-3">
        {scenarios.map((scenario) => {
          const evidence = getScenarioEvidence(scenario);
          const hasEvidence = hasScenarioEvidence(scenario);
          const evidenceRows = [
            // Re-executable evidence contract (spec 9e0bf979): class + artifact
            // pointers a validator can rerun/inspect without reading comments.
            { label: 'Evidence class', value: evidence?.evidence_class, mono: true },
            { label: 'Test file', value: evidence?.test_file_path, mono: true },
            { label: 'Function', value: evidence?.test_function, mono: true },
            { label: 'Replay command', value: evidence?.replay_command, mono: true },
            { label: 'Manifest (V2)', value: evidence?.manifest_ref, mono: true },
            {
              label: 'Execution attestation',
              value: evidence?.execution_attestation
                ? `v${evidence.execution_attestation.schema_version} · ${evidence.execution_attestation.run_id} · runtime ${evidence.execution_attestation.product_runtime_exercised ? 'exercised' : 'NOT exercised'}`
                : null,
              mono: true,
            },
            { label: 'Manual checklist', value: evidence?.manual_checklist_ref, mono: true },
            { label: 'Last run', value: formatEvidenceTimestamp(evidence?.last_run_at), mono: false },
            { label: 'Run ID', value: evidence?.test_run_id, mono: true },
          ].filter((row): row is { label: string; value: string; mono: boolean } => Boolean(row.value));

          return (
            <section
              key={scenario.id}
              className="rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/30 p-4"
            >
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className={`text-[10px] px-1.5 py-0.5 rounded shrink-0 ${testScenarioStatusColor(scenario.status)}`}>
                      {scenario.status}
                    </span>
                    <ScenarioTypeBadge scenarioType={scenario.scenario_type} />
                    <EvidenceBadge scenario={scenario} />
                    <VerificationReportDetails evidence={evidence} />
                  </div>
                  <h3 className="mt-2 text-sm font-semibold text-gray-900 dark:text-gray-100 break-words">{scenario.title}</h3>
                  <p className="mt-1 text-xs text-gray-500 dark:text-gray-400 break-words">
                    Given {scenario.given}{' -> '}When {scenario.when}{' -> '}Then {scenario.then}
                  </p>
                </div>
              </div>

              {hasEvidence ? (
                <div className="mt-4 space-y-3">
                  {evidenceRows.length > 0 && (
                    <dl className="grid gap-2 sm:grid-cols-2">
                      {evidenceRows.map((row) => (
                        <div key={row.label} className="rounded-md border border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/60 p-2">
                          <dt className="text-[10px] font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400">{row.label}</dt>
                          <dd className={`mt-1 text-xs text-gray-800 dark:text-gray-200 break-words ${row.mono ? 'font-mono' : ''}`}>
                            {row.value}
                          </dd>
                        </div>
                      ))}
                    </dl>
                  )}
                  {evidence?.output_snippet && (
                    <div>
                      <p className="text-[10px] font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400 mb-1">Output</p>
                      <pre className="max-h-44 overflow-auto whitespace-pre-wrap break-words rounded-md border border-gray-200 dark:border-gray-700 bg-gray-950 p-3 text-xs text-gray-100">
                        {evidence.output_snippet}
                      </pre>
                    </div>
                  )}
                  {evidence?.expected_output_snapshot && (
                    <div>
                      <p className="text-[10px] font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400 mb-1">Expected output</p>
                      <pre className="max-h-44 overflow-auto whitespace-pre-wrap break-words rounded-md border border-gray-200 dark:border-gray-700 bg-gray-950 p-3 text-xs text-gray-100">
                        {evidence.expected_output_snapshot}
                      </pre>
                    </div>
                  )}
                  {evidence?.non_replayable_justification && (
                    <div className="rounded-md border border-amber-200 dark:border-amber-800/60 bg-amber-50 dark:bg-amber-900/10 p-3">
                      <p className="text-[10px] font-semibold uppercase tracking-wide text-amber-700 dark:text-amber-300 mb-1">Non-replayable justification</p>
                      <p className="whitespace-pre-wrap break-words text-xs text-amber-800 dark:text-amber-200">
                        {evidence.non_replayable_justification}
                      </p>
                    </div>
                  )}
                </div>
              ) : (
                <div className="mt-4 flex items-center gap-2 rounded-md border border-amber-200 dark:border-amber-800/60 bg-amber-50 dark:bg-amber-900/10 px-3 py-2 text-xs text-amber-700 dark:text-amber-300">
                  <AlertCircle size={14} className="shrink-0" />
                  No evidence recorded
                </div>
              )}
            </section>
          );
        })}
      </div>
    </div>
  );
}

// Test Scenarios section in Details tab
function TestScenariosSection({
  card, specId, scenarios, api, onUpdate, canLink = true,
}: {
  card: Card;
  specId: string;
  scenarios: TestScenario[];
  api: ReturnType<typeof useDashboardApi>;
  onUpdate: (card: Card, scenarios: TestScenario[]) => void;
  canLink?: boolean;
}) {
  const linkedIds = new Set(card.test_scenario_ids || []);
  const linked = scenarios.filter((s) => linkedIds.has(s.id));
  const unlinked = scenarios.filter((s) => !linkedIds.has(s.id));
  const [showPicker, setShowPicker] = useState(false);

  const handleLink = async (scenarioId: string) => {
    try {
      await api.linkTaskToScenario(specId, scenarioId, card.id);
      // Refresh card and spec
      const [updatedCard, updatedSpec] = await Promise.all([
        api.getCard(card.id),
        api.getSpec(specId),
      ]);
      onUpdate(updatedCard, updatedSpec.test_scenarios || []);
      toast.success('Scenario linked');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to link scenario');
    }
  };

  const handleUnlink = async (scenarioId: string) => {
    try {
      await api.unlinkTaskFromScenario(specId, scenarioId, card.id);
      const [updatedCard, updatedSpec] = await Promise.all([
        api.getCard(card.id),
        api.getSpec(specId),
      ]);
      onUpdate(updatedCard, updatedSpec.test_scenarios || []);
      toast.success('Scenario unlinked');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to unlink scenario');
    }
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">
          <FlaskConical size={14} className="inline mr-1" />
          Test Scenarios ({linked.length}/{scenarios.length})
        </h3>
        {canLink && unlinked.length > 0 && (
          <button
            onClick={() => setShowPicker(!showPicker)}
            className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300"
          >
            {showPicker ? 'Cancel' : '+ Link scenario'}
          </button>
        )}
      </div>

      {/* Linked scenarios */}
      <div className="space-y-1">
        {linked.map((s) => (
          <div
            key={s.id}
            className="flex items-center justify-between px-2 py-1.5 rounded bg-violet-50 dark:bg-violet-900/10 text-xs group"
          >
            <div className="flex items-center gap-2 flex-1 min-w-0">
              <span className={`text-[10px] px-1 py-0.5 rounded shrink-0 ${testScenarioStatusColor(s.status)}`}>
                {s.status}
              </span>
              <span className="text-gray-700 dark:text-gray-300 truncate">{s.title}</span>
              <ScenarioTypeBadge scenarioType={s.scenario_type} />
            </div>
            {canLink && (
              <button
                onClick={() => handleUnlink(s.id)}
                className="p-0.5 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
                title="Unlink scenario"
              >
                <Unlink size={12} />
              </button>
            )}
          </div>
        ))}
        {linked.length === 0 && (
          <p className="text-xs text-gray-400 dark:text-gray-500 italic">
            No test scenarios linked to this card
          </p>
        )}
      </div>

      {/* Picker for unlinked scenarios */}
      {canLink && showPicker && unlinked.length > 0 && (
        <div className="mt-2 border border-gray-200 dark:border-gray-700 rounded-lg p-2 space-y-1 max-h-40 overflow-y-auto">
          <p className="text-[10px] text-gray-400 mb-1">Click to link:</p>
          {unlinked.map((s) => (
            <button
              key={s.id}
              onClick={() => handleLink(s.id)}
              className="w-full flex items-center gap-2 px-2 py-1.5 rounded text-xs text-left hover:bg-violet-50 dark:hover:bg-violet-900/20 transition-colors"
            >
              <span className={`text-[10px] px-1 py-0.5 rounded shrink-0 ${testScenarioStatusColor(s.status)}`}>
                {s.status}
              </span>
              <span className="text-gray-600 dark:text-gray-400 truncate">{s.title}</span>
              <Link size={10} className="text-gray-400 shrink-0 ml-auto" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Generic section for linking spec items (BRs, Contracts, TRs) to a card.
 * Mirrors TestScenariosSection but works with any spec item type that has {id, linked_task_ids}.
 */
function LinkedSpecItemsSection({
  card, specId, items, field, label, icon, api, onSpecRefresh,
  onSubjectChanged, canLink = true,
}: {
  card: Card;
  specId: string;
  items: { id: string; title?: string; text?: string; method?: string; path?: string; linked_task_ids?: string[] | null }[];
  field: 'business_rules' | 'api_contracts' | 'technical_requirements' | 'integration_requirements' | 'observability_requirements';
  label: string;
  icon: React.ReactNode;
  api: ReturnType<typeof useDashboardApi>;
  onSpecRefresh: () => void;
  onSubjectChanged: () => void;
  canLink?: boolean;
}) {
  const linkedItems = items.filter(i => (i.linked_task_ids || []).includes(card.id));
  const unlinkedItems = items.filter(i => !(i.linked_task_ids || []).includes(card.id));
  const [showPicker, setShowPicker] = useState(false);

  const itemLabel = (item: typeof items[0]) =>
    item.title || item.text || (item.method && item.path ? `${item.method} ${item.path}` : item.id);

  const handleLink = async (itemId: string) => {
    try {
      await api.linkTaskToSpecItem(specId, field, itemId, card.id);
      onSpecRefresh();
      onSubjectChanged();
      toast.success(`${label} linked`);
    } catch {
      toast.error(`Failed to link ${label.toLowerCase()}`);
    }
  };

  const handleUnlink = async (itemId: string) => {
    try {
      await api.unlinkTaskFromSpecItem(specId, field, itemId, card.id);
      onSpecRefresh();
      onSubjectChanged();
      toast.success(`${label} unlinked`);
    } catch {
      toast.error(`Failed to unlink ${label.toLowerCase()}`);
    }
  };

  if (items.length === 0) return null;

  return (
    <div>
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400">
          {icon} {label} ({linkedItems.length}/{items.length})
        </h3>
        {canLink && unlinkedItems.length > 0 && (
          <button
            onClick={() => setShowPicker(!showPicker)}
            className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400"
          >
            {showPicker ? 'Cancel' : `+ Link ${label.toLowerCase()}`}
          </button>
        )}
      </div>
      <div className="space-y-1">
        {linkedItems.map((item) => (
          <div key={item.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-indigo-50 dark:bg-indigo-900/10 text-xs group">
            <span className="text-gray-700 dark:text-gray-300 truncate flex-1">{itemLabel(item)}</span>
            {canLink && (
              <button onClick={() => handleUnlink(item.id)} className="p-0.5 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity shrink-0" title="Unlink">
                <Unlink size={12} />
              </button>
            )}
          </div>
        ))}
        {linkedItems.length === 0 && (
          <p className="text-xs text-gray-400 dark:text-gray-500 italic">No {label.toLowerCase()} linked to this card</p>
        )}
      </div>
      {canLink && showPicker && unlinkedItems.length > 0 && (
        <div className="mt-2 border border-gray-200 dark:border-gray-700 rounded-lg p-2 space-y-1 max-h-40 overflow-y-auto">
          <p className="text-[10px] text-gray-400 mb-1">Click to link:</p>
          {unlinkedItems.map((item) => (
            <button key={item.id} onClick={() => handleLink(item.id)} className="w-full flex items-center gap-2 px-2 py-1.5 rounded text-xs text-left hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-colors">
              <span className="text-gray-600 dark:text-gray-400 truncate">{itemLabel(item)}</span>
              <Link size={10} className="text-gray-400 shrink-0 ml-auto" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Q&A Tab Component
// Dependencies section in Details tab
function DependenciesSection({
  cardId, dependencies, dependents, setDependencies, api, allCards,
  onSubjectChanged, canManage = true,
}: {
  cardId: string;
  dependencies: { id: string; title: string; status: string }[];
  dependents: { id: string; title: string; status: string }[];
  setDependencies: (d: { id: string; title: string; status: string }[]) => void;
  api: ReturnType<typeof useDashboardApi>;
  allCards: { id: string; title: string; status: string }[];
  onSubjectChanged: () => void;
  canManage?: boolean;
}) {
  const [selectedDepId, setSelectedDepId] = useState('');

  const statusColor = (s: string) => {
    if (s === 'done') return 'text-green-600';
    if (s === 'rejected') return 'text-rose-600 dark:text-rose-400';
    if (s === 'cancelled') return 'text-gray-400 dark:text-gray-500';
    return 'text-amber-600';
  };

  // Cards available for selection: exclude self, existing dependencies, and dependents
  const excludedIds = new Set([cardId, ...dependencies.map((d) => d.id), ...dependents.map((d) => d.id)]);
  const availableCards = allCards.filter((c) => !excludedIds.has(c.id));

  const handleAdd = async () => {
    if (!selectedDepId) return;
    try {
      await api.addCardDependency(cardId, selectedDepId);
      const fresh = await api.getCardDependencies(cardId);
      setDependencies(fresh);
      setSelectedDepId('');
      onSubjectChanged();
      toast.success('Dependency added');
    } catch (e: any) {
      const msg = e?.message?.includes('409') ? 'Circular or duplicate dependency' : 'Failed to add dependency';
      toast.error(msg);
    }
  };

  const handleRemove = async (depId: string) => {
    try {
      await api.removeCardDependency(cardId, depId);
      setDependencies(dependencies.filter((d) => d.id !== depId));
      onSubjectChanged();
      toast.success('Dependency removed');
    } catch {
      toast.error('Failed to remove dependency');
    }
  };

  const hasBlocking = dependencies.some((d) => d.status !== 'done' && d.status !== 'cancelled');

  return (
    <div>
      <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-2">
        <Link size={14} className="inline mr-1" />
        Dependencies
        {hasBlocking && (
          <span className="ml-2 text-xs text-amber-600 font-normal">Blocked</span>
        )}
      </h3>

      {/* Depends on */}
      {dependencies.length > 0 && (
        <div className="mb-2">
          <p className="text-xs text-gray-400 dark:text-gray-500 mb-1">Depends on:</p>
          <div className="space-y-1">
            {dependencies.map((d) => (
              <div key={d.id} className="flex items-center justify-between px-2 py-1 bg-gray-50 dark:bg-gray-800 rounded text-sm text-gray-700 dark:text-gray-300">
                <span className={statusColor(d.status)}>
                  {d.status === 'done' ? '✓' : d.status === 'cancelled' ? '✗' : '●'}{' '}
                  {d.title}
                </span>
                {canManage && (
                  <button onClick={() => handleRemove(d.id)} className="p-0.5 text-gray-400 dark:text-gray-500 hover:text-red-500" title="Remove dependency">
                    <Unlink size={12} />
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Dependents */}
      {dependents.length > 0 && (
        <div className="mb-2">
          <p className="text-xs text-gray-400 dark:text-gray-500 mb-1">Blocks:</p>
          <div className="space-y-1">
            {dependents.map((d) => (
              <div key={d.id} className="px-2 py-1 bg-gray-50 dark:bg-gray-800 rounded text-sm text-gray-600 dark:text-gray-400">
                {d.title}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Add dependency */}
      {canManage && (
      <div className="flex gap-2 mt-2">
        <select
          value={selectedDepId}
          onChange={(e) => setSelectedDepId(e.target.value)}
          className="flex-1 px-2 py-1 text-xs border border-gray-300 rounded dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100"
        >
          <option value="">Select a card...</option>
          {availableCards.map((c) => (
            <option key={c.id} value={c.id}>
              [{STATUS_LABELS[c.status as CardStatus] || c.status}] {c.title}
            </option>
          ))}
        </select>
        <button onClick={handleAdd} disabled={!selectedDepId} className="text-xs px-2 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed">
          Add
        </button>
      </div>
      )}
    </div>
  );
}

// Seen-by indicator for items
type SeenRecord = { agent_name: string; seen_at: string };
type SeenMap = Record<string, SeenRecord[]>;

function SeenByIndicator({ itemId, seenStatus }: { itemId: string; seenStatus: SeenMap }) {
  const viewers = seenStatus[itemId];
  if (!viewers || viewers.length === 0) return null;

  return (
    <div className="flex items-center gap-1 mt-1">
      <span className="text-[10px] text-gray-400 dark:text-gray-500">Seen by:</span>
      {viewers.map((v, i) => (
        <span
          key={i}
          className="inline-flex items-center px-1.5 py-0.5 rounded-full bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 text-[10px] font-medium"
          title={`${v.agent_name} at ${new Date(v.seen_at).toLocaleString('en-US')}`}
        >
          {v.agent_name}
        </span>
      ))}
    </div>
  );
}

function QATab({
  card,
  onCardChanged,
  api,
  members,
  seenStatus,
  canAsk,
  canAnswer,
}: {
  card: Card;
  onCardChanged: (card: Card) => void;
  api: ReturnType<typeof useDashboardApi>;
  members: { id: string; name: string }[];
  seenStatus: SeenMap;
  canAsk: boolean;
  canAnswer: boolean;
}) {
  const [newQuestion, setNewQuestion] = useState('');
  const [answerInput, setAnswerInput] = useState<Record<string, string>>({});

  const reconcileQAItems = (qaItems: Card['qa_items']) => {
    onCardChanged({
      ...card,
      qa_items: qaItems,
      open_qa_count: qaItems.filter((qa) => qa.answered_at == null).length,
    });
  };

  const handleAskQuestion = async () => {
    if (!newQuestion.trim()) return;

    try {
      const qa = await api.createQuestion(card.id, { question: newQuestion });
      reconcileQAItems([...card.qa_items, qa]);
      setNewQuestion('');
      toast.success('Question added');
    } catch {
      toast.error('Failed to add question');
    }
  };

  const handleAnswer = async (qaId: string) => {
    const answer = answerInput[qaId];
    if (!answer?.trim()) return;

    try {
      const updated = await api.answerQuestion(qaId, { answer });
      reconcileQAItems(
        card.qa_items.map((q) => (q.id === qaId ? updated : q)),
      );
      setAnswerInput({ ...answerInput, [qaId]: '' });
      toast.success('Answer saved');
    } catch {
      toast.error('Failed to answer');
    }
  };

  return (
    <div className="space-y-4">
      {/* Add question */}
      {canAsk && (
        <div className="flex gap-2">
          <div className="flex-1">
            <MentionInput
              value={newQuestion}
              onChange={setNewQuestion}
              members={members}
              placeholder="Add a question... (use @ to mention)"
            />
          </div>
          <button onClick={handleAskQuestion} className="btn btn-primary">
            Ask
          </button>
        </div>
      )}

      {/* Questions list */}
      <div className="space-y-3">
        {card.qa_items.map((qa) => (
          <div key={qa.id} className="border rounded-lg p-3 dark:border-gray-700">
            <div className="font-medium text-gray-900 dark:text-gray-100">
              <HelpCircle size={14} className="inline mr-1 align-text-top" />
              <Md className="inline">{qa.question}</Md>
            </div>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-0.5 pl-5">
              Asked by <span className="font-medium text-gray-500 dark:text-gray-400">{resolveActorName(qa.asked_by, members)}</span>
            </p>

            {qa.answer ? (
              <div className="mt-2 text-gray-600 dark:text-gray-400 text-sm pl-5">
                <Md>{qa.answer}</Md>
                <p className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                  Answered by <span className="font-medium text-gray-500 dark:text-gray-400">{resolveActorName(qa.answered_by, members)}</span>
                </p>
              </div>
            ) : canAnswer ? (
              <div className="mt-2 flex gap-2 pl-5">
                <input
                  type="text"
                  value={answerInput[qa.id] || ''}
                  onChange={(e) => setAnswerInput({ ...answerInput, [qa.id]: e.target.value })}
                  placeholder="Answer..."
                  className="flex-1 px-2 py-1 text-sm border border-gray-300 rounded dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100"
                />
                <button
                  onClick={() => handleAnswer(qa.id)}
                  className="text-sm px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700"
                >
                  Answer
                </button>
              </div>
            ) : (
              <p className="mt-2 pl-5 text-xs italic text-gray-400 dark:text-gray-500">
                Awaiting an answer from an authorized contributor.
              </p>
            )}
            <SeenByIndicator itemId={qa.id} seenStatus={seenStatus} />
          </div>
        ))}

        {card.qa_items.length === 0 && (
          <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-4">
            No questions yet
          </p>
        )}
      </div>
    </div>
  );
}

function validationVerdict(
  validation: ValidationEntry,
): 'pass' | 'fail' {
  return validation.outcome === 'success' ? 'pass' : 'fail';
}

function validationMetricStatus(
  validation: ValidationEntry,
  metric: 'confidence' | 'completeness' | 'drift',
): 'met' | 'not-met' | 'neutral' {
  if (!validation.threshold_violations) return 'neutral';
  return validation.threshold_violations.some((violation) =>
    violation.toLowerCase().includes(metric)
  )
    ? 'not-met'
    : 'met';
}

function ValidationMetricInput({
  id,
  label,
  value,
  direction,
  threshold,
  thresholdSource,
  justification,
  onValueChange,
  onJustificationChange,
}: {
  id: string;
  label: string;
  value: number;
  direction: 'higher-is-better' | 'lower-is-better';
  threshold: number;
  thresholdSource: TaskValidationThresholdSource;
  justification: string;
  onValueChange: (value: number) => void;
  onJustificationChange: (value: string) => void;
}) {
  return (
    <div className="flex gap-4 rounded-lg border border-violet-200 bg-white p-3 dark:border-violet-800 dark:bg-gray-900/20">
      <MetricScoreRing
        label={label}
        value={value}
        direction={direction}
        threshold={threshold}
        tone="info"
        testId={`${id}-score`}
      />
      <div className="min-w-0 flex-1">
        <p
          className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-violet-500 dark:text-violet-300"
          data-testid={`${id}-threshold-source`}
        >
          Threshold source: {thresholdSource}
        </p>
        <label
          htmlFor={id}
          className="text-xs font-medium text-gray-600 dark:text-gray-400"
        >
          {label} score
        </label>
        <input
          id={id}
          type="range"
          min={0}
          max={100}
          value={value}
          onChange={(event) => onValueChange(Number(event.target.value))}
          className="mt-2 w-full"
        />
        <textarea
          value={justification}
          onChange={(event) => onJustificationChange(event.target.value)}
          placeholder={`Justify the ${label.toLowerCase()} score...`}
          className="mt-2 w-full resize-none rounded-lg border border-gray-300 px-3 py-2 text-xs text-gray-900 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
          rows={3}
        />
        <p className="mt-1 text-[10px] text-gray-500 dark:text-gray-400">
          Minimum 10 characters.
        </p>
      </div>
    </div>
  );
}

function ValidationHistoryMetric({
  label,
  value,
  direction,
  threshold,
  thresholdSource,
  status,
  justification,
  testId,
}: {
  label: string;
  value: number;
  direction: 'higher-is-better' | 'lower-is-better';
  threshold: number | null;
  thresholdSource?: string | null;
  status: 'met' | 'not-met' | 'neutral';
  justification?: string | null;
  testId: string;
}) {
  return (
    <div
      className="flex h-full flex-col rounded-lg border border-gray-200 bg-white p-3 dark:border-gray-700 dark:bg-gray-900/20"
      data-testid={`${testId}-metric`}
    >
      <div className="flex justify-center">
        <MetricScoreRing
          label={label}
          value={value}
          direction={direction}
          threshold={threshold}
          status={status}
          testId={testId}
        />
      </div>
      <div
        className="mt-3 min-w-0 border-t border-gray-100 pt-3 dark:border-gray-700"
        data-testid={`${testId}-justification`}
      >
        {thresholdSource && (
          <p className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-gray-400 dark:text-gray-500">
            Threshold source: {thresholdSource}
          </p>
        )}
        <p className="text-xs font-semibold text-gray-600 dark:text-gray-300">
          Reviewer justification
        </p>
        <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
          {justification || 'No justification recorded.'}
        </p>
      </div>
    </div>
  );
}

// Validations Tab Component
function ValidationsTab({
  boardId,
  card,
  onCardChanged,
  api,
  members,
  canSubmit,
  thresholds,
  thresholdsLoading,
  thresholdsError,
  onRetryThresholds,
  canStartRework,
  reworkBusy,
  onStartRework,
}: {
  boardId: string;
  card: Card;
  onCardChanged: (card: Card) => void;
  api: ReturnType<typeof useDashboardApi>;
  members: { id: string; name: string }[];
  canSubmit: boolean;
  thresholds: ResolvedTaskValidationThresholds | null;
  thresholdsLoading: boolean;
  thresholdsError: string | null;
  onRetryThresholds: () => void;
  canStartRework: boolean;
  reworkBusy: boolean;
  onStartRework: () => Promise<boolean>;
}) {
  const [confidence, setConfidence] = useState(80);
  const [completeness, setCompleteness] = useState(80);
  const [drift, setDrift] = useState(20);
  const [confidenceJustification, setConfidenceJustification] = useState('');
  const [completenessJustification, setCompletenessJustification] = useState('');
  const [driftJustification, setDriftJustification] = useState('');
  const [generalJustification, setGeneralJustification] = useState('');
  const [recommendation, setRecommendation] =
    useState<'approve' | 'reject'>('approve');
  const [submitting, setSubmitting] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const validationIntentRef = useRef({ signature: '', idempotencyKey: '' });
  const learningPermissions = usePermissions(boardId);
  const canSelectLearning = !learningPermissions.isLoading && !learningPermissions.error
    && ['board.read', 'card.entity.read', 'card.entity.context_read', 'card.validation.read',
      'card.comments.read', 'card.conclusion.read', 'card.tests.read', 'spec.entity.read',
      'spec.tests.read', 'kg.query.learning_from_bugs'].every(learningPermissions.has);
  const learningScope = `${boardId}:${card.id}:${card.subject_version}`;
  const [learningChoice, setLearningChoice] = useState<{ scope: string; value: LearningCaptureSelection } | null>(null);
  const onLearningChange = useCallback((value: LearningCaptureSelection | null) => {
    setLearningChoice(value ? { scope: learningScope, value } : null);
  }, [learningScope]);
  useEffect(() => {
    if (!canSelectLearning || recommendation !== 'approve') setLearningChoice(null);
  }, [canSelectLearning, recommendation]);
  const validations = card.validations || [];
  const latestFailedValidation = [...validations]
    .reverse()
    .find((validation) => validationVerdict(validation) === 'fail') ?? null;
  const currentRejectionRecord = card.current_rejection_id
    ? (card.rejection_records || []).find(
      (record) => record.id === card.current_rejection_id,
    ) ?? null
    : null;
  const currentRejectionValidation = card.status === 'rejected'
    ? [...validations].reverse().find((validation) => (
      validation.id === card.current_rejection_id
      || validation.id === currentRejectionRecord?.source_id
      || validation.rejection_cause?.id === card.current_rejection_id
      || (
        validation.card_status === 'rejected'
        && validation.completion_outcome === 'rejected'
      )
    )) ?? null
    : null;
  const rejectionFeedbackValidation =
    currentRejectionValidation ?? latestFailedValidation;
  const rejectionFeedbackValidationId = rejectionFeedbackValidation?.id ?? null;
  const formValid =
    confidenceJustification.trim().length >= 10
    && completenessJustification.trim().length >= 10
    && driftJustification.trim().length >= 10
    && generalJustification.trim().length >= 20;

  useEffect(() => {
    if (card.status === 'rejected' && rejectionFeedbackValidationId) {
      setExpandedId(rejectionFeedbackValidationId);
    }
  }, [card.id, card.status, rejectionFeedbackValidationId]);

  const handleSubmit = async () => {
    if (!formValid || !thresholds || thresholdsLoading || thresholdsError) return;
    if (!Number.isInteger(card.subject_version) || Number(card.subject_version) < 1) {
      toast.error('Reload the card before submitting validation; its current version is unavailable.');
      return;
    }
    setSubmitting(true);
    try {
      const request = {
        expected_subject_version: Number(card.subject_version),
        confidence,
        confidence_justification: confidenceJustification.trim(),
        estimated_completeness: completeness,
        completeness_justification: completenessJustification.trim(),
        estimated_drift: drift,
        drift_justification: driftJustification.trim(),
        general_justification: generalJustification.trim(),
        recommendation,
        ...(card.card_type === 'bug' && recommendation === 'approve' && canSelectLearning
          && learningChoice?.scope === learningScope ? { learning_capture: learningChoice.value } : {}),
      };
      const signature = JSON.stringify(request);
      if (
        validationIntentRef.current.signature !== signature
        || !validationIntentRef.current.idempotencyKey
      ) {
        validationIntentRef.current = {
          signature,
          idempotencyKey: uuidv4(),
        };
      }
      const data = {
        ...request,
        idempotency_key: validationIntentRef.current.idempotencyKey,
      };
      const validation = await api.submitTaskValidation(card.id, data);
      let updatedCard: Card;
      try {
        updatedCard = await api.getCard(card.id);
      } catch {
        const cause = validation.rejection_cause ?? null;
        const rejected = validation.card_status === 'rejected';
        updatedCard = {
          ...card,
          status: validation.card_status || card.status,
          subject_version: validation.subject_version ?? card.subject_version,
          current_rejection_kind: rejected
            ? cause?.kind ?? card.current_rejection_kind ?? null
            : null,
          current_rejection_id: rejected
            ? cause?.id ?? card.current_rejection_id ?? null
            : null,
          current_rejection_code: rejected
            ? cause?.code ?? card.current_rejection_code ?? null
            : null,
          current_rejection_summary: rejected
            ? cause?.summary ?? card.current_rejection_summary ?? null
            : null,
          validations: [...(card.validations || []), validation],
        };
      }
      onCardChanged(updatedCard);
      setExpandedId(validation.id);
      // Reset form
      setConfidence(80);
      setCompleteness(80);
      setDrift(20);
      setConfidenceJustification('');
      setCompletenessJustification('');
      setDriftJustification('');
      setGeneralJustification('');
      setRecommendation('approve');
      setLearningChoice(null);
      validationIntentRef.current = { signature: '', idempotencyKey: '' };
      toast.success('Validation submitted');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to submit validation');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      {card.status === 'rejected' && card.card_type !== 'test' && (
        <section
          role="alert"
          aria-labelledby={`rejected-rework-${card.id}`}
          data-testid="task-rejected-rework-panel"
          className="rounded-xl border border-rose-300 bg-rose-50 p-4 text-rose-900 dark:border-rose-800 dark:bg-rose-950/25 dark:text-rose-100"
        >
          <div className="flex items-start gap-3">
            <ShieldX size={20} className="mt-0.5 shrink-0 text-rose-600 dark:text-rose-300" />
            <div className="min-w-0 flex-1">
              <h3 id={`rejected-rework-${card.id}`} className="text-sm font-semibold">
                Rejected — rework required
              </h3>
              <p className="mt-1 text-xs text-rose-800 dark:text-rose-200">
                {card.current_rejection_summary
                  || (rejectionFeedbackValidation
                  ? rejectionFeedbackValidation.general_justification
                    || 'The latest Task Validation did not pass.'
                  : 'The latest governed completion attempt did not pass. Review the available validation, policy and activity feedback before rework.')}
              </p>
              {(rejectionFeedbackValidation?.threshold_violations?.length || 0) > 0 && (
                <ul className="mt-2 list-disc space-y-1 pl-4 text-xs text-rose-800 dark:text-rose-200">
                  {rejectionFeedbackValidation!.threshold_violations!.map((violation) => (
                    <li key={violation}>{violation}</li>
                  ))}
                </ul>
              )}
              {(rejectionFeedbackValidation?.completion_gate_failures?.length || 0) > 0 && (
                <div className="mt-3 rounded-md border border-rose-300/80 bg-white/55 p-3 dark:border-rose-800 dark:bg-rose-950/30">
                  <p className="text-xs font-semibold text-rose-900 dark:text-rose-100">
                    Completion gates requiring action
                  </p>
                  <ul className="mt-1.5 space-y-2 text-xs text-rose-800 dark:text-rose-200">
                    {rejectionFeedbackValidation!.completion_gate_failures!.map((failure) => (
                      <li key={`${failure.code}:${failure.summary}`}>
                        <span className="font-semibold">{failure.summary}</span>
                        {(failure.reason_codes?.length || 0) > 0 && (
                          <span className="mt-0.5 block text-[11px] text-rose-700 dark:text-rose-300">
                            {failure.reason_codes!.join(' · ')}
                          </span>
                        )}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
              <p className="mt-2 text-xs text-rose-700 dark:text-rose-300">
                Move to In Progress to begin a new execution attempt. A new
                execution report and Current technical traceability are
                required before the card can return to Validation.
              </p>
              <div className="mt-3 flex flex-wrap items-center gap-3">
                <button
                  type="button"
                  onClick={() => { void onStartRework(); }}
                  disabled={!canStartRework || reworkBusy}
                  className="rounded-md bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {reworkBusy ? 'Starting rework…' : 'Move to In Progress for rework'}
                </button>
                <ContextualHelpLink
                  sectionId="tasks"
                  className="text-xs text-rose-700 dark:text-rose-200"
                  ariaLabel="Open help about Rejected task rework"
                >
                  Rejected lifecycle help
                </ContextualHelpLink>
              </div>
              {!canStartRework && (
                <p className="mt-2 text-[11px] text-rose-700 dark:text-rose-300">
                  Your current role cannot start this rework attempt.
                </p>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Section A: Submit Validation Form — only when status === 'validation' */}
      {card.status === 'validation' && canSubmit && thresholds && (
        <div
          className="bg-violet-50 dark:bg-violet-900/20 border border-violet-200 dark:border-violet-700 rounded-xl p-5 space-y-5"
          aria-busy={thresholdsLoading}
        >
          <h3 className="text-sm font-semibold text-violet-800 dark:text-violet-200 flex items-center gap-2">
            <Shield size={16} />
            Submit Validation
          </h3>

          {thresholdsLoading && (
            <div
              role="status"
              className="rounded-lg border border-violet-300 bg-white/70 px-3 py-2 text-xs text-violet-800 dark:border-violet-700 dark:bg-gray-900/40 dark:text-violet-200"
            >
              Refreshing authoritative Task Validation thresholds. Submission is temporarily disabled.
            </div>
          )}

          <div className="grid gap-4 xl:grid-cols-3">
            <ValidationMetricInput
              id="task-validation-confidence"
              label="Confidence"
              value={confidence}
              direction="higher-is-better"
              threshold={thresholds.min_confidence}
              thresholdSource={thresholds.resolved_sources.min_confidence}
              justification={confidenceJustification}
              onValueChange={setConfidence}
              onJustificationChange={setConfidenceJustification}
            />
            <ValidationMetricInput
              id="task-validation-completeness"
              label="Completeness"
              value={completeness}
              direction="higher-is-better"
              threshold={thresholds.min_completeness}
              thresholdSource={thresholds.resolved_sources.min_completeness}
              justification={completenessJustification}
              onValueChange={setCompleteness}
              onJustificationChange={setCompletenessJustification}
            />
            <ValidationMetricInput
              id="task-validation-drift"
              label="Drift"
              value={drift}
              direction="lower-is-better"
              threshold={thresholds.max_drift}
              thresholdSource={thresholds.resolved_sources.max_drift}
              justification={driftJustification}
              onValueChange={setDrift}
              onJustificationChange={setDriftJustification}
            />
          </div>

          {/* General Justification */}
          <div>
            <label className="text-xs font-medium text-gray-600 dark:text-gray-400 block mb-1">General Justification</label>
            <textarea
              value={generalJustification}
              onChange={(e) => setGeneralJustification(e.target.value)}
              placeholder="Overall validation summary..."
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-xs dark:bg-gray-700 resize-none text-gray-900 dark:text-gray-100"
              rows={3}
            />
          </div>

          {/* Approve/Reject Toggle */}
          <div className="flex items-center gap-2">
            <button
              onClick={() => setRecommendation('approve')}
              type="button"
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                recommendation === 'approve'
                  ? 'bg-green-600 text-white ring-2 ring-green-300 dark:ring-green-700'
                  : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              <CheckCircle size={16} />
              Approve
            </button>
            <button
              onClick={() => setRecommendation('reject')}
              type="button"
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                recommendation === 'reject'
                  ? 'bg-red-600 text-white ring-2 ring-red-300 dark:ring-red-700'
                  : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              <XCircle size={16} />
              Reject
            </button>
          </div>

          {card.card_type === 'bug' && recommendation === 'approve' && canSelectLearning && (
            <LearningCaptureSelector key={learningScope} boardId={boardId} bugId={card.id}
              disabled={submitting} onChange={onLearningChange} />
          )}

          {/* Submit */}
          <button
            onClick={handleSubmit}
            disabled={submitting || !formValid || thresholdsLoading || Boolean(thresholdsError)}
            className={`w-full py-2.5 rounded-lg text-sm font-medium transition-colors ${
              recommendation === 'approve'
                ? 'bg-green-600 hover:bg-green-700 text-white'
                : 'bg-red-600 hover:bg-red-700 text-white'
            } disabled:opacity-50`}
          >
            {submitting
              ? 'Submitting...'
              : `Submit Validation (${recommendation === 'approve' ? 'Approve' : 'Reject'})`}
          </button>
          {!formValid && (
            <p className="text-xs text-violet-700 dark:text-violet-300">
              Each metric justification requires at least 10 characters and
              the general justification requires at least 20.
            </p>
          )}
        </div>
      )}
      {card.status === 'validation' && canSubmit && !thresholds && thresholdsError && (
        <div
          role="alert"
          className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-950/20 dark:text-red-200"
        >
          <p>{thresholdsError} Retry before submitting Task Validation.</p>
          <button
            type="button"
            onClick={onRetryThresholds}
            className="mt-2 rounded-md border border-current/30 px-2.5 py-1 text-xs font-semibold hover:bg-red-100 dark:hover:bg-red-900/30"
          >
            Retry thresholds
          </button>
        </div>
      )}
      {card.status === 'validation' && canSubmit && !thresholds && !thresholdsError && (
        <div className="rounded-lg border border-violet-200 bg-violet-50 p-3 text-sm text-violet-800 dark:border-violet-800 dark:bg-violet-950/20 dark:text-violet-200">
          {thresholdsLoading
            ? 'Resolving effective Task Validation thresholds…'
            : 'Task Validation thresholds are not available yet.'}
        </div>
      )}
      {card.status === 'validation' && !canSubmit && (
        <div className="rounded-lg border border-violet-200 bg-violet-50 p-3 text-sm text-violet-800 dark:border-violet-800 dark:bg-violet-950/20 dark:text-violet-200">
          This card is awaiting independent validation. Your current role can
          read the history but cannot submit Task Validation.
        </div>
      )}

      {/* Section B: Validation History — always visible */}
      <div>
        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3 flex items-center gap-2">
          <Clock size={14} />
          Validation History
        </h3>

        {validations.length === 0 ? (
          <div className="text-center py-8">
            <Shield size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
            <p className="text-sm text-gray-500 dark:text-gray-400">No validations yet</p>
            {card.status !== 'validation' && card.status !== 'rejected' && (
              <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                Move this card to "Validation" status to submit a validation
              </p>
            )}
          </div>
        ) : (
          <div className="space-y-2">
            {[...validations].reverse().map((v) => {
              const isExpanded = expandedId === v.id;
              const verdict = validationVerdict(v);
              const completenessScore =
                v.estimated_completeness ?? 0;
              const driftScore = v.estimated_drift ?? 0;
              const summary = v.general_justification;
              const evaluatorId = v.reviewer_id;
              return (
                <div key={v.id} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                  <div
                    className="flex items-center gap-2 px-3 py-2.5 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700/30"
                    onClick={() => setExpandedId(isExpanded ? null : v.id)}
                  >
                    <div className={`w-2 h-2 rounded-full shrink-0 ${verdict === 'pass' ? 'bg-green-500' : 'bg-red-500'}`} />
                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-semibold shrink-0 ${
                      verdict === 'pass'
                        ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300'
                        : 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300'
                    }`}>
                      {verdict === 'pass' ? 'SUCCESS' : 'FAILED'}
                    </span>
                    <span className="text-sm text-gray-700 dark:text-gray-300 truncate flex-1">
                      {summary || (verdict === 'pass' ? 'Validation passed' : 'Validation failed')}
                    </span>
                    <div className="flex items-center gap-2 shrink-0 text-[10px] text-gray-400">
                      <span className="px-1 py-0.5 rounded bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-300">
                        {resolveActorName(evaluatorId, members)}
                      </span>
                      <span>{v.created_at ? new Date(v.created_at).toLocaleString() : ''}</span>
                    </div>
                    <span className="text-gray-400 shrink-0">
                      {isExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                    </span>
                  </div>

                  {isExpanded && (
                    <div className="px-4 py-3 border-t border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 space-y-3">
                      <div className="grid gap-4 lg:grid-cols-3">
                        <ValidationHistoryMetric
                          label="Confidence"
                          value={v.confidence}
                          direction="higher-is-better"
                          threshold={
                            v.resolved_thresholds?.min_confidence ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources
                              ?.min_confidence
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(
                            v,
                            'confidence',
                          )}
                          justification={v.confidence_justification}
                          testId={`task-validation-${v.id}-confidence-score`}
                        />
                        <ValidationHistoryMetric
                          label="Completeness"
                          value={completenessScore}
                          direction="higher-is-better"
                          threshold={
                            v.resolved_thresholds?.min_completeness ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources
                              ?.min_completeness
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(
                            v,
                            'completeness',
                          )}
                          justification={v.completeness_justification}
                          testId={`task-validation-${v.id}-completeness-score`}
                        />
                        <ValidationHistoryMetric
                          label="Drift"
                          value={driftScore}
                          direction="lower-is-better"
                          threshold={
                            v.resolved_thresholds?.max_drift ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources?.max_drift
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(v, 'drift')}
                          justification={v.drift_justification}
                          testId={`task-validation-${v.id}-drift-score`}
                        />
                      </div>

                      {/* Summary */}
                      {summary && (
                        <div className="pt-2 border-t border-gray-200 dark:border-gray-700">
                          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Summary</p>
                          <p className="text-sm text-gray-700 dark:text-gray-300">{summary}</p>
                        </div>
                      )}
                      {(v.threshold_violations?.length || 0) > 0 && (
                        <div className="rounded-md border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-950/20">
                          <p className="text-xs font-semibold text-red-700 dark:text-red-300">
                            Threshold violations
                          </p>
                          <ul className="mt-1 list-disc space-y-1 pl-4 text-xs text-red-700 dark:text-red-300">
                            {v.threshold_violations!.map((violation) => (
                              <li key={violation}>{violation}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                      {(v.completion_gate_failures?.length || 0) > 0 && (
                        <div className="rounded-md border border-amber-200 bg-amber-50 p-3 dark:border-amber-800 dark:bg-amber-950/20">
                          <p className="text-xs font-semibold text-amber-800 dark:text-amber-200">
                            Completion gate failures
                          </p>
                          <ul className="mt-1.5 space-y-2 text-xs text-amber-800 dark:text-amber-200">
                            {v.completion_gate_failures!.map((failure) => (
                              <li key={`${failure.code}:${failure.summary}`}>
                                <span className="font-medium">{failure.summary}</span>
                                {(failure.reason_codes?.length || 0) > 0 && (
                                  <span className="mt-0.5 block text-[11px] text-amber-700 dark:text-amber-300">
                                    {failure.reason_codes!.join(' · ')}
                                  </span>
                                )}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

// Activity Tab Component
function ActivityTab({ cardId, api, revision }: { cardId: string; api: ReturnType<typeof useDashboardApi>; revision: number }) {
  const [logs, setLogs] = useState<ActivityLogEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    api.getCardActivity(cardId)
      .then(value => { if (!cancelled) setLogs(value); })
      .catch(() => { if (!cancelled) { setLogs([]); toast.error('Failed to load activity'); } })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [api, cardId, revision]);

  return <ActivityLogList entries={logs} loading={loading} />;
}

// Markdown renderer with prose styling
function Md({ children, className = '' }: { children: string; className?: string }) {
  return <MarkdownContent content={children} className={className} />;
}

// Mention autocomplete dropdown
function MentionInput({
  value,
  onChange,
  members,
  placeholder,
  multiline = false,
}: {
  value: string;
  onChange: (v: string) => void;
  members: { id: string; name: string }[];
  placeholder: string;
  multiline?: boolean;
}) {
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [filter, setFilter] = useState('');

  const handleChange = (text: string) => {
    onChange(text);
    // Check if user just typed @
    const atMatch = text.match(/@(\w*)$/);
    if (atMatch) {
      setFilter(atMatch[1].toLowerCase());
      setShowSuggestions(true);
    } else {
      setShowSuggestions(false);
    }
  };

  const insertMention = (name: string) => {
    const newVal = value.replace(/@\w*$/, `@${name} `);
    onChange(newVal);
    setShowSuggestions(false);
  };

  const filtered = members.filter((m) => m.name.toLowerCase().includes(filter));

  const InputTag = multiline ? 'textarea' : 'input';

  return (
    <div className="relative">
      <InputTag
        value={value}
        onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => handleChange(e.target.value)}
        placeholder={placeholder}
        className={`w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100 ${multiline ? 'resize-none' : ''}`}
        rows={multiline ? 3 : undefined}
      />
      {showSuggestions && filtered.length > 0 && (
        <div className="absolute z-10 top-full mt-1 w-48 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg shadow-lg max-h-32 overflow-y-auto">
          {filtered.map((m) => (
            <button
              key={m.id}
              onClick={() => insertMention(m.name)}
              className="w-full text-left px-3 py-1.5 text-sm hover:bg-blue-50 dark:hover:bg-blue-900/20"
            >
              @{m.name}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Comments Tab Component
function ChoiceBoardRenderer({
  comment,
  api,
  card,
  setCard,
  members,
  canRespond,
}: {
  comment: Comment;
  api: ReturnType<typeof useDashboardApi>;
  card: Card;
  setCard: (c: Card) => void;
  members: { id: string; name: string }[];
  canRespond: boolean;
}) {
  const isMulti = comment.comment_type === 'multi_choice';
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [freeText, setFreeText] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const toggle = (optId: string) => {
    setSelected(prev => {
      const next = new Set(prev);
      if (isMulti) {
        if (next.has(optId)) next.delete(optId); else next.add(optId);
      } else {
        next.clear();
        next.add(optId);
      }
      return next;
    });
  };

  const handleSubmit = async () => {
    if (selected.size === 0) return;
    setSubmitting(true);
    try {
      const updated = await api.respondToChoice(comment.id, Array.from(selected), freeText || undefined);
      setCard({ ...card, comments: card.comments.map(c => c.id === comment.id ? updated : c) });
      setSelected(new Set());
      setFreeText('');
      toast.success('Response recorded');
    } catch {
      toast.error('Failed to respond');
    } finally {
      setSubmitting(false);
    }
  };

  const responses = comment.responses || [];
  const totalResponses = responses.length;

  return (
    <div className="space-y-2">
      <p className="font-medium text-sm text-gray-800 dark:text-gray-100">{comment.content}</p>
      <p className="text-xs text-gray-400">{isMulti ? 'Select one or more' : 'Select one'}</p>

      {/* Options */}
      <div className="space-y-1.5">
        {(comment.choices || []).map(opt => {
          const votes = responses.filter(r => r.selected.includes(opt.id)).length;
          const pct = totalResponses > 0 ? Math.round((votes / totalResponses) * 100) : 0;
          const isSelected = selected.has(opt.id);

          return (
            <button
              key={opt.id}
              onClick={() => {
                if (canRespond) toggle(opt.id);
              }}
              disabled={!canRespond}
              className={`w-full text-left relative rounded-lg border px-3 py-2 text-sm transition-colors ${
                isSelected
                  ? 'border-blue-400 bg-blue-50 dark:bg-blue-900/30 dark:border-blue-500/50'
                  : 'border-gray-200 dark:border-gray-600 hover:border-gray-300 dark:hover:border-gray-500'
              } disabled:cursor-default`}
            >
              {/* Progress bar background */}
              {totalResponses > 0 && (
                <div
                  className="absolute inset-0 rounded-lg bg-blue-100/50 dark:bg-blue-900/20 transition-all"
                  style={{ width: `${pct}%` }}
                />
              )}
              <div className="relative flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className={`w-4 h-4 rounded-${isMulti ? 'sm' : 'full'} border-2 flex items-center justify-center ${
                    isSelected ? 'border-blue-500 bg-blue-500' : 'border-gray-300 dark:border-gray-500'
                  }`}>
                    {isSelected && <span className="text-white text-[10px]">✓</span>}
                  </span>
                  <span className="text-gray-700 dark:text-gray-200">{opt.label}</span>
                </div>
                {totalResponses > 0 && (
                  <span className="text-xs text-gray-400">{votes} ({pct}%)</span>
                )}
              </div>
            </button>
          );
        })}
      </div>

      {/* Free text */}
      {canRespond && comment.allow_free_text && (
        <input
          type="text"
          value={freeText}
          onChange={e => setFreeText(e.target.value)}
          placeholder="Additional comment (optional)"
          className="w-full px-3 py-1.5 text-sm border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200"
        />
      )}

      {/* Submit */}
      {canRespond && (
        <button
          onClick={handleSubmit}
          disabled={selected.size === 0 || submitting}
          className="btn btn-primary text-sm disabled:opacity-50"
        >
          {submitting ? 'Submitting...' : 'Submit Response'}
        </button>
      )}

      {/* Responses summary */}
      {totalResponses > 0 && (
        <details className="text-xs text-gray-400 dark:text-gray-500">
          <summary className="cursor-pointer hover:text-gray-600">{totalResponses} response(s)</summary>
          <div className="mt-1 space-y-1 pl-2 border-l-2 border-gray-200 dark:border-gray-600">
            {responses.map((r, i) => (
              <div key={i}>
                <span className="font-medium text-gray-600 dark:text-gray-300">
                  {resolveActorName(r.responder_id, members) || r.responder_name}
                </span>
                {': '}
                {r.selected.map(s => (comment.choices || []).find(c => c.id === s)?.label || s).join(', ')}
                {r.free_text && <span className="italic ml-1">"{r.free_text}"</span>}
              </div>
            ))}
          </div>
        </details>
      )}
    </div>
  );
}

function CommentsTab({
  card,
  setCard,
  api,
  members,
  seenStatus,
  canCreate,
  canCreateChoice,
  canRespondToChoice,
}: {
  card: Card;
  setCard: (c: Card) => void;
  api: ReturnType<typeof useDashboardApi>;
  members: { id: string; name: string }[];
  seenStatus: SeenMap;
  canCreate: boolean;
  canCreateChoice: boolean;
  canRespondToChoice: boolean;
}) {
  const [newComment, setNewComment] = useState('');
  const [mode, setMode] = useState<'text' | 'choice' | 'multi_choice'>('text');
  const [choiceOptions, setChoiceOptions] = useState('');
  const [allowFreeText, setAllowFreeText] = useState(false);

  useEffect(() => {
    if (!canCreateChoice && mode !== 'text') setMode('text');
  }, [canCreateChoice, mode]);

  const handleAddComment = async () => {
    if (mode === 'text') {
      if (!newComment.trim()) return;
      try {
        const comment = await api.createComment(card.id, { content: newComment });
        setCard({ ...card, comments: [...card.comments, comment] });
        setNewComment('');
        toast.success('Comment added');
      } catch {
        toast.error('Failed to add comment');
      }
    } else {
      if (!newComment.trim() || !choiceOptions.trim()) return;
      const options = choiceOptions.split('\n').map(s => s.trim()).filter(Boolean);
      if (options.length < 2) {
        toast.error('At least 2 options required');
        return;
      }
      try {
        const comment = await api.createComment(card.id, {
          content: newComment,
          comment_type: mode,
          choices: options.map((label, i) => ({ id: `opt_${i}`, label })),
          allow_free_text: allowFreeText,
        });
        setCard({ ...card, comments: [...card.comments, comment] });
        setNewComment('');
        setChoiceOptions('');
        setMode('text');
        toast.success('Choice board added');
      } catch {
        toast.error('Failed to create choice board');
      }
    }
  };

  return (
    <div className="space-y-4">
      {canCreate && (
        <>
          {/* Mode selector */}
          <div className="flex gap-1 text-xs">
            {([
              ['text', 'Text'],
              ...(canCreateChoice
                ? [
                    ['choice', 'Single Choice'],
                    ['multi_choice', 'Multi Choice'],
                  ] as const
                : []),
            ] as const).map(([m, label]) => (
              <button
                key={m}
                onClick={() => setMode(m)}
                className={`px-2.5 py-1 rounded-md border transition-colors ${
                  mode === m
                    ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-300 dark:border-blue-500/50 text-blue-700 dark:text-blue-300'
                    : 'border-gray-200 dark:border-gray-600 text-gray-500 hover:bg-gray-50 dark:hover:bg-gray-700'
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Input */}
          <div>
            <MentionInput
              value={newComment}
              onChange={setNewComment}
              members={members}
              placeholder={mode === 'text' ? 'Write a comment... (use @ to mention)' : 'Enter the question or prompt...'}
              multiline
            />

            {/* Choice options */}
            {mode !== 'text' && canCreateChoice && (
              <div className="mt-2 space-y-2">
                <textarea
                  value={choiceOptions}
                  onChange={e => setChoiceOptions(e.target.value)}
                  placeholder="Enter options, one per line..."
                  rows={3}
                  className="w-full px-3 py-2 text-sm border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200"
                />
                <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={allowFreeText}
                    onChange={e => setAllowFreeText(e.target.checked)}
                    className="rounded border-gray-300"
                  />
                  Allow free-text response
                </label>
              </div>
            )}

            <div className="flex justify-end mt-2">
              <button onClick={handleAddComment} className="btn btn-primary">
                {mode === 'text' ? 'Comment' : 'Create Choice Board'}
              </button>
            </div>
          </div>
        </>
      )}

      {/* Comments list */}
      <div className="space-y-3">
        {card.comments.map((comment) => (
          <div key={comment.id} className="bg-gray-50 dark:bg-gray-800 rounded-lg p-3 text-gray-700 dark:text-gray-300">
            {/* Author */}
            <div className="flex items-center gap-1.5 mb-1.5">
              <span className="text-xs font-semibold text-gray-600 dark:text-gray-300">
                {resolveActorName(comment.author_id, members)}
              </span>
              <span className="text-xs text-gray-400 dark:text-gray-500">
                {new Date(comment.created_at).toLocaleDateString('en-US', {
                  day: '2-digit',
                  month: 'short',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </span>
            </div>

            {comment.comment_type && comment.comment_type !== 'text' ? (
              <ChoiceBoardRenderer
                comment={comment}
                api={api}
                card={card}
                setCard={setCard}
                members={members}
                canRespond={canRespondToChoice}
              />
            ) : (
              <Md>{comment.content}</Md>
            )}
            <SeenByIndicator itemId={comment.id} seenStatus={seenStatus} />
          </div>
        ))}

        {card.comments.length === 0 && (
          <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-4">
            No comments yet
          </p>
        )}
      </div>
    </div>
  );
}
